local _orig_pui_find = l_pui_0.find
local _orig_pui_create = l_pui_0.create

local _wrap_container
local function _patch_any_element(el)
    if not el or type(el) ~= "table" then return el end
    pcall(function()
        if rawget(el, "callbacks") == nil then
            rawset(el, "callbacks", {})
        end
        if el.callbacks == nil then el.callbacks = {} end
    end)
    local orig_sc = el.set_callback
    if type(orig_sc) == "function" and not el._sc_guarded then
        el._sc_guarded = true
        el.set_callback = function(self, fn, run_now)
            if self and type(self) == "table" then
                pcall(function()
                    if rawget(self, "callbacks") == nil then
                        rawset(self, "callbacks", {})
                    end
                    if self.callbacks == nil then self.callbacks = {} end
                end)
            end
            local ok, res = pcall(orig_sc, self, fn, run_now)
            if not ok then
                pcall(function()
                    if type(self) == "table" and self[1] and type(self[1].set_callback) == "function" then
                        self[1]:set_callback(fn)
                    end
                end)
            end
            return self
        end
    end
    local orig_ov = el.override
    if type(orig_ov) == "function" and not el._ov_guarded then
        el._ov_guarded = true
        el.override = function(self, ...)
            if self and type(self) == "table" then
                pcall(function()
                    if rawget(self, "callbacks") == nil then
                        rawset(self, "callbacks", {})
                    end
                    if self.callbacks == nil then self.callbacks = {} end
                end)
            end
            return orig_ov(self, ...)
        end
    end
    local orig_vis = el.visibility
    if type(orig_vis) == "function" and not el._vis_guarded then
        el._vis_guarded = true
        el.visibility = function(self, ...)
            orig_vis(self, ...)
            return self
        end
    end
    local orig_cr = el.create
    if type(orig_cr) == "function" and not el._cr_guarded then
        el._cr_guarded = true
        el.create = function(self, ...)
            local args = { ... }
            if type(args[1]) == "function" then
                local orig_cb = args[1]
                args[1] = function(gear, ...)
                    local wrapped_gear = _wrap_container(gear)
                    local res = orig_cb(wrapped_gear, ...)
                    if type(res) == "table" then
                        for _, sub_el in pairs(res) do
                            _patch_any_element(sub_el)
                        end
                    end
                    return res
                end
            end
            local sub = orig_cr(self, unpack(args))
            return _wrap_container(sub)
        end
    end
    return el
end

_wrap_container = function(cont)
    if not cont or type(cont) ~= "table" then return cont end
    if rawget(cont, "_elements") == nil then
        rawset(cont, "_elements", {})
    end
    local methods = { "switch", "combo", "slider", "selectable", "button", "label", "list", "listable", "input", "color_picker", "hotkey", "texture" }
    for _, m in ipairs(methods) do
        local orig_m = cont[m]
        if type(orig_m) == "function" and not rawget(cont, "_wrapped_" .. m) then
            pcall(function() rawset(cont, "_wrapped_" .. m, true) end)
            cont[m] = function(self, ...)
                local res = orig_m(self, ...)
                if res and (type(res) == "table" or type(res) == "userdata") then
                    table.insert(self._elements, res)
                end
                return _patch_any_element(res)
            end
        end
    end
    if not rawget(cont, "visibility") then
        cont.visibility = function(self, visible)
            local is_vis = (visible == true)
            self._is_visible = is_vis
            if self._elements then
                for _, el in ipairs(self._elements) do
                    if el and type(el.visibility) == "function" then
                        pcall(el.visibility, el, is_vis)
                    end
                end
            end
            return self
        end
        cont.set_visible = cont.visibility
        cont.get_visible = function(self) return self._is_visible ~= false end
    end
    return cont
end

local function _guard_pui_element(el)
    return _patch_any_element(el)
end

local function _wrap_gear(gear)
    return _wrap_container(gear)
end

l_pui_0.create = function(...)
    local grp = _orig_pui_create(...)
    return _wrap_container(grp)
end

l_pui_0.find = function(...)
    local res = _orig_pui_find(...)
    return _patch_any_element(res)
end

local _orig_pui_setup = l_pui_0.setup;
local function _sanitize_pui_node(node, visited)
    if type(node) ~= "table" then return end
    visited = visited or {}
    if visited[node] then return end
    visited[node] = true

    if node.__name == "pui::element" then
        if type(node[1]) == "table" then
