local function _clean_preset_bots(t)
    if type(t) ~= "table" then return end
    t.warmup_setup = nil
    t["\001\f<fire-flame-curved>\r\tWarmup"] = nil
    t.bot_stop = nil
    t.bot_regen = nil
    t.bot_respawn = nil
    t.kick_bots = nil
    t.bot_place = nil
    t.practice_server = nil
    t.apply = nil
    t.infinite_ammo = nil
    t.grenade_traj = nil
    t.buy_anywhere = nil
    t.auto_on_map = nil
    t.showpos = nil
    for k, v in pairs(t) do
        if type(v) == "table" then
            _clean_preset_bots(v)
        end
    end
end

