            end),
            aim_tools = v167.groups.aimbot:switch("\001\f<crosshairs-simple>\r\tAim Tools", false, function(gear)
                local weapons = { [1] = "Pistols", [2] = "AutoSnipers", [3] = "AWP", [4] = "SSG-08", [5] = "Desert Eagle" }
                local cond_names = { [1] = "Higher than you", [2] = "Lower than you", [3] = "Lethal", [4] = "After X misses", [5] = "HP lower than X" }
                local res = {
                    flag = gear:switch("Draw Flags", false),
                    weapon = gear:combo("Weapon", weapons)
                }
                for _, w in ipairs(weapons) do
                    local pb_c = gear:selectable("Prefer Body Aim##" .. w, cond_names)
                    local pb_m = gear:slider("\tMax Misses##pb_m_" .. w, 1, 10, 2)
                    local pb_h = gear:slider("\tLower HP##pb_h_" .. w, 0, 100, 80)
                    local fs_c = gear:selectable("Force Safe Point##" .. w, cond_names)
                    local fs_m = gear:slider("\tMax Misses##fs_m_" .. w, 1, 10, 2)
                    local fs_h = gear:slider("\tLower HP##fs_h_" .. w, 0, 100, 80)
                    local hc_c = gear:combo("Hit Chance##" .. w, cond_names)
                    local hc_items = {}
                    for _, cn in ipairs(cond_names) do
                        local it = { enabled = gear:switch("\tEnabled##hc_" .. cn .. "_" .. w) }
                        if cn == "After X misses" then it.max_misses = gear:slider("\tMax Misses##hc_m_" .. cn .. "_" .. w, 1, 10, 2) end
                        if cn == "HP lower than X" then it.lower_hp = gear:slider("\tLower HP##hc_h_" .. cn .. "_" .. w, 0, 100, 80) end
                        it.value = gear:slider("\tValue##hc_v_" .. cn .. "_" .. w, 0, 100, 50)
                        hc_items[cn] = it

                        local c_key = cn:gsub("%s+", "_")
                        res["hc_en_" .. c_key .. "_" .. w] = it.enabled
                        if it.max_misses then res["hc_m_" .. c_key .. "_" .. w] = it.max_misses end
                        if it.lower_hp then res["hc_h_" .. c_key .. "_" .. w] = it.lower_hp end
                        res["hc_v_" .. c_key .. "_" .. w] = it.value
                    end
                    local mp_c = gear:combo("Multipoints##" .. w, cond_names)
                    local mp_items = {}
                    for _, cn in ipairs(cond_names) do
                        local it = { enabled = gear:switch("\tEnabled##mp_" .. cn .. "_" .. w) }
                        if cn == "After X misses" then it.max_misses = gear:slider("\tMax Misses##mp_m_" .. cn .. "_" .. w, 1, 10, 2) end
                        if cn == "HP lower than X" then it.lower_hp = gear:slider("\tLower HP##mp_h_" .. cn .. "_" .. w, 0, 100, 80) end
                        it.value = gear:slider("\tValue##mp_v_" .. cn .. "_" .. w, 0, 100, 50)
                        mp_items[cn] = it

                        local c_key = cn:gsub("%s+", "_")
                        res["mp_en_" .. c_key .. "_" .. w] = it.enabled
                        if it.max_misses then res["mp_m_" .. c_key .. "_" .. w] = it.max_misses end
                        if it.lower_hp then res["mp_h_" .. c_key .. "_" .. w] = it.lower_hp end
                        res["mp_v_" .. c_key .. "_" .. w] = it.value
                    end

                    res["pb_cond_" .. w] = pb_c
                    res["pb_m_" .. w] = pb_m
                    res["pb_h_" .. w] = pb_h
                    res["fs_cond_" .. w] = fs_c
                    res["fs_m_" .. w] = fs_m
                    res["fs_h_" .. w] = fs_h
                    res["hc_cond_" .. w] = hc_c
                    res["mp_cond_" .. w] = mp_c

                    res[w] = {
                        [0] = { savable = false, skipsave = true },
                        prefer_body = { [0] = { savable = false, skipsave = true }, conditions = pb_c, max_misses = pb_m, lower_hp = pb_h },
                        force_safe = { [0] = { savable = false, skipsave = true }, conditions = fs_c, max_misses = fs_m, lower_hp = fs_h },
                        hit_chance = { [0] = { savable = false, skipsave = true }, conditions = hc_c, items = hc_items },
                        multipoints = { [0] = { savable = false, skipsave = true }, conditions = mp_c, items = mp_items }
                    }
                end
                return res
            end),
            auto_r8 = v167.groups.aimbot:switch("\001\f<gun>\r\tAuto !r8 / !usp", false, "Automatically types !r8 or !usp in chat on pistol rounds (or every round). For servers with !r8 / !usp give commands.", function(v_r8)
