            clan_tag = v167.groups.other:switch("\v\239\159\170   \rClan Tag Spammer", false, function(ct)
                local mode = ct:combo("\v\f<layer-group>   \rMode", "Presets", "Custom", "Steal from player")
                local preset = ct:combo("\v\f<bookmark>   \rPreset", "caelestis", "onlybaim", "bluhgang", "godeless", "gamesense", "monolith", "primordial", "nemesis", "fatality", "neverlose", "ev0lve", "skeet.cc")
                local text = ct:input("\v\f<pen>   \rText", "caelestis")
                local animate = ct:switch("\v\f<wave-sine>   \rAnimate", true)
                local anim_style = ct:combo("\v\f<wand-magic-sparkles>   \rAnimation style", "Build & Dissolve", "Scroll Marquee", "Evalate Glitch", "Static")
                local speed = ct:slider("\v\f<gauge-high>   \rSpeed", 5, 30, 17, 1, "t")
                local random_case = ct:switch("\v\f<shuffle>   \rRandomize case", false)
                local target_player = ct:combo("\v\f<user-secret>   \rTarget player", "Refresh players...")
                local refresh_players = ct:button("\v\f<arrows-rotate>   \rRefresh player list")

                local function update_clan_deps()
                    local m = mode:get()
                    local is_preset = (m == "Presets")
                    local is_custom = (m == "Custom")
                    local is_steal = (m == "Steal from player")
                    local is_anim = animate:get() and not is_steal

                    preset:visibility(is_preset)
                    text:visibility(is_custom)
                    animate:visibility(not is_steal)
                    anim_style:visibility(is_anim)
                    speed:visibility(is_anim)
                    random_case:visibility(not is_steal)
                    target_player:visibility(is_steal)
                    refresh_players:visibility(is_steal)
                end

                mode:set_callback(update_clan_deps)
                animate:set_callback(update_clan_deps)
                update_clan_deps()

                return {
                    mode = mode,
                    preset = preset,
                    text = text,
                    animate = animate,
                    anim_style = anim_style,
                    speed = speed,
                    random_case = random_case,
                    target_player = target_player,
                    refresh_players = refresh_players
                }
            end),
