            local local_player = entity.get_local_player()
            if not local_player then
                return nil
            end
            if local_player.m_iTeamNum ~= 3 then
                return nil
            end
            if local_player.m_hCarriedHostage ~= nil then
                return nil
            end
            local eye_pos = local_player:get_eye_position()
            if not eye_pos then
                return nil
            end
            local nearest_hostage = nil
            local nearest_dist = 100
