                if not hostage then
                    return
                end
                local hostage_pos = hostage:get_origin()
                if not hostage_pos then
                    return
                end
                local dist = eye_pos:dist(hostage_pos)
                if dist > nearest_dist then
                    return
                end
                nearest_dist = dist
                nearest_hostage = hostage
            end)
            if not nearest_hostage then
                return nil
            end
            local hostage_pos = nearest_hostage:get_origin()
