                return
            end
            if not local_player:is_alive() then
                self:set_use_aa(false)
                self.hostage_use_ticks = 0
                return
            end
            local weapon = local_player:get_player_weapon()
            if not weapon then
                self:set_use_aa(false)
                self.hostage_use_ticks = 0
                return
            end
            
            local should_use = self:should_override_use(local_player, weapon, cmd)
