            end
            
            local weapon_class = weapon:get_classname()
            
            if weapon_class ~= "CC4" then
                if self:is_in_bombzone(local_player) and self:has_c4_in_backpack(local_player) then
                    cmd.in_use = false
                    return true
                end
                return false
            end
            
            -- Для CC4 нужно проверить команду игрока и состояние
            if local_player.m_iTeamNum ~= 2 then
                return false
            end
            
            if not self:is_in_bombzone(local_player) then
                return false
            end
            
            -- Проверяем, нажал ли игрок +use или +attack
            local is_using = cmd.in_use == true or cmd.in_use == 1
            local is_attacking = cmd.in_attack == true or cmd.in_attack == 1
            
            if not is_using and not is_attacking then
                return false
