                local ok = pcall(function()
                    local f_orig = vec_t(origin.x, origin.y, origin.z)
                    local f_mins = vec_t(mins.x, mins.y, mins.z)
                    local f_maxs = vec_t(maxs.x, maxs.y, maxs.z)
                    local f_angs = vec_t(angles.x, angles.y, angles.z)
