        get_icon = function(self, name)
            if self.icon_cache and self.icon_cache[name] then
                return self.icon_cache[name]
            end
            local ic_res = ""
            if ui.get_icon then
                local ok, ic = pcall(ui.get_icon, name)
                if ok and ic and type(ic) == "string" and #ic > 0 then
                    ic_res = ic
                end
            end
            if ic_res == "" and l_pui_0 and l_pui_0.get_icon then
                local ok, ic = pcall(l_pui_0.get_icon, name)
                if ok and ic and type(ic) == "string" and #ic > 0 then
                    if ui.get_icon then
                        local ok2, ic2 = pcall(function() return ic:gsub("\\f<(.-)>", ui.get_icon) end)
                        if ok2 and ic2 then ic_res = ic2 else ic_res = ic end
                    else
                        ic_res = ic
                    end
                end
            end
            if ic_res == "" then
                if name == "link-simple" then ic_res = "\239\131\129"
                elseif name == "glasses-round" then ic_res = "\239\131\147"
                elseif name == "heart" or name == "butterfly" then ic_res = "\239\128\132"
                elseif name == "brackets-curly" then ic_res = "{}"
                end
            end
            if self.icon_cache then
                self.icon_cache[name] = ic_res
            end
            return ic_res
        end,

        calc_width = function(self, font, txt)
            if not txt or txt == "" then return 0 end
            local key = tostring(font) .. ":" .. txt
            local cache = self.width_cache
            if cache and cache[key] then return cache[key] end
            local w = 0
            local ok, res = pcall(render.measure_text, font, "s", txt)
            if ok and res and res.x and res.x > 0 then
                w = res.x
            else
                ok, res = pcall(render.measure_text, font, txt)
                if ok and res and res.x and res.x > 0 then
                    w = res.x
                else
                    ok, res = pcall(render.measure_text, nil, txt)
                    if ok and res and res.x and res.x > 0 then
                        w = res.x
                    else
                        local clean = txt:gsub("\a%x%x%x%x%x%x%x%x", ""):gsub("\a%x%x%x%x%x%x", ""):gsub("\aDEFAULT", "")
                        w = #clean * 7
                    end
                end
            end
            if cache then
                if (self.width_cache_count or 0) > 600 then
                    self.width_cache = {}
                    self.width_cache_count = 0
                    cache = self.width_cache
                end
                cache[key] = w
                self.width_cache_count = (self.width_cache_count or 0) + 1
            end
            return w
        end,

        get_elems = function(self)
            if self.ui_structure and self.ui_structure.other and self.ui_structure.other.elements then
                return self.ui_structure.other.elements
            end
            return nil
        end,

        get_colors = function(self, elems)
            local now = globals.realtime
            if self.cached_colors and self.last_color_update and (now - self.last_color_update < 0.25) and (ui.get_alpha() == 0) then
                return self.cached_colors[1], self.cached_colors[2]
            end
            self.last_color_update = now

            local c_accent = color(116, 166, 169, 255)
            local c_sec = color(255, 255, 255, 255)
            if elems and elems.widgets_accent then
                pcall(function()
                    local cp = elems.widgets_accent
                    local val = cp.value
                    local mode = nil
                    if type(val) == "table" then
                        mode = val[1]
                        local data = val[2]
                        if mode == "Solid" then
                            if type(data) == "userdata" or (type(data) == "table" and data.r) then
                                c_accent = data
                                c_sec = data
                            elseif type(data) == "table" and data[1] then
                                c_accent = data[1]
                                c_sec = data[1]
                            end
                        elseif mode == "Gradient" and type(data) == "table" then
                            c_accent = data[1] or c_accent
                            c_sec = data[2] or c_accent
                        elseif type(data) == "userdata" or (type(data) == "table" and data.r) then
                            c_accent = data
                            c_sec = data
                        end
                    end

                    if not mode then
                        local ok_m, m = pcall(function() return cp:get() end)
                        if ok_m and type(m) == "string" then mode = m end
                    end

                    if mode then
                        local ok_sub, sub = pcall(function() return cp:get(mode) end)
                        if ok_sub and sub then
                            if type(sub) == "userdata" or (type(sub) == "table" and sub.r) then
                                c_accent = sub
                                c_sec = sub
                            elseif type(sub) == "table" then
                                if mode == "Gradient" then
                                    c_accent = sub[1] or c_accent
                                    c_sec = sub[2] or c_accent
                                else
                                    c_accent = sub[1] or sub
                                    c_sec = sub[1] or sub
                                end
                            end
                        end
                    else
                        local ok_raw, raw = pcall(function() return cp:get() end)
                        if ok_raw and raw then
                            if type(raw) == "userdata" or (type(raw) == "table" and raw.r) then
                                c_accent = raw
                                c_sec = raw
                            elseif type(raw) == "table" then
                                c_accent = raw[1] or c_accent
                                c_sec = raw[2] or c_accent
                            end
                        end
                    end
                end)
            end
            self.cached_colors = { c_accent, c_sec }
            return c_accent, c_sec
        end,

        get_style = function(self, elems)
            local now = globals.realtime
            if self.cached_style and self.last_style_update and (now - self.last_style_update < 0.25) and (ui.get_alpha() == 0) then
                return self.cached_style[1], self.cached_style[2], self.cached_style[3], self.cached_style[4]
            end
            self.last_style_update = now

            local is_simple = false
            local blur_on = true
            local alpha_pct = 85
            if elems and elems.widgets_style then
                pcall(function()
                    local st = elems.widgets_style
                    if st.mode then
                        local m = st.mode:get()
                        if m == 2 or (type(m) == "string" and m:find("Simple")) then
                            is_simple = true
                        end
                    end
                    if st.blur then blur_on = (st.blur:get() == true) end
                    if st.bg_alpha then alpha_pct = tonumber(st.bg_alpha:get()) or 85 end
                end)
            end
            local bg_alpha = math.floor((alpha_pct / 100) * 140)
            local capsule_alpha = math.floor((alpha_pct / 100) * 96)
            self.cached_style = { is_simple, blur_on, bg_alpha, capsule_alpha }
            return is_simple, blur_on, bg_alpha, capsule_alpha
        end,

        get_colors_v2 = function(self, elems)
            local now = globals.realtime
            if self.cached_colors_v2 and self.last_color_update_v2 and (now - self.last_color_update_v2 < 0.25) and (ui.get_alpha() == 0) then
                return self.cached_colors_v2[1], self.cached_colors_v2[2]
            end
            self.last_color_update_v2 = now

            local c_accent = color(140, 130, 255, 255)
            local c_sec = color(100, 210, 255, 255)
            if elems and elems.widgets_v2_accent then
                pcall(function()
                    local cp = elems.widgets_v2_accent
                    local val = cp.value
                    local mode = nil
                    if type(val) == "table" then
                        mode = val[1]
                        local data = val[2]
                        if mode == "Solid" then
                            if type(data) == "userdata" or (type(data) == "table" and data.r) then
                                c_accent = data
                                c_sec = data
                            elseif type(data) == "table" and data[1] then
                                c_accent = data[1]
                                c_sec = data[1]
                            end
                        elseif mode == "Gradient" and type(data) == "table" then
                            c_accent = data[1] or c_accent
                            c_sec = data[2] or c_accent
                        elseif type(data) == "userdata" or (type(data) == "table" and data.r) then
                            c_accent = data
                            c_sec = data
                        end
                    end
                    if not mode then
                        local ok_m, m = pcall(function() return cp:get() end)
                        if ok_m and type(m) == "string" then mode = m end
                    end
                    if mode then
                        local ok_sub, sub = pcall(function() return cp:get(mode) end)
                        if ok_sub and sub then
                            if type(sub) == "userdata" or (type(sub) == "table" and sub.r) then
                                c_accent = sub
                                c_sec = sub
                            elseif type(sub) == "table" then
                                if mode == "Gradient" then
                                    c_accent = sub[1] or c_accent
                                    c_sec = sub[2] or c_accent
                                else
                                    c_accent = sub[1] or sub
                                    c_sec = sub[1] or sub
                                end
                            end
                        end
                    else
                        local ok_raw, raw = pcall(function() return cp:get() end)
                        if ok_raw and raw then
                            if type(raw) == "userdata" or (type(raw) == "table" and raw.r) then
                                c_accent = raw
                                c_sec = raw
                            elseif type(raw) == "table" then
                                c_accent = raw[1] or c_accent
                                c_sec = raw[2] or c_accent
                            end
                        end
                    end
                end)
            end
            self.cached_colors_v2 = { c_accent, c_sec }
            return c_accent, c_sec
        end,

        get_style_v2 = function(self, elems)
            local blur_on = true
            local alpha_pct = 90
            if elems and elems.widgets_v2_style then
                pcall(function()
                    local st = elems.widgets_v2_style
                    if st.blur then blur_on = (st.blur:get() == true) end
                    if st.bg_alpha then alpha_pct = tonumber(st.bg_alpha:get()) or 90 end
                end)
            end
            local bg_alpha = math.floor((alpha_pct / 100) * 160)
            return blur_on, bg_alpha
        end,

        draw_rulers = function(self)
            if ui.get_alpha() <= 0 then return end
            local scr = render.screen_size()
            local cx = math.floor(scr.x * 0.5)
            local cy = math.floor(scr.y * 0.5)

            -- 1. Top horizontal snap line at y = 24 across the screen (watermark center snap line)
            if self.active_snap.top_line then
                render.rect(vector(0, 24), vector(scr.x, 25), color(255, 255, 255, 180))
            end

            -- 2. Middle horizontal snap line at y = cy across the screen
            if self.active_snap.mid_y_line then
                render.rect(vector(0, cy), vector(scr.x, cy + 1), color(255, 255, 255, 180))
            end

            -- 3. Bottom horizontal snap line at y = scr.y - 24 across the screen
            if self.active_snap.bot_line then
                render.rect(vector(0, scr.y - 24), vector(scr.x, scr.y - 23), color(255, 255, 255, 180))
            end

            -- 4. Vertical center ruler down the screen (center snap line)
            if self.active_snap.center_line then
                render.rect(vector(cx, 0), vector(cx + 1, scr.y), color(255, 255, 255, 180))
            end
        end,

        handle_drag = function(self, key, pos, size)
            local menu_open = (ui.get_alpha() > 0)
            local st = self.drag_states[key]
            if not st then return pos end
            if not menu_open then
                st.dragging = false
                return pos
            end

            local scr = render.screen_size()
            local cx = math.floor(scr.x * 0.5)
            local cy = math.floor(scr.y * 0.5)

            if key == "crosshair" or key == "crosshair_v2" then
                pos.x = math.floor(cx - size.x * 0.5)
            end

            local mpos = ui.get_mouse_position()
            local is_down = common.is_button_down(1)
            local is_hover = mpos.x >= pos.x and mpos.x <= pos.x + size.x and mpos.y >= pos.y and mpos.y <= pos.y + math.max(size.y, 22)

            if is_down then
                if not st.dragging and is_hover then
                    st.dragging = true
                    st.drag_offset = vector(mpos.x - pos.x, mpos.y - pos.y)
                end
            else
                st.dragging = false
            end

            if key == "crosshair" or key == "crosshair_v2" then
                if st.dragging then
                    pos.y = mpos.y - st.drag_offset.y
                    if math.abs(pos.y - (cy + 28)) < 10 then
                        pos.y = cy + 28
                    end
                end
                pos.x = math.floor(cx - size.x * 0.5)
                pos.y = math.max(cy - 100, math.min(cy + 100 - size.y, pos.y))

                -- Draw full vertical ruler line through the crosshairs while hovering or dragging
                if st.dragging or is_hover then
                    local ruler_alpha = st.dragging and 180 or 100
                    render.rect(vector(cx, 0), vector(cx + 1, scr.y), color(255, 255, 255, ruler_alpha))
                end

                if st.dragging then
                    render.rect(vector(pos.x - 4, pos.y - 4), vector(pos.x + size.x + 4, pos.y + size.y + 4), color(255, 255, 255, 25), 6)
                    render.rect_outline(vector(pos.x - 5, pos.y - 5), vector(pos.x + size.x + 5, pos.y + size.y + 5), color(255, 255, 255, 90), 1, 7)
                elseif is_hover then
                    render.rect(vector(pos.x - 4, pos.y - 4), vector(pos.x + size.x + 4, pos.y + size.y + 4), color(255, 255, 255, 12), 6)
                    render.rect_outline(vector(pos.x - 5, pos.y - 5), vector(pos.x + size.x + 5, pos.y + size.y + 5), color(255, 255, 255, 45), 1, 7)
                end

                return pos
            end

            if st.dragging then
                pos.x = mpos.x - st.drag_offset.x
                pos.y = mpos.y - st.drag_offset.y

                -- Snapping logic matching HY_24 with center alignment
                if key == "watermark" or key == "watermark_v2" then
                    local wm_cx = pos.x + size.x * 0.5
                    local wm_cy = pos.y + size.y * 0.5

                    -- Snap to top guideline at y = 24 (watermark center snaps to the line)
                    if math.abs(wm_cy - 24) < 14 then
                        pos.y = 24 - size.y * 0.5
                        self.active_snap.top_line = true
                    end
                    -- Snap to middle vertical center (cy)
                    if math.abs(wm_cy - cy) < 14 then
                        pos.y = cy - size.y * 0.5
                        self.active_snap.mid_y_line = true
                    end
                    -- Snap to bottom guideline at y = scr.y - 24 (watermark center snaps to the line)
                    if math.abs(wm_cy - (scr.y - 24)) < 14 then
                        pos.y = (scr.y - 24) - size.y * 0.5
                        self.active_snap.bot_line = true
                    end
                    -- Snap to screen center horizontally (cx)
                    if math.abs(wm_cx - cx) < 14 then
                        pos.x = cx - size.x * 0.5
                        self.active_snap.center_line = true
                    end
                    -- Snap to right edge
                    if math.abs((pos.x + size.x) - (scr.x - 24)) < 14 then
                        pos.x = scr.x - size.x - 24
                    end
                    -- Snap to left edge
                    if math.abs(pos.x - 24) < 14 then
                        pos.x = 24
                    end
                elseif key == "keybinds" or key == "spectators" or key == "keybinds_v2" or key == "spectators_v2" or key == "bomb_v2" or key == "velocity_v2" then
                    if math.abs(pos.x - 30) < 14 then
                        pos.x = 30
                    end
                    if math.abs((pos.x + size.x) - (scr.x - 30)) < 14 then
                        pos.x = scr.x - size.x - 30
                    end
                end

                -- Clamp to screen
                pos.x = math.max(0, math.min(scr.x - size.x, pos.x))
                pos.y = math.max(0, math.min(scr.y - size.y, pos.y))

                -- Active drag outline
                render.rect(vector(pos.x - 4, pos.y - 4), vector(pos.x + size.x + 4, pos.y + size.y + 4), color(255, 255, 255, 25), 6)
                render.rect_outline(vector(pos.x - 5, pos.y - 5), vector(pos.x + size.x + 5, pos.y + size.y + 5), color(255, 255, 255, 90), 1, 7)
            elseif is_hover then
                -- Hover outline
                render.rect(vector(pos.x - 4, pos.y - 4), vector(pos.x + size.x + 4, pos.y + size.y + 4), color(255, 255, 255, 12), 6)
                render.rect_outline(vector(pos.x - 5, pos.y - 5), vector(pos.x + size.x + 5, pos.y + size.y + 5), color(255, 255, 255, 45), 1, 7)
            end

            return pos
        end,

        edge_h = function(self, p, w, c1, c2)
            c1 = c1 or color(116, 166, 169, 255)
            c2 = c2 or c1
            if c1 == c2 then
                render.rect(vector(p.x + 4, p.y), vector(p.x + w - 4, p.y + 2), c1)
            else
                render.gradient(vector(p.x + 4, p.y), vector(p.x + w - 4, p.y + 2), c1, c2, c1, c2)
            end
            if self.textures and self.textures.corner_h1 then
                render.texture(self.textures.corner_h1, vector(p.x, p.y), vector(4, 6), c1, "f")
            end
            if self.textures and self.textures.corner_h2 then
                render.texture(self.textures.corner_h2, vector(p.x + w - 4, p.y), vector(4, 6), c2, "f")
            end
        end,

        edge_v = function(self, p, h, c1, c2)
            c1 = c1 or color(116, 166, 169, 255)
            c2 = c2 or c1
            if c1 == c2 then
                render.rect(vector(p.x, p.y + 4), vector(p.x + 2, p.y + h - 4), c1)
            else
                render.gradient(vector(p.x, p.y + 4), vector(p.x + 2, p.y + h - 4), c1, c1, c2, c2)
            end
            if self.textures and self.textures.corner_v1 then
                render.texture(self.textures.corner_v1, vector(p.x, p.y), vector(6, 4), c1, "f")
            end
            if self.textures and self.textures.corner_v2 then
                render.texture(self.textures.corner_v2, vector(p.x, p.y + h - 4), vector(6, 4), c2, "f")
            end
        end,

        side_h = function(self, p1, p2, c_accent, c_sec, blur_on, is_simple, bg_alpha)
            if not is_simple then
                if blur_on and p1 and p2 then
                    pcall(render.blur, p1, p2, 1, 1, { [1] = 4, [2] = 4, [3] = 0, [4] = 0 })
                end
                local bg = color(5, 6, 8, bg_alpha or 140)
                render.rect(p1, p2, bg, { [1] = 4, [2] = 4, [3] = 0, [4] = 0 })
                render.rect(vector(p1.x, p2.y), vector(p2.x, p2.y + 2), bg)
                self:edge_h(vector(p1.x, p2.y), p2.x - p1.x, c_accent, c_sec)
            else
                if blur_on and p1 and p2 then
                    pcall(render.blur, p1, p2, 1, 1, 4)
                end
                render.rect(p1, p2, color(0, 0, 0, bg_alpha or 140), 4)
                self:edge_h(vector(p1.x, p1.y - 1), p2.x - p1.x, c_accent, c_sec)
            end
        end,

        side_v = function(self, p1, p2, c_accent, c_sec, blur_on, bg_alpha)
            if blur_on and p1 and p2 then
                pcall(render.blur, p1, p2, 1, 1, { [1] = 4, [2] = 0, [3] = 0, [4] = 4 })
            end
            local bg = color(5, 6, 8, bg_alpha or 140)
            render.rect(p1, p2, bg, { [1] = 4, [2] = 0, [3] = 0, [4] = 4 })
            render.rect(vector(p2.x, p1.y), vector(p2.x + 2, p2.y), bg)
            self:edge_v(vector(p2.x, p1.y), p2.y - p1.y, c_accent, c_sec)
        end,

        draw_capsule = function(self, p1, p2, blur_on, capsule_alpha)
            render.rect(p1, p2, color(23, 26, 28, capsule_alpha or 96), 4)
        end,

        draw_watermark = function(self, wm_el, c_accent, c_sec, blur_on, is_simple, bg_alpha, capsule_alpha)
            local scr = render.screen_size()
            if not self.drag_states.watermark.pos then
                self.drag_states.watermark.pos = vector(scr.x - 330, 12)
            end
            local pos = self.drag_states.watermark.pos

            local hide_logo = false
            local name_type = "Neverlose"
            local custom_name = "caelestis"
            local time_mode = "24-hour"
            local avatar_mode = "Steam"
            local show_build = true
            local wm_font = "Hysteria"

            if wm_el then
                pcall(function()
                    if wm_el.hide_logo then hide_logo = (wm_el.hide_logo:get() == true) end
                    if wm_el.name_type then name_type = wm_el.name_type:get() end
                    if wm_el.custom_name then custom_name = wm_el.custom_name:get() end
                    if wm_el.time then time_mode = wm_el.time:get() end
                    if wm_el.avatar then avatar_mode = wm_el.avatar:get() end
                    if wm_el.show_build then show_build = (wm_el.show_build:get() == true) end
                    if wm_el.font then wm_font = wm_el.font:get() end
                end)
            end

            local uname = ""
            if name_type == "Steam" then
                if not self._cached_steam_name or (ui.get_alpha() > 0) then
                    pcall(function() self._cached_steam_name = cvar.name:string() or "" end)
                end
                uname = self._cached_steam_name or ""
            elseif name_type == "Custom" then
                uname = custom_name or ""
            else
                if not self._cached_nl_name then
                    pcall(function() self._cached_nl_name = common.get_username() or "" end)
                end
                uname = self._cached_nl_name or ""
            end
            if not uname or uname == "" or uname == "?" then
                uname = "Jesus Christ?"
            end

            local font_reg = self.fonts and (self.fonts.regular_d or self.fonts.regular) or 1
            local font_bold = self.fonts and (self.fonts.bold_d or self.fonts.bold) or 4
            local font_logo = self.fonts and self.fonts.hysteria or font_bold

            if is_simple then
                font_reg = 1
                font_bold = 4
                font_logo = self.fonts and self.fonts.hysteria or font_bold
            elseif wm_font == "Pixel" or wm_font == "4" then
                font_reg = self.fonts and self.fonts.pixel or 2
                font_bold = self.fonts and self.fonts.pixel or 2
                font_logo = font_bold
            elseif wm_font == "Bold" or wm_font == "3" then
                font_reg = self.fonts and (self.fonts.bold_d or self.fonts.bold) or 4
                font_bold = self.fonts and (self.fonts.bold_d or self.fonts.bold) or 4
                font_logo = font_bold
            elseif wm_font == "Italic" or wm_font == "2" then
                font_reg = self.fonts and (self.fonts.regular_d or self.fonts.regular) or 1
                font_bold = self.fonts and (self.fonts.italic or self.fonts.hysteria) or font_bold
                font_logo = self.fonts and (self.fonts.italic or self.fonts.hysteria) or font_bold
            elseif wm_font == "Regular" or wm_font == "Default" or wm_font == "5" then
                font_reg = 1
                font_bold = 4
                font_logo = font_bold
            else
                font_logo = self.fonts and self.fonts.hysteria or font_bold
                font_reg = self.fonts and (self.fonts.regular_d or self.fonts.regular) or 1
                font_bold = self.fonts and (self.fonts.bold_d or self.fonts.bold) or 4
            end
            local c_text = color(240, 240, 240, 255)

            local cur_x = pos.x

            -- 1. Logo capsule (side_v)
            if not hide_logo then
                local hw = self:calc_width(font_logo, "cael")
                local ew = self:calc_width(font_logo, "estis")
                local logo_w = math.max(64, hw + ew + 16)
                local logo_h = 24
                self:side_v(pos, vector(pos.x + logo_w, pos.y + logo_h), c_accent, c_sec, blur_on, bg_alpha)
                render.text(font_logo, vector(pos.x + 8, pos.y + 4), c_accent, "s", "cael")
                render.text(font_logo, vector(pos.x + 8 + hw, pos.y + 4), c_text, "s", "estis")
                cur_x = cur_x + logo_w + 4
            end

            -- 2. User capsule
            if self.local_avatar == nil and avatar_mode ~= "Hidden" then
                local me = entity.get_local_player()
                if me then
                    pcall(function() self.local_avatar = me:get_steam_avatar() end)
                end
            end
            local steam_avatar = (avatar_mode ~= "Hidden") and self.local_avatar or nil
            local curly = self:get_icon("brackets-curly")
            local build_icon = (curly ~= "" and curly) or "{}"
            local build_str = show_build and (" \aFFFFFF40\226\128\148 \a" .. c_accent:to_hex() .. SCRIPT_VERSION_TAG .. " " .. build_icon) or ""
            local user_str = uname .. build_str
            local uw = self:calc_width(font_reg, user_str)
            local user_pill_w = uw + (steam_avatar and 32 or 16)

            self:draw_capsule(vector(cur_x, pos.y + 1), vector(cur_x + user_pill_w, pos.y + 23), blur_on, capsule_alpha)
            if steam_avatar then
                local ok = pcall(function()
                    render.texture(steam_avatar, vector(cur_x + 4, pos.y + 4), vector(16, 16), color(255, 255, 255, 255), nil, 4)
                end)
                if not ok then self.local_avatar = nil end
                render.text(font_reg, vector(cur_x + 24, pos.y + 4), c_text, "s", user_str)
            else
                render.text(font_reg, vector(cur_x + 8, pos.y + 4), c_text, "s", user_str)
            end
            cur_x = cur_x + user_pill_w + 3

            -- 3. Time capsule
            local now = globals.realtime
            if not self._last_wm_time or (now - self._last_wm_time >= 1.0) then
                self._last_wm_time = now
                if time_mode ~= "Off" then
                    self._cached_time_str = common.get_date(time_mode == "12-hour" and "%I:%M %p" or "%H:%M") .. " \aFFFFFF50" .. common.get_date("%A")
                else
                    self._cached_time_str = ""
                end
                local net = utils.net_channel()
                self._cached_ping = net and math.floor(net.latency[1] * 1000) or 0
            end

            if time_mode ~= "Off" and self._cached_time_str and self._cached_time_str ~= "" then
                local time_str = self._cached_time_str
                local tw = self:calc_width(font_reg, time_str)
                local time_pill_w = tw + 18
                self:draw_capsule(vector(cur_x, pos.y + 1), vector(cur_x + time_pill_w, pos.y + 23), blur_on, capsule_alpha)
                render.text(font_reg, vector(cur_x + 8, pos.y + 4), c_text, "s", time_str)
                cur_x = cur_x + time_pill_w + 3
            end

            -- 4. Ping capsule
            local ping = self._cached_ping or 0
            if ping > 5 or (ui.get_alpha() > 0) then
                local ping_str = string.format("%d \aFFFFFF60ms", ping)
                local pw = self:calc_width(font_reg, ping_str)
                local ping_pill_w = pw + 18
                self:draw_capsule(vector(cur_x, pos.y + 1), vector(cur_x + ping_pill_w, pos.y + 23), blur_on, capsule_alpha)
                render.text(font_reg, vector(cur_x + 8, pos.y + 4), c_text, "s", ping_str)
                cur_x = cur_x + ping_pill_w + 3
            end

            local total_w = cur_x - pos.x
            pos = self:handle_drag("watermark", pos, vector(total_w, 24))
            self.drag_states.watermark.pos = pos
        end,

        draw_keybinds = function(self, kb_el, c_accent, c_sec, blur_on, is_simple, bg_alpha, capsule_alpha)
            local scr = render.screen_size()
            if not self.drag_states.keybinds.pos then
                self.drag_states.keybinds.pos = vector(30, scr.y * 0.45)
            end
            local pos = self.drag_states.keybinds.pos
            local menu_open = (ui.get_alpha() > 0)

            local now = globals.realtime
            if not self._last_binds_time or (now - self._last_binds_time > 0.05) or menu_open then
                self._last_binds_time = now
                local binds = {}
                local ok, raw = pcall(ui.get_binds)
                if ok and type(raw) == "table" then
                    for i = 1, #raw do
                        local b = raw[i]
                        if b and b.active then
                            local bname = b.name or ""
                            local mode_str = b.mode
                            local state_tag = "on"
                            if mode_str == "Hold" or mode_str == "holding" then
                                state_tag = "holding"
                            elseif mode_str == "Always" or mode_str == "always" then
                                state_tag = "always"
                            elseif mode_str == "Disabled" or mode_str == "off" then
                                state_tag = "off"
                            end
                            binds[#binds + 1] = { name = bname, tag = state_tag }
                        end
                    end
                end
                local fs_act, ey_act, fs_m, ey_m = get_lua_bind_states()
                local filtered_binds = {}
                for _, b in ipairs(binds) do
                    local n = tostring(b.name or ""):lower()
                    if not n:find("freestand") and not n:find("edge") then
                        table.insert(filtered_binds, b)
                    end
                end
                binds = filtered_binds
                if fs_act then
                    binds[#binds + 1] = { name = "Freestanding", tag = (fs_m == "toggle" and "toggle" or "holding") }
                end
                if ey_act then
                    binds[#binds + 1] = { name = "Edge Yaw", tag = (ey_m == "toggle" and "toggle" or "holding") }
                end
                self._cached_binds = binds
            end

            local binds = self._cached_binds or {}
            if #binds == 0 then
                if menu_open then
                    binds = { { name = "Double tap", tag = "on" } }
                else
                    return
                end
            end

            local font_reg = self.fonts and self.fonts.regular or nil
            local c_text = color(240, 240, 240, 255)

            local max_w = 120
            for i = 1, #binds do
                local b = binds[i]
                local nw = self:calc_width(font_reg, b.name)
                local tw = self:calc_width(font_reg, b.tag)
                local w = nw + tw + 32
                if w > max_w then max_w = w end
            end

            local header_w = max_w
            local header_h = 22
            local total_h = header_h + 6 + (#binds * 23)

            pos = self:handle_drag("keybinds", pos, vector(header_w, total_h))
            self.drag_states.keybinds.pos = pos

            -- Header with glowing bottom line matching HY_24
            self:side_h(pos, vector(pos.x + header_w, pos.y + header_h), c_accent, c_sec, blur_on, is_simple, bg_alpha)
            local ic = self:get_icon("link-simple")
            local header_title = (ic ~= "" and ("\a" .. c_accent:to_hex() .. ic .. "\aDEFAULT  ") or "") .. "Hotkeys"
            render.text(font_reg, vector(pos.x + header_w * 0.5, pos.y + 11), c_text, "c", header_title)

            -- Individual floating pill capsules
            for i = 1, #binds do
                local b = binds[i]
                local item_p1 = vector(pos.x + 4, pos.y + 26 + (i - 1) * 23)
                local item_p2 = vector(pos.x + header_w - 4, item_p1.y + 20)
                self:draw_capsule(item_p1, item_p2, blur_on, capsule_alpha)
                render.text(font_reg, vector(item_p1.x + 6, item_p1.y + 3), c_text, nil, b.name)
                render.text(font_reg, vector(item_p2.x - 6, item_p1.y + 3), color(180, 185, 195, 200), "r", b.tag)
            end
        end,

        draw_spectators = function(self, sp_el, c_accent, c_sec, blur_on, is_simple, bg_alpha, capsule_alpha)
            local scr = render.screen_size()
            if not self.drag_states.spectators.pos then
                self.drag_states.spectators.pos = vector(scr.x - 150, scr.y * 0.45)
            end
            local pos = self.drag_states.spectators.pos

            local now = globals.realtime
            if not self._last_specs_time or (now - self._last_specs_time > 0.25) then
                self._last_specs_time = now
                local specs = {}
                pcall(function()
                    local me = entity.get_local_player()
                    if me then
                        local target = (me:is_alive() and me) or me.m_hObserverTarget
                        if target then
                            local players = entity.get_players(true)
                            if players then
                                self.avatar_cache = self.avatar_cache or {}
                                for i = 1, #players do
                                    local p = players[i]
                                    if p and not p:is_dormant() and not p:is_alive() and p ~= me then
                                        local obs_t = p.m_hObserverTarget
                                        local obs_m = p.m_iObserverMode
                                        if obs_t == target and (obs_m == 4 or obs_m == 5) then
                                            local nick = p:get_name() or "Spectator"
                                            local p_idx = p:get_index()
                                            local av = self.avatar_cache[p_idx]
                                            if not av then
                                                pcall(function() av = p:get_steam_avatar() end)
                                                self.avatar_cache[p_idx] = av
                                            end
                                            specs[#specs + 1] = { name = nick, avatar = av }
                                        end
                                    end
                                end
                            end
                        end
                    end
                end)
                self._cached_specs = specs
            end
            local specs = self._cached_specs or {}

            local font_reg = self.fonts and self.fonts.regular or nil
            local c_text = color(240, 240, 240, 255)

            local max_w = 120
            for i = 1, #specs do
                local w = self:calc_width(font_reg, specs[i].name) + 40
                if w > max_w then max_w = w end
            end

            local header_w = max_w
            local header_h = 22
            local total_h = header_h + (#specs > 0 and (6 + #specs * 23) or 0)

            pos = self:handle_drag("spectators", pos, vector(header_w, total_h))
            self.drag_states.spectators.pos = pos

            -- Header with glowing bottom line matching HY_24
            self:side_h(pos, vector(pos.x + header_w, pos.y + header_h), c_accent, c_sec, blur_on, is_simple, bg_alpha)
            local ic = self:get_icon("glasses-round")
            local count_str = string.format(" \aFFFFFF60(%d)", #specs)
            local header_title = (ic ~= "" and ("\a" .. c_accent:to_hex() .. ic .. "\aDEFAULT  ") or "") .. "Spectators" .. count_str
            render.text(font_reg, vector(pos.x + header_w * 0.5, pos.y + 11), c_text, "c", header_title)

            -- Individual floating pill capsules only if spectators exist
            if #specs > 0 then
                for i = 1, #specs do
                    local s = specs[i]
                    local item_p1 = vector(pos.x + 4, pos.y + 26 + (i - 1) * 23)
                    local item_p2 = vector(pos.x + header_w - 4, item_p1.y + 20)
                    self:draw_capsule(item_p1, item_p2, blur_on, capsule_alpha)
                    render.text(font_reg, vector(item_p1.x + 6, item_p1.y + 3), c_text, nil, s.name)
                    if s.avatar then
                        pcall(function()
                            render.texture(s.avatar, vector(item_p2.x - 18, item_p1.y + 2), vector(16, 16), color(255, 255, 255, 255), nil, 8)
                        end)
                    end
                end
            end
        end,

        draw_crosshair_indicators = function(self, ch_el, c_accent, c_sec, blur_on, is_simple, bg_alpha, capsule_alpha)
            local me = entity.get_local_player()
            if not me or not me:is_alive() then return end

            local scr = render.screen_size()
            local cx = math.floor(scr.x * 0.5)
            local cy = math.floor(scr.y * 0.5)

            if not self.drag_states.crosshair.pos then
                self.drag_states.crosshair.pos = vector(cx, cy + 28)
            end
            local pos = self.drag_states.crosshair.pos
            pos.x = cx

            local font_reg = self.fonts and self.fonts.regular_d or self.fonts and self.fonts.regular or nil
            local font_bold = self.fonts and (self.fonts.bold_d or self.fonts.bold) or nil
            local c_text = color(240, 240, 240, 255)

            local style_mode = "Classic"
            local show_bfly = true
            local font_choice = "Bold"
            pcall(function()
                if ch_el then
                    if ch_el.style then
                        local sm = ch_el.style:get()
                        if sm == 2 or (type(sm) == "string" and sm:find("Mini")) then
                            style_mode = "Mini"
                        else
                            style_mode = "Classic"
                        end
                    end
                    if ch_el.font then font_choice = ch_el.font:get() end
                    if ch_el.butterfly then show_bfly = (ch_el.butterfly:get() == true) end
                end
            end)
            local is_classic = (style_mode == "Classic")

            local ch_font = self.fonts and self.fonts.hysteria or (self.fonts and self.fonts.regular_d) or 1
            local sub_font = self.fonts and (self.fonts.hysteria_sub or self.fonts.regular_sub or self.fonts.small_d) or 1

            if font_choice == "Pixel" or font_choice == "4" then
                ch_font = self.fonts and self.fonts.pixel or 2
                sub_font = self.fonts and (self.fonts.pixel_sub or self.fonts.pixel) or 2
            elseif font_choice == "Bold" or font_choice == "3" then
                ch_font = self.fonts and (self.fonts.bold_d or self.fonts.bold) or 4
                sub_font = self.fonts and (self.fonts.bold_sub or self.fonts.small_d or self.fonts.small) or 1
            elseif font_choice == "Italic" or font_choice == "2" then
                ch_font = self.fonts and (self.fonts.italic or self.fonts.hysteria) or 4
                sub_font = self.fonts and (self.fonts.italic_sub or self.fonts.bold_sub) or 1
            elseif font_choice == "Regular" or font_choice == "Default" or font_choice == "5" then
                ch_font = 1
                sub_font = 1
            else -- "Hysteria" (Authentic HY slanted script)
                ch_font = self.fonts and self.fonts.hysteria or (self.fonts and self.fonts.bold_d) or 4
                sub_font = self.fonts and (self.fonts.hysteria_sub or self.fonts.regular_sub) or 1
            end

            -- Check Double Tap status
            local dt_active = false
            local dt_ref = self._cached_dt_ref
            if not dt_ref then
                dt_ref = v722 and v722.references and v722.references.rage and v722.references.rage.main and v722.references.rage.main.dt
                if not dt_ref and l_pui_0 then
                    pcall(function() dt_ref = l_pui_0.find("Aimbot", "Ragebot", "Main", "Double Tap") end)
                end
                self._cached_dt_ref = dt_ref
            end
            if dt_ref then
                local ok1, ovr = pcall(function() return dt_ref:get_override() end)
                if ok1 and ovr ~= nil then
                    dt_active = (ovr == true)
                else
                    local ok2, val = pcall(function() return dt_ref:get() end)
                    if ok2 then dt_active = (val == true) end
                end
            end

            -- Check Hide Shots (OS) status
            local hs_active = false
            local hs_ref = self._cached_hs_ref
            if not hs_ref then
                hs_ref = v722 and v722.references and v722.references.rage and v722.references.rage.main and v722.references.rage.main.hs
                if not hs_ref and l_pui_0 then
                    pcall(function() hs_ref = l_pui_0.find("Aimbot", "Ragebot", "Main", "Hide Shots") end)
                end
                self._cached_hs_ref = hs_ref
            end
            if hs_ref then
                local ok1, ovr = pcall(function() return hs_ref:get_override() end)
                if ok1 and ovr ~= nil then
                    hs_active = (ovr == true)
                else
                    local ok2, val = pcall(function() return hs_ref:get() end)
                    if ok2 then hs_active = (val == true) end
                end
            end

            -- Lazy load butterfly_s if not yet loaded (attempt only once)
            if not self.textures.butterfly_s and not self.textures.butterfly_s_attempted then
                self.textures.butterfly_s_attempted = true
                pcall(function()
                    local bfly_raw = files.read("caelestis/butterfly.png", true) or files.read("hysteria/butterfly.png", true)
                    if bfly_raw and #bfly_raw > 16 then
                        self.textures.butterfly_s = render.load_image(bfly_raw, vector(64, 64))
                    end
                end)
                if not self.textures.butterfly_s then
                    pcall(function()
                        self.textures.butterfly_s = render.load_image_from_file("caelestis/butterfly.png", vector(64, 64)) or render.load_image_from_file("hysteria/butterfly.png", vector(64, 64))
                    end)
                end
            end

            local chg = 0
            if rage and rage.exploit and rage.exploit.get then
                chg = rage.exploit:get() or 0
            end
            local filled = math.min(6, math.max(0, math.floor(chg * 6 + 0.5)))
            local bar = string.sub("IIIIII", 1, filled) .. "\aFFFFFF60" .. string.sub("IIIIII", filled + 1)
            local dt_dots = "\a" .. c_accent:to_hex() .. bar

            local has_sub = (dt_active or hs_active)

            local total_w = 50
            local tw = 0
            local mini_txt = "CAELESTIS"
            local hw = 0
            local ew = 0
            local cw = 0
            if is_classic then
                hw = self:calc_width(ch_font, "cael")
                ew = self:calc_width(ch_font, "estis")
                cw = hw + ew
                total_w = math.max(50, cw)
            else
                tw = self:calc_width(ch_font, mini_txt)
                total_w = tw + (show_bfly and 12 or 0)
            end

            local total_h = (is_classic and 15 or 14) + (has_sub and 15 or 0)

            local p_drag = vector(cx - total_w * 0.5, pos.y)
            pos = self:handle_drag("crosshair", p_drag, vector(total_w, total_h))
            self.drag_states.crosshair.pos = vector(cx, pos.y)

            -- Render Line 1 (Header/Logo) - completely floating HUD without dark box or bottom border
            if is_classic then
                local ly = pos.y
                if show_bfly and self.textures and self.textures.butterfly_s then
                    local bfly_w = 32
                    local bfly_x = math.floor(pos.x + (total_w - bfly_w) * 0.5)
                    render.texture(self.textures.butterfly_s, vector(bfly_x, ly - 10), vector(bfly_w, 32), c_accent)
                end
                local tx = math.floor(pos.x + (total_w - cw) * 0.5)
                render.text(ch_font, vector(tx, ly), c_accent, "s", "cael")
                render.text(ch_font, vector(tx + hw, ly), c_text, "s", "estis")
            else
                render.text(ch_font, vector(pos.x, pos.y), c_text, "s", mini_txt)
                if show_bfly and self.textures and self.textures.bfly then
                    render.texture(self.textures.bfly, vector(pos.x + tw + 2, pos.y + 3), vector(9, 9), c_accent)
                end
            end

            -- Render Line 2 (Sub-items - ONLY IF ACTIVE, smaller size)
            if dt_active then
                local dt_str = "DT " .. dt_dots
                local dt_w = self:calc_width(sub_font, "DT IIIIII")
                local dt_x = math.floor(pos.x + (total_w - dt_w) * 0.5)
                local dt_y = pos.y + (is_classic and 16 or 15)
                render.text(sub_font, vector(dt_x, dt_y), c_text, "s", dt_str)
            elseif hs_active then
                local os_w = self:calc_width(sub_font, "OS")
                local os_x = math.floor(pos.x + (total_w - os_w) * 0.5)
                local os_y = pos.y + (is_classic and 16 or 15)
                render.text(sub_font, vector(os_x, os_y), c_text, "s", "OS")
            end
        end,

        draw_watermark_v2 = function(self, wm_el, c_accent, c_sec, blur_on, bg_alpha)
            local scr = render.screen_size()
            if not self.drag_states.watermark_v2.pos then
                self.drag_states.watermark_v2.pos = vector(scr.x - 380, 14)
            end
            local pos = self.drag_states.watermark_v2.pos

            local name_type = "Neverlose"
            local custom_name = "caelestis"
            local time_mode = "24-hour"
            local avatar_mode = "Steam"
            local glow = true
            local show_ping = true
            local show_fps = true
            local show_tick = true

            if wm_el then
                pcall(function()
                    if wm_el.name_type then name_type = wm_el.name_type:get() end
                    if wm_el.custom_name then custom_name = wm_el.custom_name:get() end
                    if wm_el.time then time_mode = wm_el.time:get() end
                    if wm_el.avatar then avatar_mode = wm_el.avatar:get() end
                    if wm_el.glow then glow = (wm_el.glow:get() == true) end
                    if wm_el.stats then
                        local st = wm_el.stats:get()
                        if type(st) == "table" then
                            show_ping = false show_fps = false show_tick = false
                            for _, v in ipairs(st) do
                                if v == "Ping" then show_ping = true end
                                if v == "FPS" then show_fps = true end
                                if v == "Tickrate" then show_tick = true end
                            end
                        end
                    end
                end)
            end

            local uname = (name_type == "Steam" and common.get_username()) or (name_type == "Custom" and custom_name) or "caelestis"
            if not uname or uname == "" then uname = "caelestis" end

            local font_bold = self.fonts and (self.fonts.bold_d or self.fonts.bold) or 4
            local font_reg = self.fonts and (self.fonts.regular_d or self.fonts.regular) or 1
            local c_white = color(245, 245, 250, 255)
            local c_dim = color(255, 255, 255, 60)

            local now = globals.realtime
            if not self._last_wm2_time or (now - self._last_wm2_time >= 0.5) then
                self._last_wm2_time = now
                local net = utils.net_channel()
                self._cached_wm2_ping = net and math.floor(net.latency[1] * 1000) or 0
                local rtt = globals.frametime
                self._cached_wm2_fps = (rtt and rtt > 0) and math.floor(1 / rtt) or 60
                local tick = (globals.tickinterval and globals.tickinterval > 0) and math.floor(1 / globals.tickinterval + 0.5) or 64
                self._cached_wm2_tick = tick
                if time_mode ~= "Off" then
                    self._cached_wm2_time = common.get_date(time_mode == "12-hour" and "%I:%M:%S %p" or "%H:%M:%S")
                else
                    self._cached_wm2_time = ""
                end
            end

            local ping_val = self._cached_wm2_ping or 0
            local fps_val = self._cached_wm2_fps or 60
            local tick_val = self._cached_wm2_tick or 64
            local time_str = self._cached_wm2_time or ""

            if self.local_avatar == nil and avatar_mode == "Steam" then
                local me = entity.get_local_player()
                if me then pcall(function() self.local_avatar = me:get_steam_avatar() end) end
            end
            local steam_avatar = (avatar_mode == "Steam") and self.local_avatar or nil

            local title_w = self:calc_width(font_bold, "CAELESTIS ") + self:calc_width(font_bold, "V2")
            local user_w = self:calc_width(font_reg, uname) + (steam_avatar and 22 or 0)
            local ping_w = show_ping and (self:calc_width(font_reg, tostring(ping_val) .. "ms") + 14) or 0
            local fps_w = show_fps and (self:calc_width(font_reg, tostring(fps_val) .. "fps") + 14) or 0
            local tick_w = show_tick and (self:calc_width(font_reg, tostring(tick_val) .. "tick") + 14) or 0
            local time_w = (time_str ~= "") and (self:calc_width(font_reg, time_str) + 14) or 0

            local total_w = 16 + title_w + 14 + user_w + (show_ping and (ping_w + 6) or 0) + (show_fps and (fps_w + 6) or 0) + (show_tick and (tick_w + 6) or 0) + ((time_str ~= "") and (time_w + 6) or 0) + 10
            local total_h = 26

            pos = self:handle_drag("watermark_v2", pos, vector(total_w, total_h))
            self.drag_states.watermark_v2.pos = pos

            local p1 = pos
            local p2 = vector(pos.x + total_w, pos.y + total_h)

            if blur_on then pcall(render.blur, p1, p2, 1, 1, 5) end
            render.rect(p1, p2, color(10, 12, 16, bg_alpha or 160), 5)
            render.rect_outline(p1, p2, color(255, 255, 255, 18), 1, 5)

            render.gradient(vector(p1.x + 2, p1.y), vector(p2.x - 2, p1.y + 2), c_accent, c_sec, c_accent, c_sec)
            if glow then
                local glow_col = color(c_accent.r, c_accent.g, c_accent.b, 25)
                render.rect(vector(p1.x, p1.y - 1), vector(p2.x, p1.y + 6), glow_col, 4)
            end

            local cur_x = p1.x + 10
            local mid_y = p1.y + 5

            render.text(font_bold, vector(cur_x, mid_y), c_accent, "s", "CAELESTIS ")
            local cw = self:calc_width(font_bold, "CAELESTIS ")
            render.text(font_bold, vector(cur_x + cw, mid_y), c_sec, "s", "V2")
            cur_x = cur_x + title_w + 10

            render.text(font_reg, vector(cur_x, mid_y), c_dim, "s", "|")
            cur_x = cur_x + 10

            if steam_avatar then
                render.texture(steam_avatar, vector(cur_x, p1.y + 5), vector(16, 16), color(255, 255, 255, 255), nil, 4)
                cur_x = cur_x + 20
            end
            render.text(font_reg, vector(cur_x, mid_y), c_white, "s", uname)
            cur_x = cur_x + self:calc_width(font_reg, uname) + 10

            if show_ping then
                render.text(font_reg, vector(cur_x, mid_y), c_dim, "s", "|")
                cur_x = cur_x + 8
                local p_str = tostring(ping_val) .. " \aFFFFFF60ms"
                render.text(font_reg, vector(cur_x, mid_y), c_white, "s", p_str)
                cur_x = cur_x + self:calc_width(font_reg, tostring(ping_val) .. " ms") + 10
            end

            if show_fps then
                render.text(font_reg, vector(cur_x, mid_y), c_dim, "s", "|")
                cur_x = cur_x + 8
                local f_str = tostring(fps_val) .. " \aFFFFFF60fps"
                render.text(font_reg, vector(cur_x, mid_y), c_white, "s", f_str)
                cur_x = cur_x + self:calc_width(font_reg, tostring(fps_val) .. " fps") + 10
            end

            if show_tick then
                render.text(font_reg, vector(cur_x, mid_y), c_dim, "s", "|")
                cur_x = cur_x + 8
                local t_str = tostring(tick_val) .. " \aFFFFFF60tick"
                render.text(font_reg, vector(cur_x, mid_y), c_white, "s", t_str)
                cur_x = cur_x + self:calc_width(font_reg, tostring(tick_val) .. " tick") + 10
            end

            if time_str ~= "" then
                render.text(font_reg, vector(cur_x, mid_y), c_dim, "s", "|")
                cur_x = cur_x + 8
                render.text(font_reg, vector(cur_x, mid_y), c_white, "s", time_str)
            end
        end,

        draw_keybinds_v2 = function(self, kb_el, c_accent, c_sec, blur_on, bg_alpha)
            local scr = render.screen_size()
            if not self.drag_states.keybinds_v2.pos then
                self.drag_states.keybinds_v2.pos = vector(30, scr.y * 0.45)
            end
            local pos = self.drag_states.keybinds_v2.pos
            local menu_open = (ui.get_alpha() > 0)

            local show_mode = true
            local glow = true
            if kb_el then
                pcall(function()
                    if kb_el.show_mode then show_mode = (kb_el.show_mode:get() == true) end
                    if kb_el.glow then glow = (kb_el.glow:get() == true) end
                end)
            end

            local binds = {}
            local ok, raw = pcall(ui.get_binds)
            if ok and type(raw) == "table" then
                for i = 1, #raw do
                    local b = raw[i]
                    if b and b.active then
                        local bname = b.name or ""
                        local mode_str = b.mode
                        local tag = "TOGGLE"
                        if mode_str == "Hold" or mode_str == "holding" then tag = "HOLD"
                        elseif mode_str == "Always" or mode_str == "always" then tag = "ALWAYS" end
                        binds[#binds + 1] = { name = bname, tag = tag }
                    end
                end
            end

            local fs_act, ey_act, fs_m, ey_m = get_lua_bind_states()
            if fs_act then
                local exists = false
                for _, b in ipairs(binds) do if b.name and b.name:lower():find("freestand") then exists = true break end end
                if not exists then
                    binds[#binds + 1] = { name = "Freestanding", tag = (fs_m == "toggle" and "TOGGLE" or (fs_m == "always" and "ALWAYS" or "HOLD")) }
                end
            end
            if ey_act then
                local exists = false
                for _, b in ipairs(binds) do if b.name and b.name:lower():find("edge") then exists = true break end end
                if not exists then
                    binds[#binds + 1] = { name = "Edge Yaw", tag = (ey_m == "toggle" and "TOGGLE" or (ey_m == "always" and "ALWAYS" or "HOLD")) }
                end
            end

            local is_preview = false
            if #binds == 0 then
                if menu_open then
                    is_preview = true
                    binds = {
                        { name = "Double Tap", tag = "TOGGLE" },
                        { name = "Hide Shots", tag = "HOLD" },
                        { name = "Auto Peek", tag = "HOLD" }
                    }
                else
                    return
                end
            end

            local font_bold = self.fonts and (self.fonts.bold_d or self.fonts.bold) or 4
            local font_reg = self.fonts and (self.fonts.regular_d or self.fonts.regular) or 1
            local c_white = color(245, 245, 250, 255)

            local max_w = 170
            for i = 1, #binds do
                local bw = self:calc_width(font_reg, binds[i].name) + (show_mode and 60 or 20)
                if bw > max_w then max_w = bw end
            end

            local card_w = max_w + 24
            local card_h = 32 + (#binds * 22) + 6

            pos = self:handle_drag("keybinds_v2", pos, vector(card_w, card_h))
            self.drag_states.keybinds_v2.pos = pos

            local p1 = pos
            local p2 = vector(pos.x + card_w, pos.y + card_h)

            if blur_on then pcall(render.blur, p1, p2, 1, 1, 6) end
            render.rect(p1, p2, color(10, 12, 16, bg_alpha or 160), 6)
            render.rect_outline(p1, p2, color(255, 255, 255, 16), 1, 6)

            render.gradient(vector(p1.x + 3, p1.y), vector(p2.x - 3, p1.y + 2), c_accent, c_sec, c_accent, c_sec)
            if glow then
                render.rect(vector(p1.x, p1.y - 1), vector(p2.x, p1.y + 4), color(c_accent.r, c_accent.g, c_accent.b, 20), 4)
            end

            local count_str = is_preview and " [PREVIEW]" or string.format(" [%d]", #binds)
            render.text(font_bold, vector(p1.x + 12, p1.y + 7), c_accent, "s", "❖")
            render.text(font_bold, vector(p1.x + 26, p1.y + 7), c_white, "s", "Keybinds" .. "\aFFFFFF50" .. count_str)

            render.rect(vector(p1.x + 10, p1.y + 27), vector(p2.x - 10, p1.y + 28), color(255, 255, 255, 16))

            local row_y = p1.y + 33
            for i = 1, #binds do
                local b = binds[i]
                render.text(font_reg, vector(p1.x + 12, row_y), c_white, "s", b.name)
                if show_mode then
                    local tag_w = self:calc_width(font_reg, b.tag) + 10
                    local tag_x = p2.x - 12 - tag_w
                    render.rect(vector(tag_x, row_y - 1), vector(tag_x + tag_w, row_y + 16), color(255, 255, 255, 10), 3)
                    render.text(font_reg, vector(tag_x + 5, row_y), c_accent, "s", b.tag)
                end
                row_y = row_y + 22
            end
        end,

        draw_spectators_v2 = function(self, sp_el, c_accent, c_sec, blur_on, bg_alpha)
            local scr = render.screen_size()
            if not self.drag_states.spectators_v2.pos then
                self.drag_states.spectators_v2.pos = vector(scr.x - 170, scr.y * 0.45)
            end
            local pos = self.drag_states.spectators_v2.pos
            local menu_open = (ui.get_alpha() > 0)

            local show_mode = true
            local show_avatars = true
            if sp_el then
                pcall(function()
                    if sp_el.show_mode then show_mode = (sp_el.show_mode:get() == true) end
                    if sp_el.avatars then show_avatars = (sp_el.avatars:get() == true) end
                end)
            end

            local specs = self._cached_specs or {}
            local is_preview = false
            if #specs == 0 then
                if menu_open then
                    is_preview = true
                    specs = {
                        { name = "Spectator 1", mode = "1ST" },
                        { name = "Spectator 2", mode = "3RD" }
                    }
                else
                    return
                end
            end

            local font_bold = self.fonts and (self.fonts.bold_d or self.fonts.bold) or 4
            local font_reg = self.fonts and (self.fonts.regular_d or self.fonts.regular) or 1
            local c_white = color(245, 245, 250, 255)

            local max_w = 160
            for i = 1, #specs do
                local s_w = self:calc_width(font_reg, specs[i].name) + 60
                if s_w > max_w then max_w = s_w end
            end

            local card_w = max_w + 20
            local card_h = 32 + (#specs * 23) + 6

            pos = self:handle_drag("spectators_v2", pos, vector(card_w, card_h))
            self.drag_states.spectators_v2.pos = pos

            local p1 = pos
            local p2 = vector(pos.x + card_w, pos.y + card_h)

            if blur_on then pcall(render.blur, p1, p2, 1, 1, 6) end
            render.rect(p1, p2, color(10, 12, 16, bg_alpha or 160), 6)
            render.rect_outline(p1, p2, color(255, 255, 255, 16), 1, 6)

            render.gradient(vector(p1.x + 3, p1.y), vector(p2.x - 3, p1.y + 2), c_accent, c_sec, c_accent, c_sec)

            local count_str = is_preview and " [PREVIEW]" or string.format(" [%d]", #specs)
            render.text(font_bold, vector(p1.x + 12, p1.y + 7), c_accent, "s", "◎")
            render.text(font_bold, vector(p1.x + 26, p1.y + 7), c_white, "s", "Spectators" .. "\aFFFFFF50" .. count_str)

            render.rect(vector(p1.x + 10, p1.y + 27), vector(p2.x - 10, p1.y + 28), color(255, 255, 255, 16))

            local row_y = p1.y + 34
            for i = 1, #specs do
                local s = specs[i]
                local cur_rx = p1.x + 12
                if show_avatars and s.avatar then
                    render.texture(s.avatar, vector(cur_rx, row_y), vector(16, 16), color(255, 255, 255, 255), nil, 4)
                    cur_rx = cur_rx + 22
                else
                    render.text(font_reg, vector(cur_rx, row_y), color(255, 255, 255, 120), "s", "•")
                    cur_rx = cur_rx + 12
                end
                render.text(font_reg, vector(cur_rx, row_y), c_white, "s", s.name)

                if show_mode then
                    local mode_tag = s.mode or "1ST"
                    local mw = self:calc_width(font_reg, mode_tag) + 10
                    local mx = p2.x - 12 - mw
                    render.rect(vector(mx, row_y - 1), vector(mx + mw, row_y + 16), color(255, 255, 255, 10), 3)
                    render.text(font_reg, vector(mx + 5, row_y), c_accent, "s", mode_tag)
                end
                row_y = row_y + 23
            end
        end,

        draw_crosshair_v2 = function(self, ch_el, c_accent, c_sec, blur_on, bg_alpha)
            local scr = render.screen_size()
            local cx = math.floor(scr.x * 0.5)
            local cy = math.floor(scr.y * 0.5)

            if not self.drag_states.crosshair_v2.pos then
                self.drag_states.crosshair_v2.pos = vector(cx, cy + 32)
            end
            local pos = self.drag_states.crosshair_v2.pos
            local menu_open = (ui.get_alpha() > 0)

            local show_dt_bar = true
            local glow = true
            if ch_el then
                pcall(function()
                    if ch_el.dt_bar then show_dt_bar = (ch_el.dt_bar:get() == true) end
                    if ch_el.glow then glow = (ch_el.glow:get() == true) end
                end)
            end

            local dt_active = false
            local dt_ref = self._cached_dt_ref
            if not dt_ref and l_pui_0 then
                pcall(function() dt_ref = l_pui_0.find("Aimbot", "Ragebot", "Main", "Double Tap") end)
                self._cached_dt_ref = dt_ref
            end
            if dt_ref then
                local ok, ovr = pcall(function() return dt_ref:get_override() end)
                if ok and ovr ~= nil then dt_active = (ovr == true)
                else local ok2, v = pcall(function() return dt_ref:get() end) if ok2 then dt_active = (v == true) end end
            end

            local hs_active = false
            local hs_ref = self._cached_hs_ref
            if not hs_ref and l_pui_0 then
                pcall(function() hs_ref = l_pui_0.find("Aimbot", "Ragebot", "Main", "Hide Shots") end)
                self._cached_hs_ref = hs_ref
            end
            if hs_ref then
                local ok, ovr = pcall(function() return hs_ref:get_override() end)
                if ok and ovr ~= nil then hs_active = (ovr == true)
                else local ok2, v = pcall(function() return hs_ref:get() end) if ok2 then hs_active = (v == true) end end
            end

            local fs_active = false
            pcall(function()
                if v722 and v722.elements and v722.elements.freestanding_hotkey and v722.elements.freestanding_hotkey:get() then
                    fs_active = true
                end
            end)

            local chg = 0
            if rage and rage.exploit and rage.exploit.get then
                chg = rage.exploit:get() or 0
            end

            local indicators = {}
            if dt_active or (menu_open and not hs_active and not fs_active) then
                local ready = (chg >= 0.95)
                indicators[#indicators + 1] = {
                    tag = "DT",
                    status = ready and "READY" or "CHARGING",
                    col = ready and color(100, 255, 140, 255) or color(255, 180, 50, 255),
                    has_bar = show_dt_bar,
                    bar_val = chg
                }
            end
            if hs_active or (menu_open and #indicators == 0) then
                indicators[#indicators + 1] = { tag = "HS", status = "ACTIVE", col = c_accent }
            end
            if fs_active or (menu_open and #indicators < 2) then
                indicators[#indicators + 1] = { tag = "FS", status = "AUTO", col = c_sec }
            end

            if #indicators == 0 and not menu_open then
                return
            end

            local font_bold = self.fonts and (self.fonts.bold_d or self.fonts.bold) or 4
            local font_reg = self.fonts and (self.fonts.regular_d or self.fonts.regular) or 1
            local c_white = color(245, 245, 250, 255)

            local total_w = 90
            for _, ind in ipairs(indicators) do
                local w = self:calc_width(font_bold, ind.tag) + self:calc_width(font_reg, ind.status) + 30
                if w > total_w then total_w = w end
            end

            local total_h = 20 + (#indicators * 20) + (show_dt_bar and dt_active and 8 or 0)
            local p_drag = vector(cx - total_w * 0.5, pos.y)
            pos = self:handle_drag("crosshair_v2", p_drag, vector(total_w, total_h))
            self.drag_states.crosshair_v2.pos = vector(cx, pos.y)

            local p1 = vector(cx - total_w * 0.5, pos.y)
            local p2 = vector(p1.x + total_w, p1.y + total_h)

            local brand_str = "CAELESTIS " .. "\a" .. c_sec:to_hex() .. "V2"
            render.text(font_bold, vector(cx, p1.y), c_accent, "c", brand_str)

            local ind_y = p1.y + 18
            for _, ind in ipairs(indicators) do
                local ind_p1 = vector(cx - total_w * 0.5, ind_y)
                local ind_p2 = vector(cx + total_w * 0.5, ind_y + 17)
                render.rect(ind_p1, ind_p2, color(12, 14, 18, 140), 3)
                render.rect(vector(ind_p1.x, ind_p1.y), vector(ind_p1.x + 3, ind_p2.y), ind.col, 2)

                render.text(font_bold, vector(ind_p1.x + 8, ind_y + 2), c_white, "s", ind.tag)
                render.text(font_reg, vector(ind_p2.x - 8, ind_y + 2), ind.col, "r", ind.status)

                ind_y = ind_y + 19
                if ind.has_bar and ind.bar_val then
                    local bar_p1 = vector(ind_p1.x + 8, ind_y)
                    local bar_w = total_w - 16
                    render.rect(bar_p1, vector(bar_p1.x + bar_w, bar_p1.y + 3), color(255, 255, 255, 20), 2)
                    local fill_w = math.max(2, math.floor(bar_w * math.min(1.0, math.max(0.0, ind.bar_val))))
                    render.gradient(bar_p1, vector(bar_p1.x + fill_w, bar_p1.y + 3), c_accent, c_sec, c_accent, c_sec)
                    ind_y = ind_y + 7
                end
            end
        end,

        draw_bomb_v2 = function(self, bm_el, c_accent, c_sec, blur_on, bg_alpha)
            local scr = render.screen_size()
            if not self.drag_states.bomb_v2.pos then
                self.drag_states.bomb_v2.pos = vector(30, 90)
            end
            local pos = self.drag_states.bomb_v2.pos
            local menu_open = (ui.get_alpha() > 0)

            local show_defuse = true
            local glow = true
            if bm_el then
                pcall(function()
                    if bm_el.show_defuse then show_defuse = (bm_el.show_defuse:get() == true) end
                    if bm_el.glow then glow = (bm_el.glow:get() == true) end
                end)
            end

            local is_planted = false
            local time_left = 0
            local site_name = "A"
            local defuse_left = nil
            local can_defuse = true
            local dmg_text = nil
            local is_fatal = false

            local game_rules = entity.get_game_rules()
            if game_rules and game_rules.m_bBombPlanted then
                local c4_list = entity.get_entities("CPlantedC4")
                local c4 = c4_list and c4_list[1]
                if c4 and c4.m_bBombTicking and not c4.m_bBombDefused then
                    is_planted = true
                    local curtime = globals.curtime
                    local blow_time = c4.m_flC4Blow or 0
                    time_left = math.max(0, blow_time - curtime)
                    site_name = (c4.m_nBombSite == 1) and "B" or "A"

                    if c4.m_hBombDefuser ~= nil then
                        local def_cd = c4.m_flDefuseCountDown or 0
                        defuse_left = math.max(0, def_cd - curtime)
                        can_defuse = (blow_time >= def_cd)
                    end

                    local me = entity.get_local_player()
                    if me and me:is_alive() then
                        local hp = me.m_iHealth or 100
                        local c4_origin = c4.m_vecOrigin or c4:get_origin()
                        local my_origin = me.m_vecOrigin or me:get_origin()
                        if c4_origin and my_origin then
                            local dist = (c4_origin - my_origin):length()
                            local max_dmg = 500
                            local radius = 1750
                            local est_dmg = math.floor(max_dmg * math.exp(-((dist / radius) ^ 2) * 2.2))
                            if hp <= est_dmg then
                                is_fatal = true
                                dmg_text = "FATAL"
                            elseif est_dmg > 0 then
                                dmg_text = string.format("-%d HP", est_dmg)
                            end
                        end
                    end
                end
            end

            local is_preview = false
            if not is_planted then
                if menu_open then
                    is_preview = true
                    time_left = 34.2
                    site_name = "A"
                    defuse_left = 4.8
                    can_defuse = true
                    dmg_text = "-42 HP"
                else
                    return
                end
            end

            local card_w = 175
            local card_h = (defuse_left and show_defuse) and 70 or 52

            pos = self:handle_drag("bomb_v2", pos, vector(card_w, card_h))
            self.drag_states.bomb_v2.pos = pos

            local p1 = pos
            local p2 = vector(pos.x + card_w, pos.y + card_h)

            local font_bold = self.fonts and (self.fonts.bold_d or self.fonts.bold) or 4
            local font_reg = self.fonts and (self.fonts.regular_d or self.fonts.regular) or 1
            local c_white = color(245, 245, 250, 255)

            local c_urgency = color(255, 80, 80, 255)
            if time_left > 15 then c_urgency = color(100, 240, 140, 255)
            elseif time_left > 7 then c_urgency = color(255, 200, 50, 255) end

            if blur_on then pcall(render.blur, p1, p2, 1, 1, 6) end
            render.rect(p1, p2, color(10, 12, 16, bg_alpha or 160), 6)
            render.rect_outline(p1, p2, color(255, 255, 255, 16), 1, 6)

            render.gradient(vector(p1.x + 3, p1.y), vector(p2.x - 3, p1.y + 2), c_accent, c_sec, c_accent, c_sec)

            render.text(font_bold, vector(p1.x + 12, p1.y + 7), c_urgency, "s", "💣")
            render.text(font_bold, vector(p1.x + 28, p1.y + 7), c_white, "s", "C4 " .. site_name)
            if dmg_text then
                local dmg_col = is_fatal and color(255, 50, 60, 255) or color(255, 210, 80, 255)
                render.text(font_bold, vector(p2.x - 12, p1.y + 7), dmg_col, "r", dmg_text)
            end

            local time_str = string.format("%.1fs", time_left)
            render.text(font_bold, vector(p1.x + 12, p1.y + 26), c_urgency, "s", time_str)

            local bar_pct = math.min(1.0, math.max(0.0, time_left / 40))
            local bar_w = card_w - 70
            local bar_x = p1.x + 58
            local bar_y = p1.y + 31
            render.rect(vector(bar_x, bar_y), vector(bar_x + bar_w, bar_y + 6), color(255, 255, 255, 15), 3)
            render.rect(vector(bar_x, bar_y), vector(bar_x + math.floor(bar_w * bar_pct), bar_y + 6), c_urgency, 3)

            if defuse_left and show_defuse then
                local def_y = p1.y + 48
                local def_col = can_defuse and color(80, 230, 120, 255) or color(255, 50, 60, 255)
                local def_tag = can_defuse and "DEFUSABLE" or "IMPOSSIBLE"
                local def_str = string.format("Defuse: %.1fs", defuse_left)
                render.text(font_reg, vector(p1.x + 12, def_y), c_white, "s", def_str)
                render.text(font_reg, vector(p2.x - 12, def_y), def_col, "r", def_tag)
            end
        end,

        draw_velocity_v2 = function(self, vl_el, c_accent, c_sec, blur_on, bg_alpha)
            local scr = render.screen_size()
            local cx = math.floor(scr.x * 0.5)
            local cy = math.floor(scr.y * 0.5)

            if not self.drag_states.velocity_v2.pos then
                self.drag_states.velocity_v2.pos = vector(cx - 75, cy + 120)
            end
            local pos = self.drag_states.velocity_v2.pos
            local menu_open = (ui.get_alpha() > 0)

            local show_graph = true
            local glow = true
            if vl_el then
                pcall(function()
                    if vl_el.graph then show_graph = (vl_el.graph:get() == true) end
                    if vl_el.glow then glow = (vl_el.glow:get() == true) end
                end)
            end

            local me = entity.get_local_player()
            local cur_speed = 0
            local in_air = false
            if me and me:is_alive() then
                local vel = me.m_vecVelocity
                if vel then
                    cur_speed = math.floor(vel:length2d() + 0.5)
                end
                local flags = me.m_fFlags
                if flags then
                    in_air = (bit.band(flags, 1) == 0)
                end
            elseif menu_open then
                cur_speed = math.floor(250 + math.sin(globals.realtime * 3) * 45)
                in_air = (math.sin(globals.realtime * 3) > 0)
            else
                return
            end

            self._vel_history = self._vel_history or {}
            local hist = self._vel_history
            local now = globals.realtime
            if not self._last_vel_record or (now - self._last_vel_record >= 0.04) then
                self._last_vel_record = now
                hist[#hist + 1] = cur_speed
                if #hist > 28 then table.remove(hist, 1) end
            end

            local card_w = 150
            local card_h = show_graph and 64 or 42

            pos = self:handle_drag("velocity_v2", pos, vector(card_w, card_h))
            self.drag_states.velocity_v2.pos = pos

            local p1 = pos
            local p2 = vector(pos.x + card_w, pos.y + card_h)

            local font_bold = self.fonts and (self.fonts.bold_d or self.fonts.bold) or 4
            local font_reg = self.fonts and (self.fonts.regular_d or self.fonts.regular) or 1
            local c_white = color(245, 245, 250, 255)

            if blur_on then pcall(render.blur, p1, p2, 1, 1, 6) end
            render.rect(p1, p2, color(10, 12, 16, bg_alpha or 160), 6)
            render.rect_outline(p1, p2, color(255, 255, 255, 16), 1, 6)

            render.gradient(vector(p1.x + 3, p1.y), vector(p2.x - 3, p1.y + 2), c_accent, c_sec, c_accent, c_sec)

            local spd_col = (cur_speed >= 250) and c_accent or c_white
            render.text(font_bold, vector(p1.x + 12, p1.y + 6), spd_col, "s", tostring(cur_speed))
            render.text(font_reg, vector(p1.x + 12 + self:calc_width(font_bold, tostring(cur_speed)) + 4, p1.y + 7), color(255, 255, 255, 100), "s", "UPS")

            local state_tag = in_air and "JUMP" or "GROUND"
            local state_col = in_air and c_sec or color(140, 145, 160, 200)
            render.text(font_reg, vector(p2.x - 12, p1.y + 7), state_col, "r", state_tag)

            if show_graph and #hist > 1 then
                local graph_p1 = vector(p1.x + 12, p1.y + 28)
                local graph_w = card_w - 24
                local graph_h = 26
                local step_x = graph_w / 27
                local max_val = 320

                for i = 1, #hist - 1 do
                    local v1 = math.min(max_val, hist[i])
                    local v2 = math.min(max_val, hist[i + 1])
                    local y1 = math.floor(graph_p1.y + graph_h - (v1 / max_val) * graph_h)
                    local y2 = math.floor(graph_p1.y + graph_h - (v2 / max_val) * graph_h)
                    local x1 = math.floor(graph_p1.x + (i - 1) * step_x)
                    local x2 = math.floor(graph_p1.x + i * step_x)

                    render.line(vector(x1, y1), vector(x2, y2), c_accent)
                end
            end
        end,

        init = function(self, ui_structure)
            self.ui_structure = ui_structure
            self:init_assets()
            self.icon_cache = {}
            self.width_cache = {}
            self.width_cache_count = 0

            events.level_init(function()
                self.local_avatar = nil
                self.avatar_cache = {}
                self._cached_specs = {}
                self._cached_steam_name = nil
                self._cached_nl_name = nil
                self.icon_cache = {}
                self.width_cache = {}
                self.width_cache_count = 0
            end)

            local function render_widgets()
                local elems = self:get_elems()
                if not elems then return end

                local has_v1 = (elems.widgets and elems.widgets:get() == true)
                local has_v2 = (elems.widgets_v2 and elems.widgets_v2:get() == true)

                if not has_v1 and not has_v2 then
                    return
                end

                if has_v1 then
                    local c_accent, c_sec = self:get_colors(elems)
                    local is_simple, blur_on, bg_alpha, capsule_alpha = self:get_style(elems)

                    if elems.widgets_watermark and elems.widgets_watermark:get() then
                        self:draw_watermark(elems.widgets_watermark, c_accent, c_sec, blur_on, is_simple, bg_alpha, capsule_alpha)
                    end

                    if elems.widgets_keybinds and elems.widgets_keybinds:get() then
                        self:draw_keybinds(elems.widgets_keybinds, c_accent, c_sec, blur_on, is_simple, bg_alpha, capsule_alpha)
                    end

                    if elems.widgets_spectators and elems.widgets_spectators:get() then
                        self:draw_spectators(elems.widgets_spectators, c_accent, c_sec, blur_on, is_simple, bg_alpha, capsule_alpha)
                    end

                    if elems.widgets_crosshair and elems.widgets_crosshair:get() then
                        self:draw_crosshair_indicators(elems.widgets_crosshair, c_accent, c_sec, blur_on, is_simple, bg_alpha, capsule_alpha)
                    end
                end

                if has_v2 then
