    end,

    rebuild_server_yaw = function(self, enemy, state, layers, side, custom_delta)
        local eye_yaw = (state and state.flEyeYaw) or (enemy.m_angEyeAngles and enemy.m_angEyeAngles.y or 0)
        local vel = enemy.m_vecVelocity or vector(0, 0, 0)
        local speed_2d = vel:length2d()
        local is_in_air = bit.band(enemy.m_fFlags or 0, 1) == 0

        -- Точная серверная формула CCSGOPlayerAnimState::SetUpVelocity для максимального угла десинка
        local walk_to_run = (state and state.flWalkToRunTransition) or (speed_2d > 135 and 1.0 or 0.0)
        local speed_norm = math.max(0.0, math.min(1.0, speed_2d / 260.0))
        local unk_frac = ((walk_to_run * -0.3) - 0.2) * speed_norm + 1.0
        local duck_amt = math.max(0.0, math.min(1.0, (state and state.flDuckAmount) or 0))
        if duck_amt > 0 then
            local crouch_walk = math.max(0.0, math.min(1.0, speed_2d / 88.0))
            unk_frac = unk_frac + (duck_amt * crouch_walk) * (0.5 - unk_frac)
        end

        local base_min = (state and state.flMinBodyYaw and state.flMinBodyYaw ~= 0) and state.flMinBodyYaw or -58.0
        local base_max = (state and state.flMaxBodyYaw and state.flMaxBodyYaw ~= 0) and state.flMaxBodyYaw or 58.0
        local min_body_yaw = base_min * unk_frac
        local max_body_yaw = base_max * unk_frac

        if is_in_air then
            min_body_yaw = math.max(min_body_yaw, -28.0)
            max_body_yaw = math.min(max_body_yaw, 28.0)
        end

        local l3_w, l3_c, _, l3_seq = self:get_layer_data(layers, 3)
        if not is_in_air and speed_2d <= 1.2 and l3_seq ~= 979 and l3_w == 0.0 and l3_c == 0.0 then
            min_body_yaw = math.max(min_body_yaw, -35.0)
            max_body_yaw = math.min(max_body_yaw, 35.0)
        end

        if custom_delta then
            local clamped_custom = math.min(math.abs(custom_delta), math.abs(max_body_yaw))
            min_body_yaw = -clamped_custom
            max_body_yaw = clamped_custom
        end

        local last_update_time = (state and state.flLastUpdateIncrement) or globals.tickinterval
        local lby_target = enemy.m_flLowerBodyYawTarget or eye_yaw
        local networked_abs = (state and state.flGoalFeetYaw) or eye_yaw

        -- Стартуем от целевой стороны и прогоняем через реальное серверное схождение approach()
        local candidate_abs = networked_abs
        if side == -1 then
            candidate_abs = eye_yaw + min_body_yaw
        elseif side == 1 then
            candidate_abs = eye_yaw + max_body_yaw
        elseif side == -2 then
            candidate_abs = eye_yaw
        end

        local eye_diff = self:remainderf(eye_yaw - candidate_abs, 360.0)
        if eye_diff > max_body_yaw then
            candidate_abs = eye_yaw - math.abs(max_body_yaw)
        elseif eye_diff < min_body_yaw then
            candidate_abs = eye_yaw + math.abs(min_body_yaw)
        end
        candidate_abs = self:remainderf(candidate_abs, 360.0)

        local left_ground_h = (state and state.flLeftGroundHeight) or 0
        if speed_2d > 0.1 or math.abs(vel.z) > 100.0 then
            candidate_abs = self:approach(eye_yaw, candidate_abs, ((left_ground_h * 20.0) + 30.0) * last_update_time)
        else
            candidate_abs = self:approach(lby_target, candidate_abs, last_update_time * 100.0)
        end

        return self:normalize_yaw(candidate_abs), math.abs(max_body_yaw)
    end,

    get_enemy_data = function(self, idx)
        if not self.enemies[idx] then
            self.enemies[idx] = {
                missed_shots = 0,
                hits = 0,
                state_memory = {
                    stand  = { misses = 0, side = 1, hits = 0 },
                    move   = { misses = 0, side = 1, hits = 0 },
                    crouch = { misses = 0, side = 1, hits = 0 },
                    air    = { misses = 0, side = 1, hits = 0 }
                },
                cur_move_state = "stand",
                yaw_history = {},
                last_sim_time = 0,
                last_shot_time = 0,
                is_on_shot = false,
                last_origin = nil,
                choked_ticks = 1,
                breaking_lc = false,
                is_defensive = false,
                is_jitter = false,
                jitter_diff = 0,
                avg_jitter_yaw = 0,
                resolved_side = 0,
                resolved_yaw = 0,
                last_detected_side = 1,
                confidence = 100,
                max_rotation = 58,
                stage = "Analyzing",
                bt_valid = true,
                prev_eye_yaw = nil,
                prev_2_yaw = nil,
                is_havoc_flick = false,
                havoc_detected_tick = 0,
                havoc_base_yaw = nil,
                pose_history = {},
                is_pose_loop = false,
                first_repeat_yaw = nil,
                second_repeat_yaw = nil,
                yaw_state_counts = {0, 0},
                has_two_repeating_states = false,
                shoot_state_pref = 1,
                is_roll = false,
                roll_angle = 0,
                is_pitch_spike = false,
                prev_l6_rate = 0,
                prev_l12_weight = 0,
                freestand_side = 0,
                freestand_delta = nil,
                spread_miss_boost = false
            }
        end
        return self.enemies[idx]
    end,

    find_cheat_ref = function(_, name)
        local candidates = {
            {"Aimbot", "Ragebot", "Main", "Enabled", name},
            {"Aimbot", "Ragebot", "Main", name},
            {"Aimbot", "Ragebot", "Accuracy", name},
            {"Aimbot", "Ragebot", "Safety", name},
            {"Aimbot", "Ragebot", "Selection", name}
        }
        for _, path in ipairs(candidates) do
            local ok, item = pcall(ui.find, unpack(path))
            if ok and item ~= nil then return item end
        end
        return nil
    end,

    lock_conflicting_features = function(self, _)
        if not self.refs.override_resolver then
            self.refs.override_resolver = self:find_cheat_ref("Override Resolver")
        end
        if not self.refs.extended_backtrack then
            self.refs.extended_backtrack = self:find_cheat_ref("Extended Backtrack")
        end
        if self.refs.override_resolver then
            pcall(function()
                self.refs.override_resolver:disabled(false)
                self.refs.override_resolver:override()
            end)
        end
        if self.refs.extended_backtrack then
            pcall(function()
                self.refs.extended_backtrack:disabled(false)
                self.refs.extended_backtrack:override()
            end)
        end
    end,

    reset_overrides = function(self)
        if self.safety_overridden then
            if self.refs.safe_points then self.refs.safe_points:override() end
            if self.refs.body_aim then self.refs.body_aim:override() end
            if self.refs.min_damage then self.refs.min_damage:override() end
            self.safety_overridden = false
        end
    end,

    on_net_update = function(self)
        if not globals.is_in_game or not globals.is_connected then return end
        local elem = self.other.elements
        if not elem or not elem.resolver_boost or not elem.resolver_boost:get() then return end

        local me = entity.get_local_player()
        if not me then return end

        self:init_ffi()

        local cur_time = globals.curtime
        local tick_interval = globals.tickinterval
        local me_alive = me:is_alive()
        local me_origin = me_alive and me:get_origin() or nil
        local me_res = me:get_resource()
        local ping = (me_res and me_res.m_iPing) or 0

        local sv_maxunlag = cvar.sv_maxunlag and cvar.sv_maxunlag:float() or 0.2
        local cl_interp = cvar.cl_interp and cvar.cl_interp:float() or 0.031
        local cl_interp_ratio = cvar.cl_interp_ratio and cvar.cl_interp_ratio:float() or 2.0
        local cl_updaterate = cvar.cl_updaterate and cvar.cl_updaterate:float() or 64.0

        local lerp = math.max(cl_interp, cl_interp_ratio / cl_updaterate)
        local fake_lat_sec = (self.refs.fake_latency and self.refs.fake_latency:get() or 0) / 1000.0
        local max_unlag = sv_maxunlag + fake_lat_sec
        local correct_unlag = math.max(0.0, math.min(max_unlag, (ping / 1000.0) + lerp))

        local my_idx = me:get_index()
        local my_team = me.m_iTeamNum
        local force_team = elem.force_teamaimbot and elem.force_teamaimbot:get() == true
        self.enemies[my_idx] = nil

        entity.get_players(true, false, function(enemy)
            if not enemy or enemy == me or not enemy:is_alive() or enemy:is_dormant() then return end
            local idx = enemy:get_index()
            if idx == my_idx or not enemy:is_enemy() or (not force_team and my_team and enemy.m_iTeamNum == my_team) then
                self.enemies[idx] = nil
                return
            end
            pcall(function()
                local idx = enemy:get_index()
                local data = self:get_enemy_data(idx)

                local sim_time = enemy.m_flSimulationTime or 0
                local is_new_packet = (sim_time ~= data.last_sim_time and sim_time > 0)

                local state = self:get_animstate(idx)
                local layers = self:get_animlayers(idx)

                if is_new_packet then
                    local cur_origin = enemy.m_vecOrigin or enemy:get_origin()
                    local cur_velocity = enemy.m_vecVelocity or vector(0, 0, 0)
                    local vel_2d = cur_velocity:length2d()
                    local is_in_air = bit.band(enemy.m_fFlags or 0, 1) == 0
                    local duck_amt = (state and state.flDuckAmount) or (bit.band(enemy.m_fFlags or 0, 4) == 4 and 1 or 0)

                    local move_st = self:classify_move_state(vel_2d, is_in_air, duck_amt)
                    data.cur_move_state = move_st
                    local st_mem = data.state_memory[move_st]

                    -- Check On-Shot Desync Vulnerability (m_fLastShotTime)
                    local wpn = enemy:get_player_weapon()
                    local shot_time = wpn and wpn.m_fLastShotTime or 0
                    data.is_on_shot = (shot_time > data.last_shot_time and math.abs(sim_time - shot_time) <= (tick_interval * 2.5))
                    if shot_time > data.last_shot_time then
                        data.last_shot_time = shot_time
                    end

                    local eye_ang = enemy.m_angEyeAngles or vector(0, 0, 0)
                    local cur_pitch = eye_ang.x or 0
                    local cur_roll = eye_ang.z or 0
                    local cur_eye_yaw = (state and state.flEyeYaw) or eye_ang.y or 0

                    data.is_pitch_spike = (not data.is_on_shot) and (cur_pitch > 89.0 or cur_pitch < -89.0 or (math.abs(cur_pitch) < 10.0 and vel_2d <= 15.0))
                    data.is_roll = (math.abs(cur_roll) > 4.0)
                    data.roll_angle = cur_roll

                    if data.last_sim_time > 0 then
                        local time_diff = sim_time - data.last_sim_time
                        if time_diff < 0 then
                            data.is_defensive = true
                            data.choked_ticks = 1
                        else
                            data.is_defensive = false
                            data.choked_ticks = math.max(1, math.min(64, math.floor(time_diff / tick_interval + 0.5)))
                        end

                        if data.last_origin and cur_origin then
                            local dist_sqr = (cur_origin - data.last_origin):length2dsqr()
                            data.breaking_lc = (dist_sqr > 4096.0)
                        else
                            data.breaking_lc = false
                        end
                    end
                    data.last_sim_time = sim_time
                    data.last_origin = cur_origin

                    -- Circular Vector Average Jitter Decomposition
                    table.insert(data.yaw_history, cur_eye_yaw)
                    if #data.yaw_history > 8 then table.remove(data.yaw_history, 1) end

                    local sin_sum, cos_sum = 0, 0
                    for _, y in ipairs(data.yaw_history) do
                        local r = math.rad(y)
                        sin_sum = sin_sum + math.sin(r)
                        cos_sum = cos_sum + math.cos(r)
                    end
                    local avg_jitter_yaw = self:normalize_yaw(math.deg(math.atan2(sin_sum, cos_sum)))
                    local raw_jitter_diff = self:normalize_yaw(cur_eye_yaw - avg_jitter_yaw)
                    data.avg_jitter_yaw = avg_jitter_yaw
                    data.jitter_diff = math.abs(raw_jitter_diff)
                    data.is_jitter = (data.jitter_diff >= 20.0 and #data.yaw_history >= 3)

                    -- 2-State Repeating Yaw Pattern Engine
                    local norm_yaw = self:normalize_yaw(cur_eye_yaw)
                    if data.first_repeat_yaw and math.abs(self:normalize_yaw(norm_yaw - data.first_repeat_yaw)) <= 20.0 then
                        data.first_repeat_yaw = self:normalize_yaw(data.first_repeat_yaw + self:normalize_yaw(norm_yaw - data.first_repeat_yaw) * 0.25)
                        data.yaw_state_counts[1] = data.yaw_state_counts[1] + 1
                    elseif data.second_repeat_yaw and math.abs(self:normalize_yaw(norm_yaw - data.second_repeat_yaw)) <= 20.0 then
                        data.second_repeat_yaw = self:normalize_yaw(data.second_repeat_yaw + self:normalize_yaw(norm_yaw - data.second_repeat_yaw) * 0.25)
                        data.yaw_state_counts[2] = data.yaw_state_counts[2] + 1
                    elseif not data.first_repeat_yaw then
                        data.first_repeat_yaw = norm_yaw
                        data.yaw_state_counts[1] = 1
                    elseif not data.second_repeat_yaw and math.abs(self:normalize_yaw(norm_yaw - data.first_repeat_yaw)) >= 22.0 then
                        data.second_repeat_yaw = norm_yaw
                        data.yaw_state_counts[2] = 1
                    end
                    if data.first_repeat_yaw and data.second_repeat_yaw then
                        local sep = math.abs(self:normalize_yaw(data.first_repeat_yaw - data.second_repeat_yaw))
                        data.has_two_repeating_states = (sep >= 22.0 and data.yaw_state_counts[1] >= 2 and data.yaw_state_counts[2] >= 2)
                    end

                    -- True Defensive / Havoc Flick Detection
                    local prev_eye_yaw = data.prev_eye_yaw or cur_eye_yaw
                    local prev_2_yaw = data.prev_2_yaw or prev_eye_yaw
                    local cur_yaw_diff = math.abs(self:normalize_yaw(cur_eye_yaw - prev_eye_yaw))
                    local tick_diff_2 = math.abs(self:normalize_yaw(cur_eye_yaw - prev_2_yaw))

                    local is_true_def_spike = (data.is_defensive or data.breaking_lc or data.is_pitch_spike)
                    local is_single_flick = (cur_yaw_diff >= 70.0 and tick_diff_2 <= 18.0 and not data.is_jitter)

                    if (cur_yaw_diff >= 68.0 and is_true_def_spike) or is_single_flick then
                        data.is_havoc_flick = true
                        data.havoc_detected_tick = globals.tickcount
                        if not data.havoc_base_yaw then
                            data.havoc_base_yaw = prev_2_yaw or prev_eye_yaw or avg_jitter_yaw
                        end
                    elseif (globals.tickcount - (data.havoc_detected_tick or 0)) <= 4 then
                        data.is_havoc_flick = true
                    else
                        data.is_havoc_flick = false
                        data.havoc_base_yaw = nil
                    end
                    data.prev_2_yaw = prev_eye_yaw
                    data.prev_eye_yaw = cur_eye_yaw

                    -- Pose Parameter 11 (body_yaw) & Pose Parameter 7 (move_yaw)
                    local pose_11, pose_7 = nil, nil
                    pcall(function()
                        local poses = enemy.m_flPoseParameter
                        if poses then
                            pose_11 = poses[11]
                            pose_7 = poses[7]
                        end
                    end)
                    if pose_11 and type(pose_11) == "number" then
                        table.insert(data.pose_history, pose_11)
                        if #data.pose_history > 8 then table.remove(data.pose_history, 1) end
                        local flips, sum_diff = 0, 0
                        for i = 2, #data.pose_history do
                            local p1, p2 = data.pose_history[i - 1], data.pose_history[i]
                            if (p1 > 0.53 and p2 < 0.47) or (p1 < 0.47 and p2 > 0.53) then flips = flips + 1 end
                            sum_diff = sum_diff + math.abs(p2 - p1)
                        end
                        data.is_pose_loop = ((flips >= 3 or (flips >= 2 and sum_diff > 0.45)) and vel_2d <= 45.0)
                    end

                    -- Unlag Validation
                    local delta_t = correct_unlag - (cur_time - sim_time)
                    local in_unlag_window = (math.abs(delta_t) <= max_unlag) and (sim_time <= cur_time + lerp)
                    data.bt_valid = in_unlag_window and not (data.breaking_lc or data.is_defensive or (is_in_air and vel_2d > 250.0) or data.is_roll or data.is_pitch_spike)

                    -- Dual-Width Freestanding Trace
                    if me_origin and cur_origin and me_alive and vel_2d <= 95.0 then
                        data.freestand_side, data.freestand_delta = self:detect_freestanding(me, enemy, cur_eye_yaw)
                    else
                        data.freestand_side, data.freestand_delta = 0, nil
                    end

                    -- ============================================================
                    -- MULTI-LAYER RESOLVER DECISION ENGINE (v3)
                    -- ============================================================
                    local _, max_rot = self:rebuild_server_yaw(enemy, state, layers, -1)
                    data.max_rotation = is_in_air and math.min(max_rot or 58.0, 35.0) or (max_rot or 58.0)

                    local lby_target = enemy.m_flLowerBodyYawTarget or cur_eye_yaw
                    local goal_feet_yaw = (state and state.flGoalFeetYaw) or cur_eye_yaw
                    local lby_diff = self:normalize_yaw(lby_target - cur_eye_yaw)
                    local feet_eye_delta = self:normalize_yaw(goal_feet_yaw - cur_eye_yaw)

                    local l3_w, l3_c, _, l3_seq = self:get_layer_data(layers, 3)
                    local _, _, l6_rate, _ = self:get_layer_data(layers, 6)
                    local l12_w, _, _, _ = self:get_layer_data(layers, 12)

                    local custom_delta = data.freestand_delta
                    local resolved_by_anim = false

                    -- 0. On-Shot Record Priority
                    if data.is_on_shot then
                        data.resolved_side = 0
                        custom_delta = 0.0
                        data.stage = "On-Shot Record"
                        resolved_by_anim = true
                    end

                    -- 1. Crouch Desync Analysis
                    if not resolved_by_anim and move_st == "crouch" then
                        local cr_diff = self:normalize_yaw(lby_target - goal_feet_yaw)
                        if math.abs(cr_diff) >= 3.5 then
                            data.resolved_side = (cr_diff > 0) and 1 or -1
                            data.stage = "Crouch Desync"
                            resolved_by_anim = true
                        end
                    end

                    -- 2. Standing Layer 3 (Sequence 979 vs Low-Delta)
                    if not resolved_by_anim and move_st == "stand" then
                        if l3_seq == 979 and (l3_w > 0.001 or (l3_c > 0.001 and l3_c < 0.99)) then
                            data.resolved_side = (lby_diff >= 0) and -1 or 1
                            data.stage = "L3 Balance 979"
                            resolved_by_anim = true
                        elseif l3_w == 0.0 and math.abs(lby_diff) <= 35.0 then
                            custom_delta = 29.0
                            data.max_rotation = 29.0
                            if data.freestand_side ~= 0 then
                                data.resolved_side = data.freestand_side
                                data.stage = "Edge Low-Delta"
                                resolved_by_anim = true
                            end
                        end
                    end

                    -- 3. Moving Pose 7 (move_yaw) + Layer 6 + Layer 12 Acceleration
                    if not resolved_by_anim and move_st == "move" then
                        local move_dir_yaw = math.deg(math.atan2(cur_velocity.y, cur_velocity.x))
                        local rate_delta = math.abs(l6_rate - (data.prev_l6_rate or l6_rate))
                        local lean_delta = math.abs(l12_w - (data.prev_l12_weight or l12_w))
                        data.prev_l6_rate = l6_rate
                        data.prev_l12_weight = l12_w

                        if pose_7 and type(pose_7) == "number" then
                            local move_yaw_deg = (pose_7 * 360.0) - 180.0
                            local srv_feet_yaw = self:normalize_yaw(move_dir_yaw - move_yaw_deg)
                            local srv_delta = self:normalize_yaw(srv_feet_yaw - cur_eye_yaw)
                            if math.abs(srv_delta) >= 10.0 then
                                data.resolved_side = (srv_delta > 0) and 1 or -1
                                data.stage = "Move Pose 7"
                                resolved_by_anim = true
                            end
                        end

                        if not resolved_by_anim then
                            if math.abs(feet_eye_delta) >= 12.0 then
                                data.resolved_side = (feet_eye_delta > 0) and 1 or -1
                                data.stage = "Move Layer 6"
                                resolved_by_anim = true
                            elseif l12_w > 0.01 and (rate_delta > 0.0004 or lean_delta > 0.01) then
                                local move_feet_diff = self:normalize_yaw(goal_feet_yaw - move_dir_yaw)
                                data.resolved_side = (move_feet_diff >= 0) and 1 or -1
                                data.stage = "Move Lean L12"
                                resolved_by_anim = true
                            elseif data.freestand_side ~= 0 then
                                data.resolved_side = data.freestand_side
                                data.stage = "Move Edge Trace"
                                resolved_by_anim = true
                            end
                        end
                    end

                    -- 4. Pose Parameter 11 & Dual-Ray Freestanding
                    if not resolved_by_anim then
                        if pose_11 and not data.is_pose_loop and (pose_11 > 0.57 or pose_11 < 0.43) then
                            data.resolved_side = (pose_11 > 0.5) and 1 or -1
                            data.stage = "Pose 11"
                            resolved_by_anim = true
                        elseif data.freestand_side ~= 0 then
                            data.resolved_side = data.freestand_side
                            data.stage = "Dual-Ray Edge"
                            resolved_by_anim = true
                        else
                            data.resolved_side = st_mem.side
                            data.stage = "State Memory (" .. move_st:upper() .. ")"
                        end
                    end

                    -- 5. Jitter Center Axis & 2-State Pattern
                    if data.is_jitter and not data.is_on_shot then
                        if data.has_two_repeating_states then
                            local target_state_yaw = (data.shoot_state_pref == 1) and data.first_repeat_yaw or data.second_repeat_yaw
                            local st_delta = self:normalize_yaw((target_state_yaw or cur_eye_yaw) - cur_eye_yaw)
                            data.resolved_side = (st_delta >= 0) and 1 or -1
                            data.stage = "2-State Jitter"
                        else
                            local raw_diff = self:normalize_yaw(cur_eye_yaw - data.avg_jitter_yaw)
                            data.resolved_side = (raw_diff >= 0) and -1 or 1
                            data.stage = "Jitter Axis (" .. math.floor(data.jitter_diff) .. "\194\176)"
                        end
                    end

                    -- 6. Roll AA
                    if data.is_roll and not data.is_on_shot then
                        data.resolved_side = (data.roll_angle > 0) and 1 or -1
                        data.stage = "Roll AA (" .. string.format("%.0f\194\176", data.roll_angle) .. ")"
                    end

                    -- 7. Anti-Flick Base (only when state misses == 0)
                    if data.is_havoc_flick and st_mem.misses == 0 and not data.is_on_shot then
                        local base_y = data.havoc_base_yaw or data.avg_jitter_yaw or cur_eye_yaw
                        local flick_delta = self:normalize_yaw(base_y - cur_eye_yaw)
                        data.resolved_side = (flick_delta >= 0) and 1 or -1
                        data.stage = "Anti-Flick Base"
                    end

                    if st_mem.misses == 0 and (data.resolved_side == 1 or data.resolved_side == -1) then
                        st_mem.side = data.resolved_side
                        data.last_detected_side = data.resolved_side
                    end

                    -- 8. Per-State 5-Stage Bruteforce
                    if st_mem.misses > 0 and not data.is_on_shot then
                        local base_s = (st_mem.side == 1) and 1 or -1
                        local m_step = ((st_mem.misses - 1) % 4) + 1
                        if m_step == 1 then
                            data.resolved_side = -base_s
                            data.stage = string.format("Brute [%s:1] Invert", move_st:sub(1, 1):upper())
                        elseif m_step == 2 then
                            data.resolved_side = base_s
                            custom_delta = 28.0
                            data.max_rotation = 28.0
                            data.stage = string.format("Brute [%s:2] Low 28\194\176", move_st:sub(1, 1):upper())
                        elseif m_step == 3 then
                            data.resolved_side = -base_s
                            custom_delta = 28.0
                            data.max_rotation = 28.0
                            data.stage = string.format("Brute [%s:3] Inv 28\194\176", move_st:sub(1, 1):upper())
                        else
                            data.resolved_side = 0
                            custom_delta = 0.0
                            data.stage = string.format("Brute [%s:4] Center", move_st:sub(1, 1):upper())
                        end
                    end

                    data.resolved_yaw, data.max_rotation = self:rebuild_server_yaw(enemy, state, layers, data.resolved_side, custom_delta)

                    local conf = 92
                    if resolved_by_anim then conf = 100 end
                    if st_mem.hits > 0 and st_mem.misses == 0 then conf = 100 end
                    if data.is_jitter then conf = conf - 10 end
                    if data.breaking_lc or data.is_defensive then conf = conf - 25 end
                    if data.is_roll then conf = conf - 20 end
                    conf = conf - (st_mem.misses * 20)
                    data.confidence = math.max(10, math.min(100, conf))

                    -- Применяем коррекцию строго на новом сетевом пакете и синхронизируем знак pose[11] с flGoalFeetYaw
                    local should_apply = not (move_st == "move" and vel_2d > 135.0 and st_mem.misses == 0 and not data.is_jitter)
                    if state and data.resolved_yaw and should_apply and (data.confidence >= 65 or st_mem.misses > 0) then
                        state.flGoalFeetYaw = data.resolved_yaw
                        pcall(function()
                            local poses = enemy.m_flPoseParameter
                            if poses then
                                -- В Source Engine body_yaw (pose 11) = normalize(flEyeYaw - flGoalFeetYaw) / 116 + 0.5
                                local eye_foot_delta = self:normalize_yaw(cur_eye_yaw - data.resolved_yaw)
                                local norm_pose = 0.5 + math.max(-0.5, math.min(0.5, eye_foot_delta / 116.0))
                                poses[11] = math.max(0.0, math.min(1.0, norm_pose))
                            end
                        end)
                    end
                end
            end)
        end)
    end,

    update = function(self, _)
        if not globals.is_in_game or not globals.is_connected then return end
        local elem = self.other.elements
        if not elem or not elem.resolver_boost or not elem.resolver_boost:get() then
            self:reset_overrides()
            self:lock_conflicting_features(false)
            return
        end

        local aim_tools_on = elem.aim_tools and elem.aim_tools:get()

        local me = entity.get_local_player()
        if not me or not me:is_alive() then
            if not aim_tools_on then self:reset_overrides() end
            return
        end

        local threat = entity.get_threat and entity.get_threat()
        if not threat or not threat:is_alive() or threat:is_dormant() then
            if not aim_tools_on then self:reset_overrides() end
            return
        end

        local data = self:get_enemy_data(threat:get_index())
        local st_mem = data.state_memory[data.cur_move_state or "stand"]
        local enemy_hp = threat.m_iHealth or 100
        local is_in_air = bit.band(threat.m_fFlags or 0, 1) == 0

        local need_baim = false
        local need_safepoints = false
        local force_baim_override = nil
        local force_sp_override = nil

        if enemy_hp <= 42 then
            need_baim = true
            need_safepoints = true
        end

        -- Если был миссматч по урону или враг джиттерит — зажимаем Safe Points, чтобы исключить прострел края руки/плеча
        if st_mem.misses >= 1 or data.spread_miss_boost or data.mismatch_boost or data.is_jitter then
            need_safepoints = true
            if data.mismatch_boost and st_mem.misses >= 1 then
                force_sp_override = "Force"
            end
        end
        if st_mem.misses >= 2 or (data.mismatch_boost and enemy_hp <= 70) then
            need_baim = true
        end

        if not data.bt_valid or data.breaking_lc or data.is_defensive or is_in_air then
            need_safepoints = true
            if data.breaking_lc then need_baim = true end
        end

        if data.is_roll or data.is_pitch_spike then
            need_safepoints = true
            force_sp_override = "Force"
            if st_mem.misses >= 1 then
                need_baim = true
                force_baim_override = "Prefer"
            end
        end

        if data.is_havoc_flick then
            need_safepoints = true
            force_sp_override = (st_mem.misses >= 1) and "Force" or "Prefer"
            if enemy_hp <= 55 or st_mem.misses >= 2 then
                need_baim = true
                force_baim_override = "Prefer"
            end
        end

        if not aim_tools_on then
            if need_baim then
                if self.refs.body_aim then self.refs.body_aim:override(force_baim_override or "Prefer") end
            elseif self.refs.body_aim then
                self.refs.body_aim:override()
            end

            if need_safepoints then
                local sp_mode = force_sp_override or (st_mem.misses >= 2 and "Force" or "Prefer")
                if self.refs.safe_points then self.refs.safe_points:override(sp_mode) end
            elseif self.refs.safe_points then
                self.refs.safe_points:override()
            end
        end

        -- Никогда не сбрасываем и не перезаписываем пользовательский Min. Damage (чтобы не стрелять в крайние мультипоинты)
        self.safety_overridden = (need_baim or need_safepoints)
    end,

    on_aim_ack = function(self, ctx)
        if not ctx or not ctx.target then return end
        local elem = self.other.elements
        if not elem or not elem.resolver_boost or not elem.resolver_boost:get() then return end

        local idx = ctx.target:get_index()
        local data = self:get_enemy_data(idx)
        local st_mem = data.state_memory[data.cur_move_state or "stand"]

        if ctx.state == nil then
            local wanted = tonumber(ctx.wanted_damage) or 0
            local actual = tonumber(ctx.damage) or wanted
            local wanted_hg = ctx.wanted_hitgroup
            local actual_hg = ctx.hitgroup

            -- Детект миссматча: если чит хотел выбить намного больше урона или попал в руку/ногу вместо груди/живота/головы
            local is_mismatch = (wanted > 0 and (wanted - actual) >= 18) or (wanted_hg ~= nil and actual_hg ~= nil and wanted_hg ~= actual_hg and (actual_hg >= 4 and actual_hg <= 7))

            if is_mismatch then
                data.mismatch_boost = true
                -- Если миссматч сильный (> 30 HP разницы), значит реальная моделька стояла под меньшим углом (Low-Delta) или на противоположной стороне
                if (wanted - actual) >= 30 then
                    data.freestand_delta = 28.0
                end
            else
                data.mismatch_boost = false
                data.missed_shots = 0
                st_mem.misses = 0
                st_mem.hits = st_mem.hits + 1
                data.hits = data.hits + 1
                data.bt_valid = true
                data.spread_miss_boost = false
                if data.resolved_side == 1 or data.resolved_side == -1 then
                    st_mem.side = data.resolved_side
                    data.last_detected_side = data.resolved_side
                end
            end
        else
            local reason = tostring(ctx.state):lower()
            local is_resolver_miss = (reason == "correction" or reason == "resolver" or reason == "misprediction" or reason == "?" or reason == "backtrack failure")
            if is_resolver_miss then
                data.missed_shots = data.missed_shots + 1
                st_mem.misses = st_mem.misses + 1
                data.bt_valid = false
                data.mismatch_boost = true
                if data.has_two_repeating_states then
                    data.shoot_state_pref = (data.shoot_state_pref == 1) and 2 or 1
                end
            elseif reason == "spread" or reason == "prediction error" then
                data.spread_miss_boost = true
            end
        end
    end,

    draw_indicator = function(self)
        if not globals.is_in_game or not globals.is_connected then return end
        local elem = self.other.elements
        if not elem or not elem.resolver_boost or not elem.resolver_boost:get() then return end
        if elem.resolver_boost.draw_text and not elem.resolver_boost.draw_text:get() then return end

        local me = entity.get_local_player()
        if not me then return end
        local my_idx = me:get_index()
        local my_team = me.m_iTeamNum
        local force_team = elem.force_teamaimbot and elem.force_teamaimbot:get() == true

        for idx, data in pairs(self.enemies) do
            if idx == my_idx then
                self.enemies[idx] = nil
            elseif data and data.stage and data.stage ~= "Analyzing" then
                local ent = entity.get(idx)
                if not ent or ent == me or not ent:is_player() or not ent:is_enemy() or (not force_team and my_team and ent.m_iTeamNum == my_team) then
                    self.enemies[idx] = nil
                elseif ent:is_alive() and not ent:is_dormant() then
                    local bbox = ent:get_bbox()
                    if bbox and bbox.pos1 and bbox.pos2 and bbox.alpha and bbox.alpha > 0 then
                        local pos_x = (bbox.pos1.x + bbox.pos2.x) * 0.5
                        local pos_y = bbox.pos2.y + 2
                        local hs_chance = math.floor((data.confidence or 0) + 0.5)

                        local side_str = data.resolved_side == 1 and " [R]" or (data.resolved_side == -1 and " [L]" or " [C]")
                        local res_text = string.format("%s%s (%d%%)", data.stage, side_str, hs_chance)
                        local alpha = math.floor(220 * bbox.alpha)
                        local col = hs_chance >= 90 and color(100, 255, 140, alpha)
                                 or (hs_chance >= 65 and color(140, 205, 255, alpha)
                                 or (hs_chance >= 40 and color(255, 200, 80, alpha) or color(255, 100, 100, alpha)))

                        render.text(1, vector(pos_x, pos_y), col, "c", res_text)
                    end
                end
            end
        end
    end,

    init = function(self)
        self:init_ffi()
        self.refs.override_resolver = self:find_cheat_ref("Override Resolver")
        self.refs.extended_backtrack = self:find_cheat_ref("Extended Backtrack")

        local elem = self.other.elements
        if elem and elem.resolver_boost then
            elem.resolver_boost:set_callback(function(item)
                if item:get() then
                    self:lock_conflicting_features(true)
                else
                    self:lock_conflicting_features(false)
                    self:reset_overrides()
                end
            end, true)
        end

        events.net_update_end(function() self:on_net_update() end)
        events.createmove(function(cmd) self:update(cmd) end)
        events.aim_ack(function(ctx) self:on_aim_ack(ctx) end)
        events.render(function() self:draw_indicator() end)

        events.player_death(function(e)
            local vic = entity.get(e.userid, true)
            if vic then self.enemies[vic:get_index()] = nil end
        end)

        events.level_init(function()
            self.enemies = {}
            self:reset_overrides()
        end)

        events.round_start(function()
            for _, d in pairs(self.enemies) do
                d.bt_valid = true
                d.is_havoc_flick = false
                d.spread_miss_boost = false
                d.is_on_shot = false
            end
            self:reset_overrides()
        end)

        events.shutdown(function()
            self:lock_conflicting_features(false)
            self:reset_overrides()
        end)
    end
