                        elseif type(target) == "userdata" and cur and cur.x and target.x then
                            cur = vector(cur.x + (target.x - cur.x) * dt, cur.y + (target.y - cur.y) * dt, (cur.z or 0) + ((target.z or 0) - (cur.z or 0)) * dt)
