            end
            if type(val) == "boolean" then val = val and 1 or 0 end
            if self.smooth_map[key] == nil then
                self.smooth_map[key] = self.smoothy_lib.new(val)
            end
            local res = self.smooth_map[key](spd or 0.05, val)
            if min_v ~= nil and max_v ~= nil and type(res) == "number" then
                return math.max(min_v, math.min(max_v, res))
