            local w_cont = type(content_txt) == "string" and (render.measure_text(font_content, flg, content_txt).x + 15 * sc) or (type(content_txt) == "number" and content_txt or 0)
            w_title = math.floor(w_title)
            w_cont = math.floor(w_cont)
            local slant = 5 * sc
            local gap = 2 * sc
            local rnd = 4 * sc
            local a = col.a
            local bg_col = color(20, 20, 20, a * 0.5)
            local bar_sz = (vector(4, 19) * sc):floor()
            local bar_in = math.floor(3 * sc)
            local y = bar_sz.y
            local total_sz = vector(w_title + w_cont + (w_title > 0 and (slant + gap) or 0), y)

            if pos == nil then
                pos = vector(scr.x - (total_sz.x + 15), 10)
            elseif type(pos) == "table" and pos[2] == true then
                pos = pos[1] - total_sz / 2
