            local half_y = y / 2
            local sh_h = 3 * sc
            ev_shadow(pos + vector(0, half_y - sh_h), pos + vector(0, half_y + sh_h), col, 30 * sc)
            ev_shadow(pos + vector(total_sz.x, half_y - sh_h), pos + vector(total_sz.x, half_y + sh_h), col, 30 * sc)

            if is_blur_on() then
                render.rect(pos - vector(bar_sz.x + 1 - bar_in, 0), pos + bar_sz - vector(bar_sz.x + 1 - bar_in, 0), col, { rnd, 0, rnd, 0 })
                render.rect(pos + vector(total_sz.x - bar_in + 1, 0), pos + vector(total_sz.x - bar_in + 1, 0) + bar_sz, col, { 0, rnd, 0, rnd })
            end

            ev_blur(pos, pos + total_sz, 1, col.a / 255, rnd)

            if w_title > 0 then
                render.rect(pos, pos + vector(w_title, y), bg_col, { rnd, 0, rnd, 0 })
