                -- 8. Manual Arrows
                local ev_arr = ev_on and elems.evalate_arrows and elems.evalate_arrows:get() == true
                if elems.manual_arrows then
                    if ev_arr and elems.manual_arrows:get() then elems.manual_arrows:set(false) end
                    elems.manual_arrows:disabled(ev_arr)
                end

                -- 9. Side Indicators & Gamesense Indicators
                local ev_side = ev_on and elems.evalate_side and elems.evalate_side:get() == true
                if elems.side_indicators then
                    if ev_side and elems.side_indicators:get() then elems.side_indicators:set(false) end
                    elems.side_indicators:disabled(ev_side)
                end
                if elems.gamesense_indicators then
                    if ev_side and elems.gamesense_indicators:get() then elems.gamesense_indicators:set(false) end
                    elems.gamesense_indicators:disabled(ev_side)
                end

                -- 10. Hitmarker
                local ev_hm = ev_on and elems.evalate_hitmarker and elems.evalate_hitmarker:get() == true
                if elems.hitmarkers then
                    if ev_hm and elems.hitmarkers:get() then elems.hitmarkers:set(false) end
                    elems.hitmarkers:disabled(ev_hm)
                end
            end)
            self.syncing_locks = false
        end

        local watch_elems = {
            elems.evalate_master, elems.evalate2_master, elems.evalate_watermark, elems.evalate_keybinds,
            elems.evalate_spectators, elems.evalate_notifications, elems.evalate_crosshair,
            elems.evalate_damage, elems.evalate_arrows, elems.evalate_side, elems.evalate_hitmarker,
            elems.widgets, elems.damage_indicator, elems.manual_arrows,
            elems.side_indicators, elems.gamesense_indicators, elems.hitmarkers
        }
        for _, wel in ipairs(watch_elems) do
            if wel and wel.set_callback then
                wel:set_callback(sync_conflicts)
            end
        end
        sync_conflicts()

        -- Default selections for listables
        pcall(function()
            if elems.evalate_notifications and elems.evalate_notifications.render and #elems.evalate_notifications.render:get() == 0 then
                elems.evalate_notifications.render:set({ 1, 3 })
            end
            if elems.evalate_debug_panel and elems.evalate_debug_panel.features and #elems.evalate_debug_panel.features:get() == 0 then
                elems.evalate_debug_panel.features:set({ 1, 2, 3, 4 })
            end
            if elems.evalate_crosshair and elems.evalate_crosshair.items and #elems.evalate_crosshair.items:get() == 0 then
                elems.evalate_crosshair.items:set({ 1, 2, 3, 4, 5 })
            end
            if elems.evalate_side and elems.evalate_side.items and #elems.evalate_side.items:get() == 0 then
                elems.evalate_side.items:set({ 1, 3, 4, 5, 7, 8, 9, 10, 13, 14 })
            end
        end)

        -- Rainbow accent updater
        events.render(function()
            if not elems.evalate_master:get() then return end
            if elems.evalate_accent and elems.evalate_accent:get() and elems.evalate_accent.color then
                pcall(function()
                    local mode, col = elems.evalate_accent.color:get()
                    if mode == "Rainbow" and col then
                        local _, s, v = col:to_hsv()
                        local ncol = color():as_hsv(globals.realtime % 3 / 3, s, v, col.a / 255)
                        elems.evalate_accent.color:set("Rainbow", { [1] = ncol })
                    end
                end)
            end
        end)

        -- ============================================================
        -- 1. WATERMARK & SLOW DOWN
        -- ============================================================
        if self.gradient_lib and self.gradient_lib.text_animate then
            pcall(function()
                self.wm_anim = self.gradient_lib.text_animate("caelestis", -1.3, { color() })
                self.ch_star_anim = self.gradient_lib.text_animate("caelestis", -1, { color() })
            end)
        end

        local function get_wm_text()
            local wm = elems.evalate_watermark
            local ntype = wm.name_type:get()
            local steam_name = (panorama and panorama.MyPersonaAPI and panorama.MyPersonaAPI.GetName and panorama.MyPersonaAPI.GetName()) or common.get_username()
            local uname = (ntype == 2 and steam_name) or (ntype == 3 and wm.name_input:get()) or common.get_username()
            local parts = { "\a" .. get_accent():to_hex() .. ui.get_icon("user") .. "  \aDEFAULT" .. tostring(uname) }

            local nc = utils.net_channel()
            if nc and nc:get_server_info() and nc:get_server_info().address ~= "loopback" then
                table.insert(parts, string.format("\a%s%s  \aDEFAULT%i ms", get_accent():to_hex(), ui.get_icon("arrows-rotate"), (nc.latency[1] or 0) * 1000))
            end
            if globals.realtime > self.wm_fps_time + 0.8 then
                self.wm_fps = math.floor(1 / math.max(0.0001, globals.absoluteframetime))
                self.wm_fps_time = globals.realtime
            end
            table.insert(parts, string.format("\a%s%s  \aDEFAULT%i fps", get_accent():to_hex(), ui.get_icon("layer-group"), self.wm_fps))
            local tfmt = wm.time_format:get() == 1 and "%H:%M" or "%I:%M %p"
            table.insert(parts, "\a" .. get_accent():to_hex() .. ui.get_icon("clock") .. "  \aDEFAULT" .. common.get_date(tfmt):lower())
            return table.concat(parts, "   ")
        end

        -- ============================================================
        -- 2. NOTIFICATIONS & HITMARKER EVENTS
        -- ============================================================
        local hitgroup_names = {
            [0] = "generic", [1] = "head", [2] = "chest", [3] = "stomach",
            [4] = "left arm", [5] = "right arm", [6] = "left leg", [7] = "right leg",
            [8] = "neck", [9] = "generic", [10] = "gear"
        }

        local function state_color(st)
            local map = {
                ["nil"] = get_accent(),
                spread = color("edc477"),
                correction = color("ff5d52"),
                misprediction = color("ff5d52"),
                ["backtrack failure"] = color("7a9ffa"),
                ["prediction error"] = color("ff5d52"),
                death = color("8c8c8c"),
                ["player death"] = color("8c8c8c"),
                ["unregistered shot"] = color("8c8c8c")
            }
            return map[tostring(st)] or map["nil"]
        end

        local function build_notif_str(col, fmt_str, args)
            local hex_act = (col or get_accent()):to_hex()
            local res = "\aC8C8C8FF" .. fmt_str
            for k, v in pairs(args or {}) do
                res = res:gsub("{" .. k .. "}", "\a" .. hex_act .. tostring(v) .. "\aC8C8C8FF")
            end
            return res
        end

        local function push_notif(col, text_screen, text_console)
            local nt = elems.evalate_notifications
            if not elems.evalate_master:get() or not nt or not nt:get() then return end
            if nt.render:get(3) then
                print_raw("\a" .. get_accent():to_hex() .. "caelestis\aC8C8C8FF › \aDEFAULT" .. (text_console or text_screen))
            end
            if nt.render:get(2) then
                print_dev(text_console or text_screen)
            end
            if nt.render:get(1) then
                table.insert(self.notifs, 1, {
                    alpha = 0,
                    text = text_screen,
                    color = col:clone(),
                    smoothy = self.smoothy_lib.new(0),
                    realtime = globals.realtime
                })
            end
        end

        events.aim_ack(function(ack)
            if not ack then return end
            if ack.state ~= nil then
                self.aim_stats.miss = self.aim_stats.miss + 1
            else
                self.aim_stats.hit = self.aim_stats.hit + 1
            end

            if elems.evalate_master:get() and elems.evalate_hitmarker and elems.evalate_hitmarker:get() and ack.aim then
                table.insert(self.hitmarkers_list, {
                    alpha = 0,
                    smoothy = self.smoothy_lib.new(0),
                    realtime = globals.realtime,
                    aim = ack.aim,
                    state = ack.state
                })
            end

            local me = entity.get_local_player()
            if ack.target and ack.target:is_player() and me then
                local tname = tostring(ack.target:get_name() or "Enemy"):sub(1, 17)
                local hc = math.floor((ack.hitchance or 0) + 0.5)
                local hg = hitgroup_names[ack.hitgroup] or "?"
                local whg = hitgroup_names[ack.wanted_hitgroup] or "?"
                local scol = state_color(ack.state)
                local ticks = math.abs(math.floor(tonumber(ack.backtrack or ack.ticks) or 0))

                local screen_str, console_str
                if ack.state == nil then
                    if ack.target:is_alive() then
                        screen_str = build_notif_str(scol, "Hit {name} in {hitgroup} for {damage} damage ({ticks}t)", { name = tname, hitgroup = hg, damage = ack.damage, ticks = ticks })
                        console_str = build_notif_str(scol, "Hit {name} in {hitgroup} for {damage} damage ‹ {ticks}t · {hitchance}% ›", { name = tname, hitgroup = hg, damage = ack.damage, ticks = ticks, hitchance = hc })
                    else
                        screen_str = build_notif_str(scol, "Killed {name} in {hitgroup} ({ticks}t)", { name = tname, hitgroup = hg, ticks = ticks })
                        console_str = build_notif_str(scol, "Killed {name} in {hitgroup} ‹ {ticks}t · {hitchance}% ›", { name = tname, hitgroup = hg, ticks = ticks, hitchance = hc })
                    end
                else
                    screen_str = build_notif_str(scol, "Missed in {name}'s {wanted_hitgroup} due to {reason} ({ticks}t)", { name = tname, wanted_hitgroup = whg, reason = ack.state, hitchance = hc, ticks = ticks })
                    console_str = build_notif_str(scol, "Missed in {name}'s {wanted_hitgroup} due to {reason} ‹ {ticks}t · {hitchance}% ›", { name = tname, wanted_hitgroup = whg, reason = ack.state, hitchance = hc, ticks = ticks })
                end
                push_notif(scol, screen_str, console_str)
            end
        end)

        events.player_hurt(function(e)
            if not elems.evalate_master:get() or not elems.evalate_notifications:get() then return end
            local me = entity.get_local_player()
            local vic = entity.get(e.userid, true)
            local att = entity.get(e.attacker, true)
            if not me or att ~= me or vic == me or not vic then return end
            local wmap = { taser = "Tased", inferno = "Burned", knife = "Knifed", hegrenade = "Naded" }
            local act = wmap[e.weapon]
            if not act then return end
            local vname = tostring(vic:get_name() or "Enemy"):sub(1, 17)
            local scol = get_accent()
            local str = build_notif_str(scol, act .. " {name} for {damage} damage", { name = vname, damage = e.dmg_health })
            push_notif(scol, str, str)
        end)

        -- ============================================================
        -- 3. RENDER ALL EVALATE WIDGETS & INDICATORS
        -- ============================================================
        local hm_icons = {
            [1] = ui.get_icon("star"),
            [2] = ui.get_icon("moon"),
            [3] = ui.get_icon("heart"),
            [4] = ui.get_icon("sparkles")
        }

        pcall(function()
            self.arrows_tex = {
                [1] = {
                    left = render.load_image("<svg width=\"39\" height=\"45\" viewBox=\"0 0 39 45\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\"> <path d=\"M34.41 1.07819C36.8485 -0.329653 39.7081 2.09415 38.7188 4.73032L32.3794 21.6229C32.1244 22.3024 32.1244 23.0514 32.3794 23.731L38.7188 40.6235C39.7081 43.2597 36.8485 45.6835 34.41 44.2756L1.49996 25.275C-0.500042 24.1203 -0.500043 21.2335 1.49996 20.0788L34.41 1.07819Z\" fill=\"white\"/> </svg>", vector(20, 20)),
                    right = render.load_image("<svg width=\"39\" height=\"45\" viewBox=\"0 0 39 45\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\"> <path d=\"M4.58032 44.3833C2.14187 45.7912 -0.717708 43.3674 0.271586 40.7312L6.61098 23.8387C6.866 23.1591 6.866 22.4101 6.61098 21.7306L0.271582 4.83803C-0.717712 2.20186 2.14186 -0.221952 4.58031 1.18589L37.4904 20.1865C39.4904 21.3412 39.4904 24.228 37.4904 25.3827L4.58032 44.3833Z\" fill=\"white\"/> </svg>", vector(20, 20))
                },
                [2] = {
                    left = render.load_image("<svg width=\"5\" height=\"10\" viewBox=\"0 0 5 10\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M5 0L2 0L0 4.5L0 5.5L2 10H5L3 5.5L3 5L3 4.5L5 0Z\" fill=\"white\"/></svg>", vector(10, 20)),
                    right = render.load_image("<svg width=\"5\" height=\"10\" viewBox=\"0 0 5 10\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M0 10L3 10L5 5.5L5 4.5L3 -1.74846e-07L8.74228e-07 -4.37114e-07L2 4.5L2 5L2 5.5L0 10Z\" fill=\"white\"/></svg>", vector(10, 20))
                }
            }
        end)

        events.render(function()
            if not elems.evalate_master or not elems.evalate_master:get() then return end
            local scr = render.screen_size()
            local sc = get_scale()
            local flg = get_flags()
            local acc = get_accent()
            local me = entity.get_local_player()
            local me_alive = me ~= nil and me:is_alive()

            -- 1. WATERMARK
            local wm_on = elems.evalate_watermark and elems.evalate_watermark:get()
            local wm_a = u179("ev_wm_a", { wm_on and 275 or -25, 0, 255 })
            if wm_on or wm_a >= 1 then
                local title_str = "\a" .. acc:to_hex() .. ui.get_icon("stars") .. " \aDEFAULTcaelestis"
                if self.wm_anim then
                    self.wm_anim:set_colors({ acc, acc:alpha_modulate(50) })
                    self.wm_anim:animate()
                    title_str = "\a" .. acc:to_hex() .. ui.get_icon("stars") .. " " .. self.wm_anim:get_animated_text()
                end
                draw_t61_new(nil, acc:alpha_modulate(wm_a), get_wm_text(), title_str, true)
            end

            -- 2. SLOW DOWN
            local sd_el = elems.evalate_slow_down
            local vel_mod = (me_alive and me.m_flVelocityModifier) or 1
            local sd_cond = sd_el and sd_el:get() and (vel_mod < 1 or ui.get_alpha() > 0)
            local sd_a = u179("ev_sd_a", sd_cond, 0.03)
            if sd_cond or sd_a >= 0.05 then
                local sd_col = color(255, 0, 0):lerp(color(255, 255, 255), vel_mod):alpha_modulate(255 * sd_a)
                local sd_off = u179("ev_sd_off", (sd_el.offset:get() or 40) * 0.01, 0.1)
                local sd_pos = vector(scr.x / 2, scr.y / 2 * sd_off + 30 * sd_a)
                draw_t61_new({ sd_pos, true }, sd_col, string.format("Slowed for %i%%", math.floor(100 * (1 - vel_mod))))
            end

            -- 3. KEYBINDS
            local kb_on = elems.evalate_keybinds and elems.evalate_keybinds:get()
            local has_act_bind = false
            local active_binds = {}
            local mode_names = { [1] = "hold", [2] = "toggle" }
            local raw_bind_list = {}
            local ok_b, raw_b = pcall(ui.get_binds)
            if ok_b and type(raw_b) == "table" then
                for _, b in pairs(raw_b) do
                    local n = tostring(b.name or ""):lower()
                    if not n:find("freestand") and not n:find("edge") then
                        table.insert(raw_bind_list, b)
                    end
                end
            end
            local fs_act, ey_act, fs_m, ey_m = get_lua_bind_states()
            if fs_act then
                table.insert(raw_bind_list, { name = "Freestanding", active = true, mode = (fs_m == "toggle" and 2 or 1), value = (fs_m == "toggle" and "toggle" or "holding") })
            end
            if ey_act then
                table.insert(raw_bind_list, { name = "Edge Yaw", active = true, mode = (ey_m == "toggle" and 2 or 1), value = (ey_m == "toggle" and "toggle" or "holding") })
            end
            for _, b in pairs(raw_bind_list) do
                local clean = tostring(b.name):gsub("\aDEFAULT", ""):gsub("\a%b{}", ""):gsub("\a%x%x%x%x%x%x%x%x", ""):gsub("[^%w%s]", ""):gsub("^%s+", ""):gsub("%s+$", "")
                local bval = b.value
                if type(bval) == "boolean" then bval = mode_names[b.mode] or "on"
                elseif type(bval) == "table" then bval = "on" end
                if b.active then has_act_bind = true end
                self.keybinds_cache[clean] = self.keybinds_cache[clean] or { alpha = 0, name = clean, value = tostring(bval), smoothy = self.smoothy_lib.new(0) }
                self.keybinds_cache[clean].value = tostring(bval)
                self.keybinds_cache[clean].alpha = math.max(0, math.min(255, self.keybinds_cache[clean].smoothy(0.05, b.active and 275 or -25)))
                if self.keybinds_cache[clean].alpha > 0 then
                    table.insert(active_binds, 1, self.keybinds_cache[clean])
                end
            end
            local kb_cond = kb_on and (has_act_bind or ui.get_alpha() > 0)
            local kb_a = u179("ev_kb_a", kb_cond, 0.05)
            if kb_cond or kb_a >= 0.05 then
                local kb_col = acc:alpha_modulate(255 * kb_a)
                local kb_sz = vector(self.kb_width, 23 * sc)
                local kb_pos = drag_kb:get_position()
                draw_t61_new(kb_pos, kb_col, kb_sz.x)
                render.text(font_content, kb_pos + vector(kb_sz.x / 2, 9 * sc), color(210, 210, 210, kb_col.a), get_flags("c"), "\a" .. acc:to_hex() .. ui.get_icon("bars") .. "  \aDEFAULTHotkeys")
                local row_m = 1.3
                local max_w = 0
                local step_y = 19 * sc
                for _, item in ipairs(active_binds) do
                    local nm = item.name:sub(1, 1):upper() .. item.name:sub(2):lower()
                    local nw = render.measure_text(font_content, flg, nm)
                    local vw = render.measure_text(font_content, flg, item.value)
                    local rw = nw.x + vw.x + 20 * sc
                    draw_t61_box(kb_pos + vector(0, step_y * row_m - 1 * sc), vector(kb_sz.x, 16 * sc), color(20, 20, 20, 76.5), item.alpha * kb_a, 4 * sc)
                    render.text(font_content, kb_pos + vector(5 * sc, step_y * row_m + 1 * sc), color(200, 200, 200, item.alpha * kb_a), flg, nm)
                    render.text(font_content, kb_pos + vector(kb_sz.x - vw.x - 5 * sc, step_y * row_m + 1 * sc), color(200, 200, 200, item.alpha * kb_a * 0.4), flg, item.value)
                    if rw > max_w and rw > 95 * sc then max_w = rw end
                    row_m = row_m + (item.alpha * kb_a / 255)
                end
                self.kb_width = math.floor(u179("ev_kb_w", math.max(max_w, 95 * sc)) + 0.5)
                drag_kb:update(kb_sz)
            end

            -- 4. SPECTATORS
            local sp_on = elems.evalate_spectators and elems.evalate_spectators:get()
            local has_specs = false
            local sp_list = {}
            if me then
                entity.get_players(false, false, function(p)
                    if p == me then return end
                    local pinfo = p:get_player_info()
                    if not pinfo then return end
                    local pname = tostring(p:get_name() or "Player"):sub(1, 17)
                    local key = pname .. "_" .. tostring(p:get_index())
                    self.spec_cache[key] = self.spec_cache[key] or { alpha = 0, smoothy = self.smoothy_lib.new(0), name = pname, player = p }
                    self.spec_cache[key].player = p
                    local target = me:is_alive() and me or me.m_hObserverTarget
                    local is_obs = (not p:is_alive()) and (p.m_hObserverTarget == target) and (target ~= nil)
                    if is_obs then has_specs = true end
                    self.spec_cache[key].alpha = math.max(0, math.min(255, self.spec_cache[key].smoothy(0.05, is_obs and 275 or -25)))
                    if self.spec_cache[key].alpha > 1 then
                        table.insert(sp_list, 1, self.spec_cache[key])
                    end
                end)
            end
            local sp_cond = sp_on and (has_specs or ui.get_alpha() > 0)
            local sp_a = u179("ev_sp_a", sp_cond, 0.05)
            if sp_cond or sp_a >= 0.05 then
                local sp_col = acc:alpha_modulate(255 * sp_a)
                local sp_sz = vector(self.spec_width, 23 * sc)
                local sp_pos = drag_sp:get_position()
                draw_t61_new(sp_pos, sp_col, sp_sz.x)
                render.text(font_content, sp_pos + vector(sp_sz.x / 2, 9 * sc), color(222, 222, 222, sp_col.a), get_flags("c"), "\a" .. acc:to_hex() .. ui.get_icon("eye") .. "  \aDEFAULTSpectators")
                local row_m = 1.3
                local max_w = 0
                local step_y = 19 * sc
                for _, item in ipairs(sp_list) do
                    local rw = render.measure_text(font_content, flg, item.name).x + 25 * sc
                    draw_t61_box(sp_pos + vector(17 * sc, step_y * row_m - 1 * sc), vector(sp_sz.x - 17 * sc, 16 * sc), color(20, 20, 20, 76.5), item.alpha * sp_a, 4 * sc)
                    render.text(font_content, sp_pos + vector(22 * sc, step_y * row_m + 1 * sc), color(200, 200, 200, item.alpha * sp_a), flg, item.name)
                    local av = item.player and item.player:get_steam_avatar()
                    if av then
                        pcall(render.texture, av, sp_pos + vector(0, step_y * row_m), vector(13, 13) * sc, color(255, 255, 255, item.alpha * sp_a), nil, 10 * sc)
                    end
                    if rw > max_w and rw > 95 * sc then max_w = rw end
                    row_m = row_m + (item.alpha * sp_a / 255)
                end
                self.spec_width = math.floor(u179("ev_sp_w", math.max(max_w, 95 * sc)) + 0.5)
                drag_sp:update(sp_sz)
            end

            -- 5. NOTIFICATIONS (SCREEN)
            local nt_el = elems.evalate_notifications
            local nt_cond = nt_el and nt_el:get() and nt_el.render:get(1) and me ~= nil
            local nt_a = u179("ev_nt_a", nt_cond)
            if nt_cond or nt_a >= 0.05 then
                local nt_off = math.floor(u179("ev_nt_off", nt_el.offset:get() or 40) + 0.5)
                local base_p = vector(scr.x / 2, scr.y / (1 + nt_off * 0.01))
                local stack_m = 0
                for k = #self.notifs, 1, -1 do
                    if k > 6 then table.remove(self.notifs, k) end
                end
                for k, v in ipairs(self.notifs) do
                    local alive = (v.realtime + 5) > globals.realtime
                    v.alpha = math.max(0, math.min(255, v.smoothy(0.05, alive and 275 or -25))) * nt_a
                    local tsz = render.measure_text(font_content, flg, v.text)
                    local bsz = vector(tsz.x + 10 * sc, tsz.y + 6 * sc)
                    local draw_p = vector(base_p.x, base_p.y + 27 * sc * stack_m) - bsz / 2
                    draw_t61_new(draw_p, v.color:alpha_modulate(v.alpha), v.text)
                    stack_m = stack_m + (v.alpha / 255)
                    if not alive and v.alpha < 1 then
                        table.remove(self.notifs, k)
                    end
                end
            end

            -- 6. DEBUG PANEL
            local dbg_el = elems.evalate_debug_panel
            local dbg_on = dbg_el and dbg_el:get()
            local dbg_a = u179("ev_dbg_a", { dbg_on and 265 or -10, 0, 255 }, 0.05)
            if dbg_on or dbg_a >= 1 then
                local dbg_col = acc:alpha_modulate(dbg_a)
                local w_box = 110 * sc
