        -- ============================================================
        -- 1. CUBIC-BEZIER EASING ENGINE (from evalate 2 recode)
        -- ============================================================
        local function v230_calc(p1, p2, t)
            local c = 3 * p1
            local b = 3 * (p2 - p1) - c
            return (((1 - c - b) * t + b) * t + c) * t
        end

        local function v265_slope(p1, p2, t)
            local c = 3 * p1
            local b = 3 * (p2 - p1) - c
            return (3 * (1 - c - b) * t + 2 * b) * t + c
        end

        local function bezier_easing(p1, p2, p3, p4)
            return function(t)
                local t_cur = t
                for _ = 1, 5 do
                    local diff = v230_calc(p1, p3, t_cur) - t
                    local slope = v265_slope(p1, p3, t_cur)
                    if math.abs(diff) >= 1.0e-5 and math.abs(slope) >= 1.0e-5 then
                        t_cur = t_cur - diff / slope
                    else
                        break
                    end
                end
                return v230_calc(p2, p4, t_cur)
            end
        end

        local function lerp_val(a, b, t)
            if type(a) == "number" and type(b) == "number" then
                return a + (b - a) * t
            elseif type(a) == "userdata" and type(b) == "userdata" then
                if a.lerp then return a:lerp(b, t) end
                if a.r and b.r then
                    return color(a.r + (b.r - a.r) * t, a.g + (b.g - a.g) * t, a.b + (b.b - a.b) * t, a.a + (b.a - a.a) * t)
                elseif a.x and b.x then
                    return vector(a.x + (b.x - a.x) * t, a.y + (b.y - a.y) * t, (a.z or 0) + ((b.z or 0) - (a.z or 0)) * t)
                end
            end
            return b
        end

        local function make_animator(init_val, duration, easing_fn)
            local dur = duration or 0.25
            local ease = easing_fn or bezier_easing(0.34, 1.6, 0.64, 1)
            local start_val = (type(init_val) == "boolean") and (init_val and 1 or 0) or (init_val or 0)
            local state = {
                active = false,
                time = 0,
                from = start_val,
                to = start_val,
                value = start_val
            }
            return function(target)
                if type(target) == "boolean" then target = target and 1 or 0 end
                if target ~= nil and target ~= state.to then
                    state.from = state.value
                    state.to = target
                    state.time = 0
                    state.active = true
                end
                if state.active then
                    local dt = globals.frametime or 0.016
                    state.time = math.min(state.time + dt, dur)
                    local progress = state.time / dur
                    state.value = lerp_val(state.from, state.to, ease(progress))
                    if progress >= 1 then
                        state.active = false
                    end
                end
                return state.value
            end
