            end
            local ok_s, st = pcall(ui.get_style, "Link Active")
            return (ok_s and st) or color(156, 167, 225, 255)
        end

        local function get_scale()
            if elems.evalate2_settings and elems.evalate2_settings.dpi and elems.evalate2_settings.dpi:get() then
                local ok, sc = pcall(render.get_scale, 2)
                if ok and sc then return sc end
            end
            return 1
        end

        local anim_blur = anim_lib(1, 0.25, anim_lib.ease_in_out)
        local anim_shadow = anim_lib(1, 0.25, anim_lib.ease_in_out)

        local function get_safe_icon(name)
            if ui.get_icon then
                local ok, ic = pcall(ui.get_icon, name)
                if ok and ic and type(ic) == "string" and #ic > 0 and not ic:find("<") and not ic:find("%[%?%]") then
                    return ic
                end
            end
            return ""
        end

        local function format_ui_string(str, accent_col)
            if type(str) ~= "string" then return tostring(str) end
            local acc_c = accent_col or get_accent()
            local acc_hex = acc_c:to_hex()
            local inact_hex = color(170):to_hex()
            local s = str
            local bell = string.char(7)
            local vtab = string.char(11)
            local ff = string.char(12)
            local cr = string.char(13)
            s = s:gsub("\\a%%%[accent%%%]", bell .. acc_hex)
            s = s:gsub(bell .. "%%%[accent%%%]", bell .. acc_hex)
            s = s:gsub("\\a%%%[inactive%%%]", bell .. inact_hex)
            s = s:gsub(bell .. "%%%[inactive%%%]", bell .. inact_hex)
            s = s:gsub("\\[sa]%%{accent%%}", bell .. acc_hex)
            s = s:gsub("\\[sa]%%{Link Active%%}", bell .. acc_hex)
            s = s:gsub("\\v", bell .. acc_hex)
            s = s:gsub(vtab, bell .. acc_hex)
            s = s:gsub("\\r", bell .. "DEFAULT")
            s = s:gsub(cr, bell .. "DEFAULT")
            s = s:gsub("\\f<(.-)>", get_safe_icon)
            s = s:gsub(ff .. "<(.-)>", get_safe_icon)
            return s
        end

        -- ============================================================
        -- 3. CARD RENDERER (v495 from evalate 2 recode)
        -- ============================================================
        local card = {
            layout = {
                shadow_spread = 70,
                rounding = 12,
                height = 12,
                padding = vector(25, 13)
            },
            fonts = {
                header = render.load_font("arial", 14, "ad"),
                content = render.load_font("arial", vector(13, 11), "a")
            },
            colors = {
                rect = {
                    outline = color(255, 20),
                    background = color(150, 40)
                },
                text = {
                    primary = color(240),
                    secondary = color(170)
                }
            }
        }

        card.render_rect = function(pos, col, alpha, width, height)
            local sc = get_scale()
            local h = card.layout.height * sc
            local pad = card.layout.padding * sc
            local round = card.layout.rounding * sc
            local spread = card.layout.shadow_spread * sc
            local p_center = (pos + vector(pad.x / 2, h / 2 + pad.y / 2)):floor()
            local factor = math.max(1, (height or h) / 16) - 1
            local sz = vector(width, 2 + 16 * factor):floor()

            local sh_alpha = anim_shadow(elems.evalate2_settings and elems.evalate2_settings.shadow and elems.evalate2_settings.shadow:get() and 1 or 0)
            local bl_alpha = anim_blur(elems.evalate2_settings and elems.evalate2_settings.blur and elems.evalate2_settings.blur:get() and 1 or 0)

            if sh_alpha > 0 then
                render.rect(p_center, p_center + sz, col:alpha_modulate(65 * alpha * sh_alpha), round)
                render.shadow(p_center, p_center + sz, col:alpha_modulate(255 * alpha * sh_alpha), spread, 0, round)
            end
            if bl_alpha > 0 then
                render.blur(pos, pos + pad + vector(width, height or h), 0, alpha * bl_alpha, round)
            end
            render.rect(pos, pos + pad + vector(width, height or h), card.colors.rect.background:alpha_modulate(card.colors.rect.background.a * alpha), round)
            render.rect_outline(pos, pos + pad + vector(width, height or h), card.colors.rect.outline:alpha_modulate(card.colors.rect.outline.a * alpha), 1, round)
        end

        card.render_text_header = function(pos, col, flags, text)
            render.text(card.fonts.header, pos, col, flags, text)
        end

        card.render_text_content = function(pos, col, flags, text)
            render.text(card.fonts.content, pos, col, flags, text)
        end

        -- Cached measure text
        local measure_cache = {}
        local function measure_text_cached(font, flags, text)
            local is_dpi = elems.evalate2_settings and elems.evalate2_settings.dpi and elems.evalate2_settings.dpi:get()
            local fl = (flags or "") .. (is_dpi and "s" or "")
            local key = string.format("%s:%s:%s", tostring(font), tostring(fl), tostring(text))
            if measure_cache[key] == nil or measure_cache[key].x == 0 then
                measure_cache[key] = render.measure_text(font, fl, tostring(text))
            end
            return measure_cache[key]
        end

        -- ============================================================
        -- 4. INTERACTIVE DRAGGING SYSTEM (v538 from evalate 2 recode)
        -- ============================================================
        local dragger_active_id = nil
        local dragger_hover_id = nil

        events.mouse_input(function()
            if dragger_active_id ~= nil or dragger_hover_id ~= nil then
                return false
            end
        end)

        local function is_mouse_in_box(pos, sz, m_pos)
            return m_pos.x >= pos.x and m_pos.x <= pos.x + sz.x and m_pos.y >= pos.y and m_pos.y <= pos.y + sz.y
        end

        local function clamp_val(val, min_v, max_v)
            if val < min_v then return min_v elseif val > max_v then return max_v else return val end
        end

        local function clamp_vec(v, min_v, max_v)
            return vector(clamp_val(v.x, min_v.x, max_v.x), clamp_val(v.y, min_v.y, max_v.y), clamp_val(v.z or 0, min_v.z or 0, max_v.z or 0))
        end

        local dragger_storage = l_pui_0.create("evalate-draggers")
        local DRAG_SCALE = 10000

        local function create_drag(name, default_pos, default_size)
            local sx = math.max(1, math.floor(scr_init.x))
            local sy = math.max(1, math.floor(scr_init.y))
            local px_slider = dragger_storage:slider(string.format("drag[%s].px", name), -DRAG_SCALE, DRAG_SCALE, math.floor(default_pos.x / sx * DRAG_SCALE))
            local py_slider = dragger_storage:slider(string.format("drag[%s].py", name), -DRAG_SCALE, DRAG_SCALE, math.floor(default_pos.y / sy * DRAG_SCALE))
            px_slider:set_visible(false)
            py_slider:set_visible(false)

            local obj = {
                name = name,
                dragging = false,
                hover = false,
                action = false,
                last_mouse_pos = vector(),
                size = default_size,
                position = default_pos,
                limit = nil,
                lines = {},
                anim_box_alpha = anim_lib(0, 0.15, anim_lib.ease_in_out),
                anim_line_alpha = anim_lib(0, 0.15, anim_lib.ease_in_out),
                anim_border_alpha = anim_lib(0, 0.15, anim_lib.ease_in_out),

                get_position = function(self)
                    local scr = render.screen_size()
                    return vector((px_slider:get() / DRAG_SCALE) * scr.x, (py_slider:get() / DRAG_SCALE) * scr.y)
                end,

                set_limit = function(self, pos, sz)
                    self.limit = { position = pos, size = sz }
                end,

                update = function(self, alpha_mult, new_sz, round_override)
                    local ui_alpha = ui.get_alpha()
                    local vis_alpha = ui_alpha * (alpha_mult or 1)
                    local m_pos = ui.get_mouse_position()
                    local btn_down = common.is_button_down(1)
                    local menu_pos = ui.get_position()
                    local menu_sz = ui.get_size()
                    local in_menu = is_mouse_in_box(menu_pos, menu_sz, m_pos)
                    local scr = render.screen_size()

                    if new_sz then self.size = new_sz end
                    self.position = self:get_position()
                    self.hover = is_mouse_in_box(self.position, self.size, m_pos) and not in_menu
                    self.action = self.dragging or self.hover

                    if self.action and btn_down and ui_alpha > 0 and (dragger_active_id == self.name or dragger_active_id == nil) then
                        local desired = m_pos + self.last_mouse_pos
                        desired = clamp_vec(desired, vector(0, 0), scr - self.size)
                        if self.limit then
                            desired = clamp_vec(desired, self.limit.position, self.limit.position + self.limit.size - self.size)
                        end
                        px_slider:set(math.floor(desired.x / scr.x * DRAG_SCALE))
                        py_slider:set(math.floor(desired.y / scr.y * DRAG_SCALE))
                        self.position = desired
                        self.dragging = true
                        dragger_active_id = self.name
                    else
                        self.last_mouse_pos = self.position - m_pos
                        self.dragging = false
                        if dragger_active_id == self.name then
                            dragger_active_id = nil
                        end
                    end

                    if self.hover and ui_alpha > 0 then
                        dragger_hover_id = self.name
                    elseif dragger_hover_id == self.name then
                        dragger_hover_id = nil
                    end

                    if vis_alpha > 0 then
                        local sc = get_scale()
                        local rnd = (round_override or 16) * sc
                        local b_alpha = self.anim_box_alpha(self.action and 30 or 20) * vis_alpha
                        local l_alpha = self.anim_line_alpha(self.action and 40 or 0) * vis_alpha
                        local o_alpha = self.anim_border_alpha(self.dragging and 40 or 0) * vis_alpha

                        if self.limit and l_alpha > 0 then
                            render.rect_outline(self.limit.position, self.limit.position + self.limit.size, color(255, l_alpha), 1, rnd)
                        end
                        if b_alpha > 0 then
                            render.rect(self.position, self.position + self.size, color(255, b_alpha), rnd)
                        end
                        if o_alpha > 0 then
                            render.rect_outline(self.position, self.position + self.size, color(255, o_alpha), 1, rnd)
                        end
                    end
                end
            }
            return obj
        end

        local function create_drag_offset(name, anchor_pos, size, default_offset, max_offset, horizontal, is_centered)
            local off_slider = dragger_storage:slider(string.format("drag[%s].offset", name), -DRAG_SCALE, DRAG_SCALE, default_offset)
            off_slider:set_visible(false)

            local obj = {
                name = name,
                action = false,
                dragging = false,
                hover = false,
                last_mouse_pos = vector(),
                size = size,
                position = anchor_pos,
                offset = default_offset,
                max_offset = max_offset,
                horizontal = horizontal,
                is_centered = is_centered,
                anim_box_alpha = anim_lib(0, 0.15, anim_lib.ease_in_out),
                anim_line_alpha = anim_lib(0, 0.15, anim_lib.ease_in_out),
                anim_border_alpha = anim_lib(0, 0.15, anim_lib.ease_in_out),

                get_offset = function(self)
                    return off_slider:get()
                end,

                update = function(self, alpha_mult, new_sz, round_override)
                    local ui_alpha = ui.get_alpha()
                    local vis_alpha = ui_alpha * (alpha_mult or 1)
                    local m_pos = ui.get_mouse_position()
                    local btn_down = common.is_button_down(1)
                    local menu_pos = ui.get_position()
                    local menu_sz = ui.get_size()
                    local in_menu = is_mouse_in_box(menu_pos, menu_sz, m_pos)

                    if new_sz then self.size = new_sz end
                    self.offset = self:get_offset()

                    local box_pos = self.position - (self.is_centered and (self.size / 2) or vector(self.size.x / 2, 0)) + (self.horizontal and vector(self.offset, 0) or vector(0, self.offset))
                    self.hover = is_mouse_in_box(box_pos, self.size, m_pos) and not in_menu
                    self.action = self.dragging or self.hover

                    if self.action and btn_down and ui_alpha > 0 and (dragger_active_id == self.name or dragger_active_id == nil) then
                        if self.horizontal then
                            local val = clamp_val(-(self.position.x - (m_pos.x + self.last_mouse_pos.x)), 0, self.max_offset)
                            off_slider:set(math.floor(val))
                        else
                            local val = clamp_val(-(self.position.y - (m_pos.y + self.last_mouse_pos.y)), 0, self.max_offset)
                            off_slider:set(math.floor(val))
                        end
                        self.offset = off_slider:get()
                        self.dragging = true
                        dragger_active_id = self.name
                    else
                        self.last_mouse_pos = self.horizontal and (self.position - m_pos + vector(self.offset, 0)) or (self.position - m_pos + vector(0, self.offset))
                        self.dragging = false
                        if dragger_active_id == self.name then
                            dragger_active_id = nil
                        end
                    end

                    if self.hover and ui_alpha > 0 then
                        dragger_hover_id = self.name
                    elseif dragger_hover_id == self.name then
                        dragger_hover_id = nil
                    end

                    if vis_alpha > 0 then
                        local sc = get_scale()
                        local rnd = (round_override or 16) * sc
                        local b_alpha = self.anim_box_alpha(self.action and 30 or 20) * vis_alpha
                        local l_alpha = self.anim_line_alpha(self.action and 40 or 0) * vis_alpha
                        local o_alpha = self.anim_border_alpha(self.dragging and 40 or 0) * vis_alpha

                        if l_alpha > 0 then
                            local line_sz = self.horizontal and vector(self.max_offset, 1) or vector(1, self.max_offset)
                            render.rect(self.position, self.position + line_sz, color(255, l_alpha))
                        end
                        if b_alpha > 0 then
                            render.rect(box_pos, box_pos + self.size, color(255, b_alpha), rnd)
                        end
                        if o_alpha > 0 then
                            render.rect_outline(box_pos, box_pos + self.size, color(255, o_alpha), 1, rnd)
                        end
                    end
                end
            }
            return obj
        end

        -- Draggers instances
        local drag_specs = create_drag("specs", vector(450, 300), vector(100, 44))
        local drag_hotkeys = create_drag("hotkeys", vector(300, 300), vector(100, 44))
        local drag_damage = create_drag("damage", vector(scr_init.x / 2 + 1, scr_init.y / 2 - 17), vector(25, 14))

        local notif_def_y = scr_init.y / 1.7
        local drag_notifs = create_drag_offset("notifications", vector(scr_init.x / 2, notif_def_y), vector(200, 30), 50, math.floor(scr_init.y / 1.1 - notif_def_y), false, false)
        local drag_crosshair = create_drag_offset("crosshair", vector(scr_init.x / 2, scr_init.y / 2), vector(55, 18), 10, 100, false, false)
        local drag_arrows = create_drag_offset("arrows", vector(scr_init.x / 2, scr_init.y / 2), vector(15, 15), 30, 100, true, true)
        local drag_stack = create_drag_offset("stack", vector(scr_init.x / 2, 0), vector(100, 44), math.floor(scr_init.y / 3), math.floor(scr_init.y), false, false)

        -- ============================================================
        -- 5. CLOSE SHOT BULLET EVASION DETECTOR (events.close_shot)
        -- ============================================================
        local close_shot_cbs = {}
        events.close_shot = function(cb, remove)
            if remove then
                close_shot_cbs[cb] = nil
            else
                close_shot_cbs[cb] = true
            end
        end

        local last_hurt_tick = 0
        events.player_hurt(function(e)
            local me = entity.get_local_player()
            local vic = entity.get(e.userid, true)
            local att = entity.get(e.attacker, true)
            if me and vic and me == vic and me ~= att then
                last_hurt_tick = globals.tickcount
            end
        end)

        local last_impact_tick = nil
        events.bullet_impact(function(e)
            local cur_tick = globals.tickcount
            if last_impact_tick == cur_tick then return end
            local me = entity.get_local_player()
            local enemy = entity.get(e.userid, true)
            if not me or not me:is_alive() or not enemy or enemy:is_dormant() or not enemy:is_enemy() then
                return
            end
            local my_eye = me:get_eye_position()
            local enemy_eye = enemy:get_eye_position()
            if not my_eye or not enemy_eye then return end
            local impact_pos = vector(e.x, e.y, e.z)
            local dist = my_eye:closest_ray_point(enemy_eye, impact_pos):dist(my_eye)
            if dist < 60 then
                local tick_int = globals.tickinterval or 0.015625
                utils.execute_after(tick_int, function()
                    if cur_tick - last_hurt_tick ~= 0 then
                        for cb, active in pairs(close_shot_cbs) do
                            if active then
                                pcall(cb, {
                                    distance = dist,
                                    entity = enemy,
                                    impact = impact_pos
                                })
                            end
                        end
                    end
                end)
                last_impact_tick = globals.tickcount
            end
        end)

        -- ============================================================
        -- 6. SHARED STATE & TICKBASE DEFENSIVE DETECTOR
        -- ============================================================
        local state = {
            me = nil,
            is_alive = false,
            binds = {},
            ui_alpha = 0,
            is_scoped = false,
            anim_scoped = 0,
            exploit_charge = 0,
            is_defensive = false,
            defensive_ticks_left = 0,
            players = {},
            net_channel = nil,
            server_info = nil,
            realtime = 0,
            absoluteframetime = 0.016
        }

        local anim_scoped_tracker = anim_lib(0, 0.25, anim_lib.ease_in_out)
        local last_tickbase = 0

        events.createmove(function(cmd)
            local me = entity.get_local_player()
            if me then
                local tb = me.m_nTickBase
                if math.abs(tb - last_tickbase) > 64 then
                    last_tickbase = 0
                end
                state.defensive_ticks_left = 0
                if last_tickbase < tb then
                    last_tickbase = tb
                elseif tb < last_tickbase then
                    state.defensive_ticks_left = math.min(14, math.max(0, last_tickbase - tb - 1))
                end
                state.is_defensive = state.defensive_ticks_left > 0
            end
        end)

        local function update_shared_state()
            state.me = entity.get_local_player()
            state.is_alive = state.me and state.me:is_alive() or false
            local raw_b = {}
            local ok_b, b_list = pcall(ui.get_binds)
            if ok_b and type(b_list) == "table" then
                for _, b in ipairs(b_list) do
                    local n = tostring(b.name or ""):lower()
                    if not n:find("freestand") and not n:find("edge") then
                        table.insert(raw_b, b)
                    end
                end
            end
            local fs_act, ey_act, fs_m, ey_m = get_lua_bind_states()
            if fs_act then
                table.insert(raw_b, { name = "Freestanding", active = true, mode = (fs_m == "toggle" and 2 or 1), value = (fs_m == "toggle" and "toggle" or "holding") })
            end
            if ey_act then
                table.insert(raw_b, { name = "Edge Yaw", active = true, mode = (ey_m == "toggle" and 2 or 1), value = (ey_m == "toggle" and "toggle" or "holding") })
            end
            state.binds = raw_b
            state.ui_alpha = ui.get_alpha()
            state.is_scoped = state.me and state.me.m_bIsScoped or false
            state.anim_scoped = anim_scoped_tracker(state.is_scoped)
            local ok_exp, chg = pcall(function() return rage.exploit:get() end)
            state.exploit_charge = ok_exp and chg or 0
            state.realtime = globals.realtime or 0
            state.absoluteframetime = globals.absoluteframetime or 0.016
            state.net_channel = utils.net_channel()
            if state.net_channel then
                state.server_info = state.net_channel:get_server_info()
            end
            state.players = {}
            local pls = entity.get_players()
            if pls then
                for _, p in ipairs(pls) do
                    table.insert(state.players, { entity = p, is_enemy = p:is_enemy(), is_alive = p:is_alive() })
                end
            end
        end

        -- ============================================================
        -- 7. NOTIFICATIONS SYSTEM (v50 from evalate 2 recode)
        -- ============================================================
        local notifs_queue = { default = {}, preview = {} }
        local notifs_max_history = 5
        local notifs_duration = 5
        local notif_anim_total_w = anim_lib()
        local notif_cur_w = 100

        local function notif_center(pos, col, alpha, text)
            local sc = get_scale()
            local c_pad = card.layout.padding * sc
            local t_offset = vector(10, 0) * sc
            local m_sz = measure_text_cached(card.fonts.content, nil, text) + t_offset
            local card_pos = pos - vector(c_pad.x / 2 + m_sz.x / 2, 0)
            card.render_rect(card_pos, col, alpha, m_sz.x)
            card.render_text_content(card_pos + t_offset + c_pad / 2, color(255, 255 * alpha), nil, text)
            local circle_pos = card_pos + vector(13, 12) * sc
            render.circle(circle_pos, col:alpha_modulate(75 * alpha), 4 * sc, 0, 1 * sc)
            render.circle(circle_pos, col:alpha_modulate(255 * alpha), 2 * sc, 0, 1 * sc)
            return m_sz.x
        end

        local function notif_build(pattern, accent_col, params)
            local acc_c = accent_col or get_accent()
            local acc_tag = "\a" .. acc_c:to_hex()
            local inact_tag = "\a" .. color(170):to_hex()
            local res = inact_tag .. tostring(pattern)
            if params then
                for k, v in pairs(params) do
                    local key_tok = "{" .. tostring(k) .. "}"
                    local val_tok = acc_tag .. tostring(v) .. inact_tag
                    res = res:gsub(key_tok, val_tok)
                end
            end
            return format_ui_string(res, acc_c)
        end

        local function notif_print(formatted_text)
            local prefix = "\a" .. get_accent():to_hex() .. "caelestis\a" .. color(170):to_hex() .. " \226\128\186 \aDEFAULT"
            local full_msg = prefix .. tostring(formatted_text)
            if elems.evalate2_notifications and elems.evalate2_notifications.debug and elems.evalate2_notifications.debug:get() then
                print_dev(full_msg)
            end
            if elems.evalate2_notifications and elems.evalate2_notifications.console and elems.evalate2_notifications.console:get() then
                print_raw(full_msg)
            end
        end

        local function notif_screen(cb, is_preview)
            if is_preview then
                table.insert(notifs_queue.preview, 1, {
                    alpha = 0,
                    animate = anim_lib(),
                    callback = cb
                })
            else
                table.insert(notifs_queue.default, 1, {
                    alpha = 0,
                    animate = anim_lib(),
                    realtime = state.realtime,
                    callback = cb
                })
                if #notifs_queue.default > notifs_max_history then
                    table.remove(notifs_queue.default)
                end
            end
        end

        -- Preview notifications
        notif_screen(function(entry, p)
            local acc = get_accent()
            local t = notif_build("your face is like a {melody} - it won't leave my {head}", acc, { head = "head", melody = "melody" })
            return notif_center(p, acc, entry.alpha, t)
        end, true)

        notif_screen(function(entry, p)
            local acc = get_accent()
            local t = notif_build("Glad to see you again, {name}!", acc, { name = common.get_username() })
            return notif_center(p, acc, entry.alpha, t)
        end, true)

