            spread = color("edc477"), correction = color("ff5d52"), misprediction = color("ff5d52"),
            ["prediction error"] = color("ff5d52"), ["damage rejection"] = color("ff5d52"),
            ["backtrack failure"] = color("7a9ffa"), death = color("8c8c8c"),
