        local suicide_quotes = {
            "Suicide is not a solution. Let's talk.",
            "Let's talk before it\226\128\153s too late.",
            "You're not alone. Let's talk.",
            "You matter more than you know.",
            "No shame in pain. Just talk.",
            "Breathe. Break. Talk. Repeat.",
            "Scream, cry, curse \226\128\148 just don't disappear.",
            "Death is quiet. Don't be.",
            "I'm calling 911."
        }

        local function format_shot_details(is_miss, hc, dmg, hg, wanted_dmg, wanted_hg, sprd, bt, hp)
            local parts = {}
            parts[#parts + 1] = "{backtrack}t"
            parts[#parts + 1] = "{hitchance}%"
            parts[#parts + 1] = "{spread}\194\176"
            if not is_miss and hp > 0 then parts[#parts + 1] = "{health} hp" end
            local diff_d = dmg ~= wanted_dmg
            local diff_h = hg ~= wanted_hg and not is_miss
            if diff_d and diff_h then
                parts[#parts + 1] = "{wanted_hitgroup} ({wanted_damage} dmg)"
            elseif diff_d then
                parts[#parts + 1] = "{wanted_damage} dmg"
            elseif diff_h then
                parts[#parts + 1] = "{wanted_hitgroup}"
            end
            if #parts > 0 then
                return " \226\128\185 " .. table.concat(parts, " \194\183 ") .. " \226\128\186"
            end
            return ""
        end

        events.aim_ack(function(ack)
            if not elems.evalate2_master:get() or not elems.evalate2_notifications:get() then return end
            local tgt = ack.target
            if not tgt or not state.me then return end
            local t_name = tgt:get_name()
            local is_alive = tgt:is_alive()
            local hc = math.floor((ack.hitchance or 0) + 0.5)
            local dmg = ack.damage or 0
            local hg = hitgroups[ack.hitgroup] or "?"
            local wanted_dmg = ack.wanted_damage or 0
            local wanted_hg = hitgroups[ack.wanted_hitgroup] or "?"
            local st = ack.state
            local col = (st and state_colors[st]) or get_accent()
            local sprd = string.format("%.2f", ack.spread or 0)
            local bt = math.abs(math.floor(tonumber(ack.backtrack or ack.ticks) or 0))
            local hp = tgt.m_iHealth or 0

            local screen_str = ""
            if st then
                screen_str = notif_build("Miss in {name}'s {wanted_hitgroup} due to {reason} ({backtrack}t)", col, { name = t_name, reason = st, wanted_hitgroup = wanted_hg, backtrack = bt })
            elseif is_alive then
                screen_str = notif_build("Hit {name} in {hitgroup} for {damage} damage ({backtrack}t)", col, { name = t_name, damage = dmg, hitgroup = hg, backtrack = bt })
            else
                screen_str = notif_build("Killed {name} in {hitgroup} ({backtrack}t)", col, { name = t_name, hitgroup = hg, backtrack = bt })
            end

            notif_screen(function(entry, p)
                return notif_center(p, col, entry.alpha, screen_str)
            end)

            local det = format_shot_details(st ~= nil, hc, dmg, hg, wanted_dmg, wanted_hg, sprd, bt, hp)
            local log_params = { name = t_name, reason = st, damage = dmg, health = hp, spread = sprd, hitgroup = hg, hitchance = hc, backtrack = bt, wanted_damage = wanted_dmg, wanted_hitgroup = wanted_hg }
            local log_str = ""
            if st then
                log_str = notif_build("Miss in {name}'s {wanted_hitgroup} due to {reason}" .. det, col, log_params)
            elseif is_alive then
                log_str = notif_build("Hit {name} in {hitgroup} for {damage} damage" .. det, col, log_params)
            else
                log_str = notif_build("Killed {name} in {hitgroup}" .. det, col, log_params)
            end
            notif_print(log_str)
        end)

        events.player_death(function(e)
            if not elems.evalate2_master:get() or not elems.evalate2_notifications:get() then return end
            local vic = entity.get(e.userid, true)
            local att = entity.get(e.attacker, true)
            if not state.me or state.me ~= vic or not att then return end
            local att_name = att:get_name()
            local col = state_colors.death or get_accent()
            local msg = "Killed by {name}"
            if state.me == att then
                msg = suicide_quotes[math.random(1, #suicide_quotes)] or "Suicide is not a solution. Let's talk."
            end
            local t = notif_build(msg, col, { name = att_name })
            notif_screen(function(entry, p)
                return notif_center(p, col, entry.alpha, t)
            end)
            notif_print(t)
        end)

        local molotov_tracker = {}
        events.player_hurt(function(e)
            if not elems.evalate2_master:get() or not elems.evalate2_notifications:get() then return end
            local me = state.me
            local vic = entity.get(e.userid, true)
            local att = entity.get(e.attacker, true)
            if not me or not att or me ~= att or not vic then return end
            local wpn = e.weapon
            local vic_name = vic:get_name()
            local col = get_accent()
            if wpn == "inferno" then
                local k = tostring(vic:get_index()) .. tostring(vic_name)
                molotov_tracker[k] = (molotov_tracker[k] or 0) + (e.dmg_health or 0)
                local cur_dmg = molotov_tracker[k]
                local is_alive = (e.health or 0) > 0
                local t = notif_build(is_alive and "{name} was burned for {damage} hp" or "{name} burned out", col, { name = vic_name, damage = cur_dmg })
                if not is_alive then molotov_tracker[k] = 0 end
                notif_screen(function(entry, p)
                    return notif_center(p, col, entry.alpha, t)
                end)
                notif_print(t)
            end
        end)

        events.close_shot(function(shot)
            if not elems.evalate2_master:get() or not elems.evalate2_notifications:get() then return end
            local ent = shot.entity
            local e_name = ent and ent:get_name() or "Enemy"
            local col = get_accent()
            local t = notif_build("Evaded {name}'s shot", col, { name = e_name })
            notif_screen(function(entry, p)
                return notif_center(p, col, entry.alpha, t)
            end)
            notif_print(t)
        end)

        local anim_notifs_master = anim_lib()
        local function render_notifications()
            local nt_on = elems.evalate2_master:get() and elems.evalate2_notifications:get() and elems.evalate2_notifications.screen and elems.evalate2_notifications.screen:get()
            local master_a = anim_notifs_master(nt_on and (state.is_alive or state.ui_alpha > 0))
            if master_a <= 0 then return end

            local sc = get_scale()
            local smooth_w = notif_anim_total_w(notif_cur_w)
            local box_sz = vector(smooth_w + card.layout.padding.x * sc + 8 * sc, 33 * sc)
            drag_notifs:update(master_a, box_sz)

            local base_p = vector(drag_notifs.position.x, drag_notifs.position.y + drag_notifs.offset + 4 * sc)
            local row_offset = 0

            if #notifs_queue.default > 0 then
                for i = #notifs_queue.default, 1, -1 do
                    local item = notifs_queue.default[i]
                    local expired = state.realtime > (item.realtime + notifs_duration)
                    item.alpha = item.animate(not expired) * master_a
                    if item.alpha > 0 then
                        local w = item.callback(item, vector(base_p.x, base_p.y + 33 * sc * row_offset))
                        if i == 1 then notif_cur_w = w end
                        row_offset = row_offset + item.alpha
                    end
                    if expired and item.alpha <= 0 then
                        table.remove(notifs_queue.default, i)
                    end
                end
            elseif state.ui_alpha > 0 then
                for i, item in ipairs(notifs_queue.preview) do
                    item.alpha = item.animate(state.ui_alpha > 0) * master_a
                    if item.alpha > 0 then
                        local w = item.callback(item, vector(base_p.x, base_p.y + 33 * sc * row_offset))
                        if i == 1 then notif_cur_w = w end
                        row_offset = row_offset + item.alpha
                    end
                end
            end
        end

        -- ============================================================
        -- 8. WATERMARK (v545 from evalate 2 recode)
        -- ============================================================
        local anim_wm_master = anim_lib()
        local anim_wm_sub = anim_lib()
        local anim_wm_w = anim_lib(95, nil, anim_lib.ease_in_out)
        local wm_fps_val = 0
        local wm_fps_time = 0

        local function render_watermark()
            local wm_el = elems.evalate2_watermark
            local wm_on = elems.evalate2_master:get() and wm_el and wm_el:get()
            local wm_a = anim_wm_master(wm_on)
            if wm_a <= 0 then return end

            local sc = get_scale()
            local acc = get_accent()
            local scr = render.screen_size()

            local parts = {}
            if wm_el.version and wm_el.version:get() then
                local ic = get_safe_icon("code")
                parts[#parts + 1] = "\a" .. acc:to_hex() .. ic .. (#ic > 0 and "  " or "") .. "\aDEFAULTcaelestis"
            end
            if wm_el.username and wm_el.username:get() then
                local u_src = wm_el.username_source and wm_el.username_source:get() or "Cheat"
                local u_name = common.get_username()
                if u_src == "Steam" then
                    local ok, sn = pcall(function() return panorama.MyPersonaAPI.GetName() end)
                    if ok and sn and #sn > 0 then u_name = sn end
                elseif u_src == "Custom" and wm_el.username_custom then
                    u_name = wm_el.username_custom:get() or u_name
                end
                local ic = get_safe_icon("user")
                parts[#parts + 1] = "\a" .. acc:to_hex() .. ic .. (#ic > 0 and "  " or "") .. "\aDEFAULT" .. tostring(u_name)
            end
            if wm_el.latency and wm_el.latency:get() and state.net_channel and state.server_info and state.server_info.address ~= "loopback" then
                local lat = (state.net_channel.latency and state.net_channel.latency[1] or 0) * 1000
                local ic = get_safe_icon("arrows-rotate")
                parts[#parts + 1] = string.format("\a%s%s%s\aDEFAULT%i ms", acc:to_hex(), ic, (#ic > 0 and "  " or ""), math.floor(lat))
            end
            if wm_el.frames and wm_el.frames:get() then
                if state.realtime > wm_fps_time + 0.8 then
                    wm_fps_val = math.floor(1 / math.max(0.001, state.absoluteframetime))
                    wm_fps_time = state.realtime
                end
                local ic = get_safe_icon("layer-group")
                parts[#parts + 1] = string.format("\a%s%s%s\aDEFAULT%i fps", acc:to_hex(), ic, (#ic > 0 and "  " or ""), wm_fps_val)
            end
            if wm_el.time and wm_el.time:get() then
                local fmt = (wm_el.time_format and wm_el.time_format:get() == "12h") and "%I:%M %p" or "%H:%M"
                local ic = get_safe_icon("clock")
                parts[#parts + 1] = string.format("\a%s%s%s\aDEFAULT%s", acc:to_hex(), ic, (#ic > 0 and "  " or ""), common.get_date(fmt):lower())
            end

            local right_txt = table.concat(parts, "   ")
            local right_sz = measure_text_cached(card.fonts.content, nil, right_txt)
            local sub_a = anim_wm_sub(#parts > 0)
            local right_w = anim_wm_w(right_sz.x)

            local title_txt = "caelestis"
            local title_sz = measure_text_cached(card.fonts.header, nil, title_txt)
            local pad_x = card.layout.padding.x * sc
            local total_w = right_w + title_sz.x + pad_x * (2 - (1 - sub_a))

            local pos_mode = wm_el.position and wm_el.position:get() or "Top Right"
            local p = vector(scr.x - total_w - (10 + 5 * sub_a) * sc, 10 * wm_a)
            if pos_mode == "Top Left" then
                p = vector(10, 10 * wm_a)
            elseif pos_mode == "Bottom Center" then
                p = vector(scr.x / 2 - total_w / 2, scr.y - 44 * sc * wm_a)
            end

            card.render_rect(p, acc, wm_a, title_sz.x)
            card.render_text_header(p + card.layout.padding * sc / 2 - vector(0, 2 * sc), acc:alpha_modulate(255 * wm_a), nil, title_txt)

            if sub_a > 0 then
                local p2 = vector(p.x + title_sz.x + pad_x + 5 * sc, p.y)
                card.render_rect(p2, acc, wm_a * sub_a, right_w)
                card.render_text_content(p2 + card.layout.padding * sc / 2, card.colors.text.primary:alpha_modulate(255 * wm_a * sub_a), nil, right_txt)
            end
        end

        -- ============================================================
        -- 9. SPECTATORS (v623 from evalate 2 recode)
        -- ============================================================
