44\223\225G\246u\247\252\249\\\255\000\223\166\255\000\n(\160\003\251:\251\254|\174\127\239\211\127\133\031\217\215\223\243\229s\255\000~\155\252(\162\128\015\236\235\239\249\242\185\255\000\191M\254\020\127g_\127\207\149\207\253\250o\240\162\138\000\179\167Y]\195\168[K5\180\241\198\146\17134d\000\001\030\212QE\000\127\255\217", vector(30, 30));
        local default_avatar_tex = l_v631_2

        local anim_specs_master = anim_lib()
        local anim_specs_list = anim_lib()
        local anim_specs_w = anim_lib(95, nil, anim_lib.ease_in_out)
        local specs_cur_w = 103
        local specs_cache = {}

        local function render_spectators()
            local sp_el = elems.evalate2_spectators
            local sp_on = elems.evalate2_master:get() and sp_el and sp_el:get()
            local sp_active = false
            local specs_list = {}

            if state.me then
                for _, p_data in ipairs(state.players) do
                    local pl = p_data.entity
                    if pl and pl:get_player_info() and not pl:is_alive() and not pl:is_dormant() then
                        local obs = pl.m_hObserverTarget
                        if obs and obs == state.me then
                            sp_active = true
                            local p_name = pl:get_name()
                            specs_cache[p_name] = specs_cache[p_name] or { alpha = 0, name = p_name, player = pl, animate = anim_lib() }
                            specs_cache[p_name].alpha = specs_cache[p_name].animate(true)
                            table.insert(specs_list, specs_cache[p_name])
                        end
                    end
                end
            end

            local sp_a = anim_specs_master(sp_on and (sp_active or state.ui_alpha > 0))
            if sp_a <= 0 then return end

            local sc = get_scale()
            local acc = get_accent()
            local pad = card.layout.padding * sc
            local sp_ic = get_safe_icon("magnifying-glass")
            if #sp_ic == 0 then sp_ic = get_safe_icon("eye") end
            local title = "\a" .. acc:to_hex() .. sp_ic .. (#sp_ic > 0 and "  " or "") .. "\aDEFAULTSpectators"
            local title_sz = measure_text_cached(card.fonts.content, nil, title)

            local p = drag_specs.position + vector(4, 4) * sc
            card.render_rect(p, acc, sp_a, specs_cur_w)
            card.render_text_content(p + vector(specs_cur_w / 2 - title_sz.x / 2 + pad.x / 2, pad.y / 2), card.colors.text.primary:alpha_modulate(255 * sp_a), nil, title)

            local total_rows = 0
            for _, sp in ipairs(specs_list) do total_rows = total_rows + sp.alpha end

            local list_a = anim_specs_list(sp_active)
            local max_w = 0
            local row_idx = 0

            if list_a > 0 then
                card.render_rect(p + vector(0, 30 * sc), acc, list_a * sp_a, specs_cur_w, 16 * sc * total_rows)
                for _, sp in ipairs(specs_list) do
                    local nw = measure_text_cached(card.fonts.content, nil, sp.name).x + 10 * sc
                    local row_p = p + vector(pad.x / 2, 39 * sc + 16 * sc * row_idx)
                    local av = sp.player and sp.player:get_steam_avatar()
                    if not av or av.resolution < 1 then av = default_avatar_tex end
                    if av then
                        render.texture(av, row_p, vector(12, 12) * sc, color(255, 255 * sp.alpha * sp_a), 5 * sc)
                    end
                    card.render_text_content(row_p + vector(16 * sc, 0), card.colors.text.primary:alpha_modulate(255 * sp.alpha * sp_a), nil, sp.name)
                    if max_w < nw and 103 * sc < nw then max_w = nw end
                    row_idx = row_idx + sp.alpha
                end
            end

            specs_cur_w = anim_specs_w(math.max(max_w, 103 * sc))
            drag_specs:update(sp_a, vector(specs_cur_w + pad.x + 8 * sc, 33 * sc))
        end

        -- ============================================================
        -- 10. HOTKEYS (v624 from evalate 2 recode)
        -- ============================================================
        local anim_hk_master = anim_lib()
        local anim_hk_list = anim_lib()
        local anim_hk_w = anim_lib(95, nil, anim_lib.ease_in_out)
        local hk_cur_w = 103
        local hk_cache = {}
        local hk_modes = { [1] = "hold", [2] = "toggle" }

        local function clean_hk_name(s)
            return s:gsub("\aDEFAULT", ""):gsub("\a%b{}", ""):gsub("\a%x%x%x%x%x%x%x%x", ""):gsub("[^%w%s]", ""):gsub("^%s+", ""):gsub("%s+$", "")
        end

        local function render_hotkeys()
            local hk_el = elems.evalate2_keybinds
            local hk_on = elems.evalate2_master:get() and hk_el and hk_el:get()
            local hk_active = false
            local active_binds = {}

            if state.binds then
                for _, b in ipairs(state.binds) do
                    local act = b.active
                    local b_name = clean_hk_name(tostring(b.name))
                    local val = b.value
                    if type(val) == "table" then
                        local firsts = {}
                        for _, item in ipairs(val) do
                            table.insert(firsts, tostring(item):sub(1, 1))
                        end
                        val = #firsts > 0 and table.concat(firsts, ", ") or "?"
                    elseif type(val) == "boolean" then
                        val = hk_modes[b.mode] or "?"
                    end
                    if act then hk_active = true end
                    hk_cache[b_name] = hk_cache[b_name] or { alpha = 0, name = b_name, value = val, animate = anim_lib() }
                    hk_cache[b_name].value = val
                    hk_cache[b_name].alpha = hk_cache[b_name].animate(act)
                    if hk_cache[b_name].alpha > 0 then
                        table.insert(active_binds, 1, hk_cache[b_name])
                    end
                end
            end

            local hk_a = anim_hk_master(hk_on and (hk_active or state.ui_alpha > 0))
            if hk_a <= 0 then return end

            local sc = get_scale()
            local acc = get_accent()
            local pad = card.layout.padding * sc
            local hk_ic = get_safe_icon("brackets-curly")
            if #hk_ic == 0 then hk_ic = get_safe_icon("bars") end
            local title = "\a" .. acc:to_hex() .. hk_ic .. (#hk_ic > 0 and "  " or "") .. "\aDEFAULTHotkeys"
            local title_sz = measure_text_cached(card.fonts.content, nil, title)

            local p = drag_hotkeys.position + vector(4, 4) * sc
            card.render_rect(p, acc, hk_a, hk_cur_w)
            card.render_text_content(p + vector(hk_cur_w / 2 - title_sz.x / 2 + pad.x / 2, pad.y / 2), card.colors.text.primary:alpha_modulate(255 * hk_a), nil, title)

            local total_rows = 0
            for _, b in ipairs(active_binds) do total_rows = total_rows + b.alpha end

            local list_a = anim_hk_list(hk_active)
            local max_w = 0
            local row_idx = 0

            if list_a > 0 then
                card.render_rect(p + vector(0, 30 * sc), acc, list_a * hk_a, hk_cur_w, 16 * sc * total_rows)
                for _, b in ipairs(active_binds) do
                    local n_sz = measure_text_cached(card.fonts.content, nil, b.name)
                    local v_sz = measure_text_cached(card.fonts.content, nil, tostring(b.value))
                    local row_w = n_sz.x + v_sz.x + 10 * sc
                    local row_p = p + vector(0, 39 * sc + 16 * sc * row_idx)
                    card.render_text_content(row_p + vector(pad.x / 2, 0), card.colors.text.primary:alpha_modulate(255 * b.alpha * hk_a), nil, b.name)
                    card.render_text_content(row_p + vector(hk_cur_w + pad.x / 2 - v_sz.x, 0), card.colors.text.primary:alpha_modulate(150 * b.alpha * hk_a), nil, tostring(b.value))
                    if max_w < row_w and 103 * sc < row_w then max_w = row_w end
                    row_idx = row_idx + b.alpha
                end
            end

            hk_cur_w = anim_hk_w(math.max(max_w, 103 * sc))
            drag_hotkeys:update(hk_a, vector(hk_cur_w + pad.x + 8 * sc, 33 * sc))
        end

        -- ============================================================
        -- 11. STACK: SLOW DOWN, FAKE LAG, EXPLOIT (v629 from evalate 2 recode)
        -- ============================================================
        local anim_stack_master = anim_lib()
        local anim_stack_w = anim_lib()
        local anim_sd_vel = anim_lib()
        local anim_sd_alpha = anim_lib()
        local anim_fl_alpha = anim_lib()
        local anim_ex_alpha = anim_lib()
        local anim_ex_def = anim_lib(0, 0.12, anim_lib.ease_in_out)
        local fl_choked_history = {}
        local fl_last_choke_time = 0
        local fl_current_choke = 0

        events.createmove(function(cmd)
            fl_current_choke = cmd.choked_commands
            if fl_current_choke > 3 then fl_last_choke_time = state.realtime end
            table.insert(fl_choked_history, fl_current_choke)
            if #fl_choked_history > 14 then table.remove(fl_choked_history, 1) end
        end)

        local stack_icons = {
            person = get_safe_icon("person"),
            person_running = get_safe_icon("person-running")
        }
        if #stack_icons.person_running == 0 then stack_icons.person_running = stack_icons.person end

        local function render_stack()
            local sd_on = elems.evalate2_master:get() and elems.evalate2_slow_down and elems.evalate2_slow_down:get()
            local fl_on = elems.evalate2_master:get() and elems.evalate2_fake_lag and elems.evalate2_fake_lag:get()
            local ex_on = elems.evalate2_master:get() and elems.evalate2_exploit and elems.evalate2_exploit:get()
            local any_on = sd_on or fl_on or ex_on

            local stack_a = anim_stack_master(any_on and (state.is_alive or state.ui_alpha > 0))
            if stack_a <= 0 then return end

            local sc = get_scale()
            local acc = get_accent()
            local pad = card.layout.padding * sc
            local base_p = drag_stack.position + vector(0, drag_stack.offset) + vector(0, 4 * sc)
            local row_idx = 0
            local max_w = 0

            -- 1. Slow down
            if sd_on then
                local me = state.me
                local vel_mod = anim_sd_vel(me and me.m_flVelocityModifier or 1)
                local sd_a = anim_sd_alpha(sd_on and (vel_mod < 0.99 or state.ui_alpha > 0)) * stack_a
                if sd_a > 0 then
                    local w = 110 * sc
                    local col_bar = (vel_mod >= 0.7 and color():lerp(color(213, 197, 84), (1 - vel_mod) / 0.3) or color(213, 197, 84):lerp(color(255, 0, 0), (0.7 - vel_mod) / 0.7)):alpha_modulate(255 * sd_a)
                    local p_box = base_p - vector(pad.x / 2 + w / 2, 0) + vector(0, 32 * sc * row_idx)
                    card.render_rect(p_box, col_bar, sd_a, w)
                    card.render_text_content(p_box + pad / 2, col_bar, nil, stack_icons.person_running)
                    card.render_text_content(p_box + vector(w + pad.x / 2, pad.y / 2), col_bar, "r", stack_icons.person)
                    local bar_w = w - 23 * sc
                    local prog_w = bar_w * (1 - vel_mod)
                    local p_bar = p_box + vector(25, 11) * sc
                    render.rect(p_bar, p_bar + vector(bar_w, 3 * sc), color(255, 30 * sd_a), 4 * sc)
                    if prog_w > 0 then
                        render.rect(p_bar, p_bar + vector(prog_w, 3 * sc), col_bar, 4 * sc)
                    end
                    if (w + pad.x) > max_w then max_w = w + pad.x end
                    row_idx = row_idx + sd_a
                end
            end

            -- 2. Fake lag
            if fl_on then
                local fl_el = elems.evalate2_fake_lag
                local fl_a = anim_fl_alpha(fl_on and (fl_last_choke_time + 2.5 > state.realtime or state.ui_alpha > 0)) * stack_a
                if fl_a > 0 then
                    local col = acc:alpha_modulate(255 * fl_a)
                    local st_idx = fl_el.style and fl_el.style:get() or 1
                    local fl_ic = get_safe_icon("snowflake")
                    local txt = "\a" .. acc:to_hex() .. fl_ic .. (#fl_ic > 0 and "  " or "") .. "\aDEFAULTFL"
                    local t_sz = measure_text_cached(card.fonts.content, nil, txt)
                    local w = t_sz.x + (st_idx == 1 and 35 or 20) * sc
                    local p_box = base_p - vector(pad.x / 2 + w / 2, 0) + vector(0, 32 * sc * row_idx)
                    card.render_rect(p_box, col, fl_a, w)
                    card.render_text_content(p_box + pad / 2, color(255, 255 * fl_a), nil, txt)

                    if st_idx == 1 then -- Lines
                        for i, chk in ipairs(fl_choked_history) do
                            local bar_h = 8 * (chk / 14) * sc
                            local p_line = p_box + pad / 2 + vector(1 + 2 * i, 0) * sc - vector(0, bar_h / 2) + vector(t_sz.x + 5 * sc, 6 * sc)
                            render.rect(p_line, p_line + vector(1 * sc, bar_h), col)
                        end
                    elseif st_idx == 2 then -- Circle
                        local p_circ = p_box + pad / 2 + vector(t_sz.x + 14 * sc, 6 * sc)
                        local r_out = 9 * (fl_current_choke / 14) * sc
                        render.circle(p_circ, col, 2 * sc, 0, 1)
                        render.circle_outline(p_circ, col, r_out, 0, 1, 1 * sc)
                    end
                    if (w + pad.x) > max_w then max_w = w + pad.x end
                    row_idx = row_idx + fl_a
                end
            end

            -- 3. Exploit
            if ex_on then
                local ex_a = anim_ex_alpha(ex_on and (state.exploit_charge > 0 or state.ui_alpha > 0)) * stack_a
                if ex_a > 0 then
                    local def_factor = anim_ex_def(not state.is_defensive)
                    local col = acc:alpha_modulate(255 * ex_a)
                    local ex_ic = get_safe_icon("wind")
                    local txt = "\a" .. acc:to_hex() .. ex_ic .. (#ex_ic > 0 and "  " or "") .. "\aDEFAULTEX"
                    local t_sz = measure_text_cached(card.fonts.content, nil, txt)
                    local w = t_sz.x + 15 * sc
                    local p_box = base_p - vector(pad.x / 2 + w / 2, 0) + vector(0, 32 * sc * row_idx)
                    card.render_rect(p_box, col, ex_a, w)
                    card.render_text_content(p_box + pad / 2, color(255, 255 * ex_a), nil, txt)
                    local p_ring = p_box + pad / 2 + vector(t_sz.x + 11 * sc, 6 * sc)
                    render.circle_outline(p_ring, color(0, 25 * ex_a), 6 * sc, 0, 1, 2 * sc)
                    render.circle_outline(p_ring, col, 6 * sc, 0, state.exploit_charge * def_factor, 2 * sc)
                    if (w + pad.x) > max_w then max_w = w + pad.x end
                    row_idx = row_idx + ex_a
                end
            end

            local smooth_w = anim_stack_w(max_w + 8 * sc)
            drag_stack:update(stack_a, vector(smooth_w, 33 * sc * row_idx), 16)
        end

        -- ============================================================
        -- 12. CROSSHAIR (v625 from evalate 2 recode)
        -- ============================================================
        local anim_ch_master = anim_lib()
        local anim_ch_dt = anim_lib()
        local anim_ch_hs = anim_lib()
        local anim_ch_dmg = anim_lib()

        local function render_crosshair()
            local ch_el = elems.evalate2_crosshair
            local ch_on = elems.evalate2_master:get() and ch_el and ch_el:get()
            local ch_a = anim_ch_master(ch_on and (state.is_alive or state.ui_alpha > 0))
            if ch_a <= 0 then return end

            local sc = get_scale()
            local acc = get_accent()
            local col = acc:alpha_modulate(255 * ch_a)
            drag_crosshair:update(ch_a, vector(55, 18) * sc, 5)

            local p = vector(drag_crosshair.position.x + 5 * sc * state.anim_scoped, drag_crosshair.position.y + drag_crosshair.offset)
            local row_y = 0

            -- Title & desync bar
            local title_txt = "caelestis"
            local t_sz = measure_text_cached(card.fonts.header, "", title_txt)
            local p_title = vector(p.x - (t_sz.x / 2) * (1 - state.anim_scoped), p.y + row_y)
            render.shadow(p_title + vector(0, 10 * sc), p_title + vector(t_sz.x, 10 * sc), col, 40 * sc)
            card.render_text_header(p_title, col, nil, title_txt)

            local ok_desync, max_desync = pcall(function() return rage.antiaim:get_max_desync() end)
            if ok_desync and max_desync and max_desync > 0 then
                local ok_rot, rot = pcall(function() return rage.antiaim:get_rotation() end)
                local ok_rot_t, rot_t = pcall(function() return rage.antiaim:get_rotation(true) end)
                if ok_rot and ok_rot_t then
                    local desync_delta = math.abs(math.normalize_yaw(rot_t - rot))
                    local factor = math.min(desync_delta, max_desync) / max_desync
                    if factor >= 0.1 then
                        local bar_y = p_title.y + 13 * sc
                        local half_w = t_sz.x / 2
                        local p_mid = vector(p_title.x + half_w, bar_y)
                        local c_fade = col:alpha_modulate(0)
                        render.gradient(p_mid, p_mid - vector(half_w * factor, -1 * sc), col, c_fade, col, c_fade)
                        render.gradient(p_mid, p_mid + vector(half_w * factor, 1 * sc), col, c_fade, col, c_fade)
                    end
                end
            end
            row_y = row_y + 15 * sc

            -- DT Indicator
            local ok_dt, is_dt = pcall(function() return ui.find("Aimbot", "Ragebot", "Main", "Double Tap"):get() end)
            local dt_active = ok_dt and is_dt or false
            local dt_a = anim_ch_dt(dt_active) * ch_a
            if dt_a > 0 then
                local dt_txt = "DT"
                local dt_sz = measure_text_cached(2, "", dt_txt)
                local p_dt = vector(p.x - (dt_sz.x / 2) * (1 - state.anim_scoped) - 4 * sc * (1 - state.anim_scoped), p.y + row_y)
                render.text(2, p_dt, color():alpha_modulate(255 * dt_a), nil, dt_txt)
                local circ_p = p_dt + vector(15, 6) * sc
                render.circle_outline(circ_p, color(0, 50 * dt_a), 3.4 * sc, 0, 1, 1 * sc)
                render.circle_outline(circ_p, color(255, 255 * dt_a), 3.4 * sc, 0, state.exploit_charge, 1 * sc)
                row_y = row_y + 10 * sc
            end

            -- HS Indicator
            local ok_hs, is_hs = pcall(function() return ui.find("Aimbot", "Ragebot", "Main", "Hide Shots"):get() end)
            local hs_active = ok_hs and is_hs or false
            local hs_a = anim_ch_hs(hs_active) * ch_a
            if hs_a > 0 then
                local hs_txt = "HS"
                local hs_sz = measure_text_cached(2, "", hs_txt)
                local p_hs = vector(p.x - (hs_sz.x / 2) * (1 - state.anim_scoped), p.y + row_y)
                render.text(2, p_hs, color():alpha_modulate(255 * hs_a), nil, hs_txt)
                row_y = row_y + 10 * sc
            end

            -- DMG Indicator
            local ok_dmg, is_dmg = pcall(function()
                for _, b in ipairs(state.binds) do
                    if b.name and tostring(b.name):lower():find("damage") and b.active then return true end
                end
                return false
            end)
            local dmg_active = ok_dmg and is_dmg or false
            local dmg_a = anim_ch_dmg(dmg_active) * ch_a
            if dmg_a > 0 then
                local dmg_txt = "DMG"
                local dmg_sz = measure_text_cached(2, "", dmg_txt)
                local p_dmg = vector(p.x - (dmg_sz.x / 2) * (1 - state.anim_scoped), p.y + row_y)
                render.text(2, p_dmg, color():alpha_modulate(255 * dmg_a), nil, dmg_txt)
            end
        end

        -- ============================================================
        -- 13. DAMAGE INDICATOR (v626 from evalate 2 recode)
        -- ============================================================
        local anim_dmg_master = anim_lib()
        local anim_dmg_val = anim_lib(0, 0.1, anim_lib.ease_in_out)
        local font_custom_dmg = render.load_font("arial", vector(11, 9), "a")

        local function render_damage()
            local dmg_el = elems.evalate2_damage
            local dmg_on = elems.evalate2_master:get() and dmg_el and dmg_el:get()
            local dmg_a = anim_dmg_master(dmg_on and (state.is_alive or state.ui_alpha > 0))
            if dmg_a <= 0 then return end

            local sc = get_scale()
            local scr = render.screen_size()
            drag_damage:set_limit(vector(scr.x / 2 - 50, scr.y / 2 - 50), vector(100, 100))

            local cur_min_dmg = 0
            local is_override = false
            pcall(function()
                local d_ref = ui.find("Aimbot", "Ragebot", "Selection", "Min. Damage")
                if d_ref then cur_min_dmg = d_ref:get() or 0 end
                for _, b in ipairs(state.binds) do
                    if b.name and tostring(b.name):lower():find("damage") and b.active then is_override = true break end
                end
            end)

            local smooth_dmg = math.floor(anim_dmg_val(cur_min_dmg))
            local display_dmg = (dmg_el.animate and dmg_el.animate:get()) and smooth_dmg or cur_min_dmg
            local str_dmg = tostring(display_dmg == 0 and "A" or display_dmg)

            local is_always = dmg_el.always_on and dmg_el.always_on:get()
            local col = color():alpha_modulate((is_override and 255 or 50 * (is_always and 1 or state.ui_alpha)) * dmg_a)

            local font_mode = dmg_el.font and dmg_el.font:get() or 1
            local pad_sz = vector(7, 5) * sc
            local m_sz = vector()

            if font_mode == 1 then
                m_sz = measure_text_cached(1, "", str_dmg)
                render.text(1, drag_damage.position + pad_sz / 2, col, nil, str_dmg)
            elseif font_mode == 2 then
                m_sz = measure_text_cached(2, "", str_dmg)
                render.text(2, drag_damage.position + pad_sz / 2, col, nil, str_dmg)
            else
                m_sz = measure_text_cached(font_custom_dmg, "", str_dmg)
                render.text(font_custom_dmg, drag_damage.position + pad_sz / 2, col, nil, str_dmg)
            end

            drag_damage:update(dmg_a, m_sz + pad_sz, 5)
        end

        -- ============================================================
        -- 14. MANUAL ARROWS (v628 from evalate 2 recode)
        -- ============================================================
        local anim_arrows_master = anim_lib()
        local arrows_svg = {
            primed = {
                left = render.load_image("<svg width=\"39\" height=\"45\" viewBox=\"0 0 39 45\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\"> <path d=\"M34.41 1.07819C36.8485 -0.329653 39.7081 2.09415 38.7188 4.73032L32.3794 21.6229C32.1244 22.3024 32.1244 23.0514 32.3794 23.731L38.7188 40.6235C39.7081 43.2597 36.8485 45.6835 34.41 44.2756L1.49996 25.275C-0.500042 24.1203 -0.500043 21.2335 1.49996 20.0788L34.41 1.07819Z\" fill=\"white\"/> </svg>", vector(10, 10)),
                right = render.load_image("<svg width=\"39\" height=\"45\" viewBox=\"0 0 39 45\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\"> <path d=\"M4.58032 44.3833C2.14187 45.7912 -0.717708 43.3674 0.271586 40.7312L6.61098 23.8387C6.866 23.1591 6.866 22.4101 6.61098 21.7306L0.271582 4.83803C-0.717712 2.20186 2.14186 -0.221952 4.58031 1.18589L37.4904 20.1865C39.4904 21.3412 39.4904 24.228 37.4904 25.3827L4.58032 44.3833Z\" fill=\"white\"/> </svg>", vector(10, 10))
            },
            delicate = {
                left = render.load_image("<svg width=\"5\" height=\"10\" viewBox=\"0 0 5 10\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M5 0L2 0L0 4.5L0 5.5L2 10H5L3 5.5L3 5L3 4.5L5 0Z\" fill=\"white\"/></svg>", vector(5, 10)),
                right = render.load_image("<svg width=\"5\" height=\"10\" viewBox=\"0 0 5 10\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M0 10L3 10L5 5.5L5 4.5L3 -1.74846e-07L8.74228e-07 -4.37114e-07L2 4.5L2 5L2 5.5L0 10Z\" fill=\"white\"/></svg>", vector(5, 10))
            }
        }

        local function render_arrows()
            local arr_el = elems.evalate2_arrows
            local arr_on = elems.evalate2_master:get() and arr_el and arr_el:get()
            local arr_a = anim_arrows_master(arr_on and (state.is_alive or state.ui_alpha > 0))
            if arr_a <= 0 then return end

            local sc = get_scale()
            local acc = get_accent()
            drag_arrows:update(arr_a, vector(15, 15) * sc, 4)

            local c_active = acc:alpha_modulate(255 * arr_a)
            local is_always = arr_el.always_on and arr_el.always_on:get()
            local c_inactive = color(0, 75 * (is_always and 1 or state.ui_alpha) * arr_a)

            local manual_dir = "Disabled"
            if ui_structure.antiaim and ui_structure.antiaim.elements and ui_structure.antiaim.elements.manual_yaw then
                manual_dir = ui_structure.antiaim.elements.manual_yaw:get() or "Disabled"
            end

            local is_left = manual_dir == "Left"
            local is_right = manual_dir == "Right"
            local c_l = is_left and c_active or c_inactive
            local c_r = is_right and c_active or c_inactive

            local off = drag_arrows.offset
            local p_center = drag_arrows.position - vector(0, 12 * sc * state.anim_scoped)
            local st_idx = arr_el.style and arr_el.style:get() or 1

            if st_idx == 1 then -- Primed
                local sz = vector(10, 10) * sc
                render.texture(arrows_svg.primed.left, vector(p_center.x - off - 5 * sc, p_center.y - 5 * sc), sz, c_l)
                render.texture(arrows_svg.primed.right, vector(p_center.x + off - 5 * sc, p_center.y - 5 * sc), sz, c_r)
            else -- Delicate
                local sz = vector(5, 10) * sc
                render.texture(arrows_svg.delicate.left, vector(p_center.x - off - 2.5 * sc, p_center.y - 5 * sc), sz, c_l)
                render.texture(arrows_svg.delicate.right, vector(p_center.x + off - 2.5 * sc, p_center.y - 5 * sc), sz, c_r)
            end
        end

        -- ============================================================
        -- 15. MUTUAL EXCLUSION & CONFLICT RESOLUTION (sync_conflicts)
        -- ============================================================
        local function sync_conflicts()
            if self.syncing_locks then return end
            self.syncing_locks = true
            pcall(function()
                local ev_on = elems.evalate2_master and elems.evalate2_master:get() == true

                -- 1. Master switch vs Old Widgets & Old Evalate Suite
                if elems.widgets then
                    if ev_on and elems.widgets:get() then elems.widgets:set(false) end
                    elems.widgets:disabled(ev_on)
                end
                if elems.evalate_master then
                    if ev_on and elems.evalate_master:get() then elems.evalate_master:set(false) end
                    elems.evalate_master:disabled(ev_on)
                end

                -- 2. Watermark
                local ev_wm = ev_on and elems.evalate2_watermark and elems.evalate2_watermark:get() == true
                if elems.widgets_watermark then
                    if ev_wm and elems.widgets_watermark:get() then elems.widgets_watermark:set(false) end
                    elems.widgets_watermark:disabled(ev_wm)
                end

                -- 3. Keybinds
                local ev_kb = ev_on and elems.evalate2_keybinds and elems.evalate2_keybinds:get() == true
                if elems.widgets_keybinds then
                    if ev_kb and elems.widgets_keybinds:get() then elems.widgets_keybinds:set(false) end
                    elems.widgets_keybinds:disabled(ev_kb)
                end

                -- 4. Spectators
                local ev_sp = ev_on and elems.evalate2_spectators and elems.evalate2_spectators:get() == true
                if elems.widgets_spectators then
                    if ev_sp and elems.widgets_spectators:get() then elems.widgets_spectators:set(false) end
                    elems.widgets_spectators:disabled(ev_sp)
                end

                -- 5. Crosshair
                local ev_ch = ev_on and elems.evalate2_crosshair and elems.evalate2_crosshair:get() == true
                if elems.widgets_crosshair then
                    if ev_ch and elems.widgets_crosshair:get() then elems.widgets_crosshair:set(false) end
                    elems.widgets_crosshair:disabled(ev_ch)
                end

                -- 6. Notifications vs on_screen logs
                local ev_nt = ev_on and elems.evalate2_notifications and elems.evalate2_notifications:get() == true
                if elems.log_events and elems.log_events.on_screen then
                    if ev_nt and elems.log_events.on_screen:get() then elems.log_events.on_screen:set(false) end
                    elems.log_events.on_screen:disabled(ev_nt)
                end

                -- 7. Damage Indicator
                local ev_dmg = ev_on and elems.evalate2_damage and elems.evalate2_damage:get() == true
                if elems.damage_indicator then
                    if ev_dmg and elems.damage_indicator:get() then elems.damage_indicator:set(false) end
                    elems.damage_indicator:disabled(ev_dmg)
                end

                -- 8. Manual Arrows
                local ev_arr = ev_on and elems.evalate2_arrows and elems.evalate2_arrows:get() == true
                if elems.manual_arrows then
                    if ev_arr and elems.manual_arrows:get() then elems.manual_arrows:set(false) end
                    elems.manual_arrows:disabled(ev_arr)
                end
            end)
            self.syncing_locks = false
        end

        local watch_elems = {
            elems.evalate2_master, elems.evalate_master, elems.evalate2_watermark, elems.evalate2_keybinds,
            elems.evalate2_spectators, elems.evalate2_notifications, elems.evalate2_crosshair,
            elems.evalate2_damage, elems.evalate2_arrows, elems.widgets,
            elems.widgets_watermark, elems.widgets_keybinds, elems.widgets_spectators,
            elems.widgets_crosshair, elems.damage_indicator, elems.manual_arrows
        }
        for _, wel in ipairs(watch_elems) do
            if wel and wel.set_callback then
                wel:set_callback(sync_conflicts)
            end
        end
        sync_conflicts()

        -- ============================================================
        -- 16. MAIN RENDER LOOP
        -- ============================================================
        events.render(function()
            if not elems.evalate2_master or not elems.evalate2_master:get() then return end
            update_shared_state()

            pcall(render_notifications)
            pcall(render_watermark)
            pcall(render_spectators)
            pcall(render_hotkeys)
            pcall(render_stack)
                        pcall(render_crosshair)
            pcall(render_damage)
            pcall(render_arrows)
        end)
    end
});

local _init_steps = {
    { "home", function() v722.home:init() end },
    { "antiaim", function() v722.antiaim:init() end },
    { "other", function() v722.other:init() end },
    { "watermark", function() v722.watermark:init() end },
    { "sidebar", function() v722.sidebar:init() end },
    { "localplayer", function() v722.localplayer:init() end },
    { "antiaim_data", function() v722.antiaim_data:init() end },
    { "force_break_lc", function() v722.force_break_lc:init() end },
    { "player_animations", function() v722.player_animations:update() end },
    { "fake_lag", function() v722.fake_lag:init() end },
    { "tweaks", function() v722.tweaks:init() end },
    { "safe_head", function() v722.safe_head:init() end },
    { "avoid_backstab", function() v722.avoid_backstab:invoke() end },
    { "presets", function() v722.presets:init() end },
    { "log_events", function() v722.log_events:init() end },
    { "fast_ladder", function() v722.fast_ladder:init(v722) end },
    { "grenades", function() v722.grenades:init(v722) end },
    { "super_toss", function() v722.super_toss = v722.grenades end },
    { "auto_r8", function() v722.auto_r8:init(v722) end },
    { "clock_correction", function() v722.clock_correction:init(v722) end },
    { "max_user_process_ticks", function() v722.max_user_process_ticks:init(v722) end },
    { "warmup_setup", function() v722.warmup_setup:init(v722) end },
    { "no_fall_damage", function() v722.no_fall_damage:init() end },
    { "freezetime_fakeduck", function() v722.freezetime_fakeduck:init() end },
    { "fakeduck_speed", function() v722.fakeduck_speed:init() end },
    { "hitmarkers", function() v722.hitmarkers:init() end },
    { "dormant", function() v722.dormant:init() end },
    { "resolver_optimizer", function() v722.resolver_optimizer:init() end },
    { "microwave_remap", function() v722.microwave_remap:init(v722) end },
    { "ct_agent", function() v722.ct_agent:init() end },
    { "csco_roll", function() v722.csco_roll:init() end },
    { "manual_arrows", function() v722.manual_arrows:init() end },
    { "keep_transparency", function() v722.keep_transparency:invoke() end },
    { "scope_overlay", function() v722.scope_overlay:init() end },
    { "nixer1337", function() v722.nixer1337:init() end },
    { "damage_indicator", function() v722.damage_indicator:init(v722) end },
    { "cvars", function() v722.cvars:run_callbacks() end },
    { "viewmodel", function() v722.viewmodel:init() end },
    { "aspectratio", function() v722.aspectratio:init() end },
    { "clantag", function() v722.clantag:run() end },
    { "clientside_nickname", function() v722.clientside_nickname:run() end },
    { "game_focus", function() v722.game_focus:init() end },
    { "quick_switch", function() v722.quick_switch:init(v722) end },
    { "better_interactions", function() v722.better_interactions:init(v722) end },
    { "fps_optimizer", function() v722.fps_optimizer:init(v722) end },
    { "shared_esp", function() v722.shared_esp:init(v722) end },
    { "auto_kill_t", function() v722.auto_kill_t:init(v722) end },
    { "nade_radius", function() v722.nade_radius:init(v722) end },
    { "visualize_exploits", function() v722.visualize_exploits:init(v722) end },
    { "evalate2_suite", function() v722.evalate2_suite:init(v722) end },
    { "vgui_color", function() v722.vgui_color:init(v722) end },
    { "custom_netgraph_runtime", function() v722.custom_netgraph_runtime:init(v722) end },
    { "hy_widgets", function() v722.hy_widgets:init(v722) end },
    { "evalate_suite", function() v722.evalate_suite:init(v722) end },
    { "zeus_warning", function() v722.zeus_warning:init(v722) end },
    { "avoid_collisions", function() v722.avoid_collisions:init(v722) end },
    { "airstop", function() v722.airstop:init(v722) end },
    { "auto_hide_shots", function() v722.auto_hide_shots:init(v722) end },
    { "auto_dt_discharge", function() v722.auto_dt_discharge:init(v722) end },
    { "aim_tools", function() v722.aim_tools:init(v722) end },
    { "gamesense_indicators", function() v722.gamesense_indicators:init(v722) end },
    { "side_indicators", function() v722.side_indicators:init(v722) end }
}

for _, step in ipairs(_init_steps) do
